window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-10"]={"block":"med:med-clinica-medica-med-clm-10","label":"MED · MED CLM 10","count":486,"questions":[{"id":"med-clinica-medica-med-clm-10-345437","number":"345437","sourceNumber":"345437","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação ao diagnóstico da tuberculose pulmonar e o controle do seu tratamento, a\npesquisa bacteriológica assume um importante papel. Nesse contexto, assinale a alternativa\ncorreta:","options":{"A":"O teste rápido molecular para tuberculose pode ser utilizado para triagem de resistência à\nrifampicina.","B":"A baciloscopia de escarro não é indicada se não houver suspeita clínica, ainda que se tenha\nsuspeita radiológica.","C":"O teste rápido molecular para tuberculose pode ser útil para o diagnóstico em casos de\nretratamento.","D":"A baciloscopia de escarro pode ser realizada em duas amostras, desde que a primeira tenha um\nresultado positivo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-343840","number":"343840","sourceNumber":"343840","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem, 45 anos, com diagnóstico laboratorial confirmado de tuberculose (TB)\npulmonar inicia tratamento com o esquema básico\n(EB) para TB preconizado pelo Ministério da\nSaúde. Os exames laboratoriais no início do tratamento mostraram testes rápidos para HIV,\nhepatite B, hepatite C e sífilis não reagentes, função renal normal e transaminases normais. Um\nmês após o início do tratamento retorna ao atendimento médico devido mal-estar abdominal, está\nictérico ao exame físico. As transaminases estão aproximadamente dez vezes acima do limite\nsuperior de normalidade. Nesta situação, a conduta correta seria:","options":{"A":"Substituir o esquema básico pelo esquema específico para hepatopatas.","B":"Suspender o EB até melhora das transaminases e depois reintroduzir as mesmas drogas de\nforma gradual.","C":"Manter o esquema básico e associar um medicamento hepatoprotetor.","D":"Suspender o EB até melhora das transaminases e depois introduzir um esquema alternativo\npara hepatopatas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-291763","number":"291763","sourceNumber":"291763","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé esquerdo há seis meses. No interrogatório sistemático,\nqueixou-se, também, de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20 mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado retículo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na = 119 mEq/L; e K = 6,1mEq/L,\nnecessitando de internação hospitalar. Diante do caso, Identifique a hipótese diagnóstica principal\nno atendimento inicial.","options":{"A":"Paracoccidioidomicose.","B":"Leishmaniose.","C":"Esporotricose.","D":"Tuberculose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-291764","number":"291764","sourceNumber":"291764","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé esquerdo há seis meses. No interrogatório sistemático,\nqueixou-se, também, de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20 mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado retículo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na = 119 mEq/L; e K = 6,1mEq/L,\nnecessitando de internação hospitalar. Diante do caso, Indique o tratamento de primeira escolha\nda principal hipótese diagnóstica no atendimento inicial.","options":{"A":"Fluconazol.","B":"Itraconazol.","C":"Rifampicina, Isoniazida, Pirazinamida e Etambutol.","D":"Glucantime."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-281101","number":"281101","sourceNumber":"281101","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à tuberculose pleural, analise as seguintes afirmativas: I - Ocorre\ngeralmente entre três e seis anos após a infecção\nprimária; II - O exame físico do tórax mostra\nmacicez e aumento do frêmito toracovocal na área do derrame pleural; III - Ocorre por extensão\ndireta do foco caseoso pulmonar subpleural ou por disseminação hematogênica. Está ou estão\nCORRETA(S) a(s) afirmativa(s):","options":{"A":"I, II e III.","B":"II, apenas.","C":"I, apenas.","D":"III, apenas.","E":"I e II, apenas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-283298","number":"283298","sourceNumber":"283298","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em virtude da dificuldade de isolamento do bacilo da tuberculose nas crianças\ninfectadas, o Ministério da Saúde recomenda\num score para o diagnóstico, o qual considera todos\nos itens abaixo, EXCETO:","options":{"A":"Estado nutricional.","B":"Contato com adulto tuberculoso.","C":"Teste tuberculínico.","D":"Baciloscopia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-247177","number":"247177","sourceNumber":"247177","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase abaixo. No derrame\npleural por tuberculose, habitualmente se encontra:","options":{"A":"Desidrogenase lática em valores acima de 1.000 U/L.","B":"Proteínas em valores baixos, podendo caracterizar transudato.","C":"Predomínio linfomonocitário na celularidade específica.","D":"Presença do Mycobacterium tuberculosis na maioria dos casos.","E":"Líquido pleural purulento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-251909","number":"251909","sourceNumber":"251909","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em uma discussão de caso clínico com a equipe da Unidade Básica de Saúde do Rui\nLino, aborda-se algumas situações sobre a avaliação dos contatos domiciliares de pacientes TB\npulmonares com baciloscopia positiva. Sobre esse assunto, assinale a afirmativa INCORRETA.","options":{"A":"No adulto sintomático com exame de escarro positivo, a conduta inicial é a orientação. Caso o\nraio X seja sugestivo de TB, é indicado o tratamento.","B":"No adulto assintomático e no adulto sintomático com exame de escarro negativo, a conduta é a\norientação.","C":"Nas crianças de até 15 anos, não vacinadas, realiza-se a PPD. Caso seja reator a PPD,\n\nrealiza-se raio X de tórax. Caso o raio X seja sugestivo de TB e tenha sintomas clínicos, é indicado\ntratamento.","D":"Nas crianças de até 15 anos, vacinadas e sintomáticas, realiza-se raios-X de tórax. Com exame\nnormal e sem sintomas clínicos, realizam-se orientação e medicação sintomática e é feito\nacompanhamento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-251914","number":"251914","sourceNumber":"251914","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em uma saúde itinerante em Feijó, a equipe multiprofissional discute sobre a\nquimioprofilaxia da TB, referente a alguns\ncasos atendidos. Sobre esse assunto, analise as\nalternativas abaixo: I. Nas grávidas, a quimioprofilaxia deve ser iniciada no terceiro trimestre da\ngestação. II. Nos índios, recomenda-se que todo contato de TB bacilífero, forte reator à PPD\n(>10mm), independentemente da idade e do estado vacinal, após avaliação clínica e afastada a\npossibilidade de TB doença por meio de baciloscopia e exame radiológico, receba terapia\npreventiva. III. Na quimioprofilaxia primária, administra-se isoniazida em pessoas não infectadas\npara prevenir a infecção. IV. Na quimioprofilaxia secundária, administra-se isoniazida em pessoas\njá infectadas pelo Mtb, mas sem sinais de doença, para prevenir a evolução da infecção à doença.\nConsiderando as alternativas a cima, assinale a afirmativa CORRETA.","options":{"A":"Apenas I e III.","B":"Apenas I e IV.","C":"Apenas II, III e IV.","D":"I, II, III e IV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-247235","number":"247235","sourceNumber":"247235","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com 20 anos de idade procurou pronto-socorro com história de pele\namarelada e vômitos. Refere estar em\ntratamento há 10 dias, na UBS, por tuberculose pulmonar\nbacilífera. Ao exame: PA= 80x40 mmHg e FC= 130 bpm. O plantonista indicou internação. Com\nrelação ás normas de biossegurança, qual a melhor conduta?","options":{"A":"Paciente em quarto com isolamento e profissionais de saúde usando máscara cirúrgica.","B":"Paciente em quarto com isolamento e profissionais de saúde usando máscara respiratória (M95).","C":"Paciente em quarto comum e profissionais de saúde usando máscara respiratória (M95).","D":"Paciente em quarto com isolamento e paciente usando máscara respiratória (M95).","E":"Não há necessidade de isolamento desse paciente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-217739","number":"217739","sourceNumber":"217739","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O Ministério da Saúde prevê atualmente o tratamento da ILTB (infecção latente pelo\nMycobacterium tuberculosis), independente da realização do PPD (prova tuberculínica) ou do IGRA\n(Interferon Gamma Release Assay) em todos as situações abaixo citadas, EXCETO em:","options":{"A":"Portadores de HIV com contagem de células CD4+ menor ou igual a 350 células/µl.","B":"Recém-nascidos coabitantes de caso-fonte confirmado por critério laboratorial.","C":"Adultos vacinados com BCG que sejam contactantes de pessoa com tuberculose pulmonar\nbacilífera.","D":"Pessoas vivendo com HIV contatos de TB pulmonar com confirmação laboratorial."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-217669","number":"217669","sourceNumber":"217669","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O Brasil está inserido no grupo de 22 países que concentram 80% dos casos de\nTuberculose (TB) no mundo. A doença é frequente em áreas de grande concentração humana e\ncom precários serviços de infraestrutura urbana. Marque a assertiva CORRETA com relação à TB\nna criança:","options":{"A":"Crianças que receberam BCG ao nascer estão protegidas contra a infecção por Mycobacterium\ntuberculosis.","B":"A forma mais frequente de TB extrapulmonar na infância é a TB pleural.","C":"Preconiza-se tratar TB em pré-escolares com rifampicina, isoniazida, pirazinamida e etambutol.","D":"Suspeita-se de TB pulmonar em crianças com pneumonia com evolução ? 2 semanas, sem\nresposta a antimicrobianos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-182647","number":"182647","sourceNumber":"182647","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose (TB) é uma doença infecciosa de grande impacto no Brasil. O manejo na\nmaioria das vezes é fácil, porém há situações que exigem conhecimento mais aprofundado do\nmédico assistente para o êxito no tratamento do paciente. Com relação à TB, considere as\nafirmativas abaixo: I. É possível tratar empiricamente TB pulmonar em pacientes com pesquisa de\nBAAR negativa, que apresentem quadro clínico-radiológico sugestivo da doença, associado à\nreatividade do PPD; II. Considera-se TB multirresistente quando o teste de sensibilidade evidenciar\nresistência concomitantemente à Rifampicina e Estreptomicina; III. Pacientes com cirrose hepática\nque sejam portadores de TB deverão ser tratados com esquema terapêutico composto por\nestreptomicina, etambutol e ofloxacina; IV. Constitui-se em indicação para realizar cultura para\nmicobactérias no escarro: pesquisa de BAAR positiva em paciente que iniciou tratamento há mais\nde 60 dias.; V. A vacina BCG tem como finalidade evitar a infecção pelo Mycobacterium\ntuberculosis; Estão CORRETAS:","options":{"A":"II, IV.","B":"I, II, V.","C":"I, III, IV.","D":"II, III, IV, V."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-182640","number":"182640","sourceNumber":"182640","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Escolar de 8 anos, vem à consulta em posto de saúde, com tosse produtiva há mais de\n3 semanas, PPD de 6mm, com imagem radiológica\nmantida após tratamento com amoxicilina,\nusada pensando-se no diagnóstico de pneumonia comunitária. O avô materno está em tratamento\npara Tuberculose (TB) pulmonar há 4 meses. A conduta adequada nesse caso é iniciar:","options":{"A":"Tratamento para pneumonia atípica usando um macrolídeo, reavaliar depois de 2 meses. Não\nhavendo melhoras, avaliar início de tratamento\npara TB pulmonar.","B":"Tratamento com esquema básico para TB com quatro drogas (2RHZE/4RH).","C":"Tratamento com esquema básico para TB com três drogas (2RHZ/4RH).","D":"Quimioprofilaxia para TB com isoniazida."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-135909","number":"135909","sourceNumber":"135909","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"LFG, 24 anos, gestante de 22 semanas, procura atendimento na maternidade devido a\numa quadro de febre elevada, artralgia, mialgia, cefaleia, astenia e náuseas há 4 dias e exantema\nhá 1 dia. No hemograma evidenciou-se Hb 11,8 g/dL, HT 35,4%, leucócitos totais 3.200/mm³,\nplaquetas 102.000/mm³. Exames bioquímicos: AST 50, ALT 63, BT: 1,0, ureia 24, creatinina 0,8.\n\nCom relação a esse caso está INCORRETO afirmar:","options":{"A":"Dentre outros, rubeóla, dengue, chikungunya e zika vírus deverão ser investigados;","B":"Supondo-se que dengue seja a principal possibilidade diagnóstica, a hidratação é fundamental;","C":"Se a principal hipótese for febre por chikungunya os anti-inflamatórios não hormonais estão\nindicados na fase aguda visando reduzir a intensa artralgia.","D":"Caso a principal hipótese seja febre pelo zika vírus o concepto deverá ser acompanhado de\nforma periódica para identificação de possível microcefalia"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-135949","number":"135949","sourceNumber":"135949","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"HGB, 54 anos, masculino, lavrador relata que há aproximadamente 4 meses notou\nsurgimento de lesão ulcerada no septo\nnasal. Referiu leishmaniose tegumentar americana forma\ncutânea lesão única na perna esquerda há 3 anos, que desapareceu espontaneamente. O raspado\nda lesão ulcerada atual revelou a presença de rara amastigotas. Intradermorreação de Montenegro\npositiva. Hemograma, função renal, função hepática e avaliação pancreática normais. Com relação\na esse caso está CORRETO afirmar que a primeira opção de tratamento é:","options":{"A":"Glucantime por 20 dias consecutivos, porém necessita de avaliação cardiológica prévia e\ndurante o tratamento;","B":"Anfotericina B por 20 dias consecutivos, havendo necessidade de avaliação cardiológica prévia\ne durante o tratamento;","C":"Glucantime por 30 dias consecutivos, porém necessita de avaliação cardiológica prévia e\ndurante o tratamento;","D":"Anfotericina B lipossomal por 30 dias consecutivos, sem necessidade de avaliação cardiológica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-108728","number":"108728","sourceNumber":"108728","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Qual das condições abaixo relacionadas, se detectada isoladamente em um paciente\ncom suspeita de dengue, NÃO tem indicação de\ninternação hospitalar?","options":{"A":"Prova do laço positiva;","B":"Plaquetometria de 15.000/mm³;","C":"Hepatomegalia dolorosa;","D":"Aumento repentino do hematócrito."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-108816","number":"108816","sourceNumber":"108816","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre a febre chikungunya, até a Semana Epidemiológica 47 foram notificados 2.597\ncasos autóctones suspeitos no Brasil. Destes,\n251 foram descartados, 1.425 foram confirmados,\nsendo 54 por critério laboratorial e 1.371 por critério clínico-epidemiológico e 727 continuam em\ninvestigação. Caracterizada a transmissão sustentada de febre de chikungunya em uma\ndeterminada área, com a confirmação laboratorial dos primeiros casos, o Ministério da Saúde\nrecomenda que os demais casos sejam confirmados por critério clínico-epidemiológico. Assinale a\nopção abaixo que representa corretamente o critério clínico-epidemiológico da febre chikungunya.","options":{"A":"Todos os casos de pessoas com febre no Estado do Amapá devem ser considerados\nconfirmados pelo critério clínico-epidemiológico para a febre de chikungunya;","B":"Casos de pessoas com febre e poliartralgia em locais onde há casos comprovados\nlaboratorialmente devem ser considerados\nconfirmados pelo critério clínico-epidemiológico;","C":"O critério clínico-epidemiológico é aplicado solicitando-se exames sorológicos para todos os\ncasos suspeitos independente de ter ou não casos\nconfirmados na localidade;","D":"Só são confirmados por critério clínico-epidemiológico aqueles que tiveram quadro de\ncomplicação hemorrágica da doença."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-84547","number":"84547","sourceNumber":"84547","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente, feminino, 16 anos de idade é trazida por sua mãe ao atendimento de\nurgência. Mãe da menor disse que há dois\ndias notou que sua filha começou a apresentar febre e\nreclamou de dor no corpo e ao redor dos olhos. Estava administrando por conta própria dipirona à\npaciente. Hoje ao chegar em casa depois do trabalho ficou assustada, pois notou que havia\nmanchas vermelhas de tamanho muito pequeno distribuídas pelas pernas da menor. Menor nega\noutras queixas e comorbidades. Não faz uso regular de nenhum medicamento. Há vários casos de\ndengue entre os alunos da mesma escola da menor. Ao exame físico: BEG, LOTE, normocorada,\nacianótica, anictérica, eupneica, sem edemas, manchas vermelhas que não desaparecem à\ndigitopressão. FR = 16 imp, Pulso cheio = 88 bpm, PA = 110 x 70 mmHg, TA = 36,2ºC. Ausculta\npulmonar = MV universalmente audível sem ruídos adventícios. Ausculta cardíaca = BCNF, RCR\nem dois tempos, sem sopros. Abdome = inspeção, ausculta, percussão e palpação sem alterações.\nExame neurológico normal. Peso corporal: 59 kg. Foi solicitado hemograma (VER IMAGEM). Nesta\nsituação, pensando na hipótese diagnóstica de dengue, pode-se afirmar:","options":{"A":"O estadiamento desta paciente neste momento é grupo C.","B":"Esta paciente possui critério de internação.","C":"Uma falha no atendimento desta paciente foi a não realização da prova do laço.","D":"O volume de hidratação diário para essa paciente deverá ser em torno de 6 litros.","E":"Todas as alternativas anteriores estão corretas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/84547.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-67012","number":"67012","sourceNumber":"67012","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"M.F.S., de 18 anos, sexo masculino, procedente da zona rural de Feijó, procura\natendimento no PSF (Programa de Saúde da\nFamília) do Universitário, com queixa de cefaleia\nfrontal pulsátil, dor retro-orbitária há 3 dias, e há um dia vem apresentando náuseas, vômitos (2\nepisódios) e deposições líquidas sem sangue (3 episódios). Usam água de cacimba e não têm\nsaneamento básico. Refere esquema vacinal completo e antecedente de hepatite \"A\" aos 15 anos,\nseu pai e seu irmão mais velho são portadores de HBV, sua mãe tem hepatopatia a esclarecer. No\nmomento da consulta encontrava-se febril (38,7°C) ictérico +\\4+, acianótico desidratado,\nhipocorado(+|4+), eupneico. Cardiopulmonar e abdome sem alterações. Hemograma= eritrócitos\n3.980/mm³, Hb 10 g/dl, Ht 35%, leucócitos 19.900/mm³, neutrófilos 82%, bastões 5 %, linfócitos\n13%, plaquetas 90.000/mm³, ureia 60, creatina 1,5, Bilirrubina total 3,9; BD 2,0,; 1,9; TGO 105;\nGGT 102; FAL 180; CPK 160; potássio sérico baixo. O diagnóstico mais provável é:","options":{"A":"Dengue;","B":"Malária;","C":"Febre amarela;","D":"Leptospirose;"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-66953","number":"66953","sourceNumber":"66953","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Atualmente no Brasil, o tratamento da malária por Plasmodium falciparum em um\nindivíduo adulto, sexo masculino, sem comorbidades, que não curse com nenhuma manifestação\nque indique gravidade, deverá ser preferencialmente com a:","options":{"A":"Combinação de artemeter e mefloquina por via oral;","B":"Associação de cloroquina e artesunato por via oral;","C":"Combinação de quinino e mefloquina por via oral;","D":"Cloroquina por via oral isoladamente;"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-66959","number":"66959","sourceNumber":"66959","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Todos abaixo são critérios que servem para classificar um caso confirmado de dengue\ncomo \"Síndrome Hemorrágica da Dengue\", EXCETO:","options":{"A":"Contagem de plaquetas < 100.000/mm³ de sangue;","B":"Presença de qualquer sinal de alarme;","C":"Manifestações hemorrágicas;","D":"Sinais de extravasamento plasmático;"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-66969","number":"66969","sourceNumber":"66969","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Todos abaixo se constituem em sinais de alarme na dengue, EXCETO:","options":{"A":"Dor abdominal intensa e contínua;","B":"Plaquetopenia;","C":"Hipotensão postural;","D":"Desconforto respiratório;"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-37076","number":"37076","sourceNumber":"37076","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação ao manejo clínico da malária grave, é correto afirmar, EXCETO:","options":{"A":"A heparina e os glicocorticoides possuem papel central na terapêutica.","B":"É a indicação principal para o uso de derivados da artemisinina.","C":"O choque deve ser tratado com reposição hídrica cuidadosa.","D":"O desenvolvimento de SARA é indicação para assistência ventilatória com PEEP.","E":"Medidas contra o edema cerebral (ex.: manitol) não são úteis no coma malárico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-37050","number":"37050","sourceNumber":"37050","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente feminina de 19 anos, grávida de 2 semanas procedente de Cruzeiro do Sul,\nprocura atendimento em uma unidade de saúde da família no bairro onde vive sua mãe, com um\nquadro de febre não qualificada, calafrio, cefaleia, mialgia, em seus exames laboratoriais que havia\nrealizado em um serviço de Pronto Atendimento, apresenta Malária por P. vivax (+). Qual o\ntratamento adequado pelo médico de família e comunidade?","options":{"A":"Cloroquina + Primaquina.","B":"Mefloquina.","C":"Primaquina.","D":"Cloroquina.","E":"Quilina + doxiciclina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-29348","number":"29348","sourceNumber":"29348","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Visando o tratamento da malária falciparum não grave nem complicada em pacientes\nadultos do sexo masculino, o Ministério da Saúde preconiza como primeira escolha o uso de:","options":{"A":"Combinação de artemether com lumefantrine (COARTEM)","B":"Combinação de artesunato com mefloquina","C":"Associação de quinino e doxicilina","D":"As alternativas a e b estão corretas","E":"As alternativas a, b e c estão corretas"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-29350","number":"29350","sourceNumber":"29350","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Conhecendo a razão pela qual se realiza a prova do laço em um paciente com suspeita\nde dengue, qual a única situação em que ela deve\nser dispensada? Pacientes...","options":{"A":"Menores de 1 ano de idade","B":"Cardiopatas","C":"Com manifestações hemorrágicas espontâneas","D":"Com insuficiência renal crônica","E":"Grávidas"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-343158","number":"343158","sourceNumber":"343158","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma boa amostra de escarro:","options":{"A":"É a que provém da árvore brônquica, obtida sem o esforço de tosse, e não a que se obtém da\nfaringe ou por aspiração de secreções nasais, tampouco a que contém somente saliva.","B":"É a que provém da árvore brônquica, obtida após esforço de tosse, e não a que se obtém da\nfaringe, mas nunca por aspiração de secreções nasais, tampouco a que contém somente saliva.","C":"É a que provém da árvore brônquica, obtida após esforço de tosse, e não a que se obtém da\nfaringe ou por aspiração de secreções nasais, melhor a que contém somente saliva.","D":"É a que provém da árvore brônquica, obtida após esforço de tosse, e não a que se obtém da\nfaringe ou por aspiração de secreções nasais, tampouco a que contém somente saliva."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-343165","number":"343165","sourceNumber":"343165","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em PVHIV, o acometimento ganglionar da Tuberculose tende a ser bilateral, associado\ncom maior comprometimento do estado geral.","options":{"A":"Ao exame físico, os gânglios podem apresentar-se endurecidos e nunca amolecidos, aderentes\nentre si e aos planos profundos, podendo\nevoluir para flutuação e/ou fistulização espontânea, com\na inflamação da pele adjacente.","B":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, não aderentes\nentre si e aos planos profundos, podendo\nevoluir para flutuação e/ou fistulização espontânea, com\na inflamação da pele adjacente.","C":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, aderentes entre\nsi e aos planos profundos, podendo evoluir\npara flutuação e/ou fistulização espontânea, com a\ninflamação da pele adjacente.","D":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, aderentes entre\nsi e aos planos profundos, podendo evoluir\npara flutuação, mas não para fistulização espontânea,\ncom a inflamação da pele adjacente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-343168","number":"343168","sourceNumber":"343168","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Outra forma de TB do sistema nervoso central é a forma localizada (tuberculomas).\nPodemos indicar como correto o item:","options":{"A":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento rápido , com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode\nnão estar presente.","B":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre sempre\ndeve estar presente.","C":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode não\nestar presente.","D":"Nessa apresentação, o quadro clínico não é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode não\nestar presente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-343221","number":"343221","sourceNumber":"343221","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A rotina radiográfica básica em pacientes com suspeita de tuberculose inclui o uso das\nincidências posteroanteriores e perfil esquerdo.","options":{"A":"A radiografia apicolordótica (incidência de Fleischner) poderá complementar a rotina nos casos\nem que há dúvidas na interpretação dos\nápices pulmonares.","B":"A radiografia apicolordótica (incidência de Fleischner) nunca poderá complementar a rotina nos\ncasos em que há dúvidas na interpretação dos\nápices pulmonares.","C":"A radiografia apicolordótica (incidência de Fleischner) poderá complementar a rotina, mas não\nnos casos em que há dúvidas na interpretação\ndos ápices pulmonares.","D":"A radiografia apicolordótica (incidência de Fleischner) poderá complementar a rotina nos casos\nem que há dúvidas na interpretação das bases\npulmonares."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-343224","number":"343224","sourceNumber":"343224","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"As alterações radiográficas da Tuberculose Pulmonar:","options":{"A":"Podem ser abordadas considerando as seguintes situações: tuberculose primária e tuberculose\nsecundária ou de reinfecção.","B":"Podem ser abordadas considerando as seguintes situações: tuberculose primária e tuberculose\nsecundária, mas não de reinfecção.","C":"Podem ser abordadas considerando apenas tuberculose secundária.","D":"Podem ser abordadas considerando apenas a tuberculose primária."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-314194","number":"314194","sourceNumber":"314194","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A atuação dos medicamentos anti-TB difere conforme o metabolismo bacilar. Sendo\ncorreto o item:","options":{"A":"Na população intramacrofágica, agem os fármacos que melhor se difundem no meio intracelular\ne em pH alcalino: rifampicina, pirazinamida e\netambutol.","B":"Na população intramacrofágica, agem os fármacos que melhor se difundem no meio intracelular\ne em pH ácido: rifampicina, pirazinamida e\netambutol.","C":"Na população intramacrofágica, agem os fármacos que pior se difundem no meio intracelular e\nem pH ácido: rifampicina, pirazinamida e etambutol.","D":"Na população intramacrofágica, não agem os fármacos que melhor se difundem no meio\nintracelular e em pH ácido: rifampicina, pirazinamida e etambutol."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-314197","number":"314197","sourceNumber":"314197","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Nas lesões caseosas fechadas da tuberculose, podemos indicar como correto o item:","options":{"A":"O fármaco menos efetivo é a rifampicina, sendo a ação da isoniazida mais lenta e demorada.","B":"O fármaco mais efetivo é a rifampicina, sendo a ação da isoniazida mais lenta e demorada.","C":"O fármaco mais efetivo é a rifampicina, sendo a ação da isoniazida mais rápida.","D":"O fármaco não é a rifampicina, sendo a ação da isoniazida mais lenta e demorada."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-314232","number":"314232","sourceNumber":"314232","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Considerando então a necessidade de intensificar a busca de pessoas com Infecção\nLatente pelo Mycobacterium tuberculosis (ILTB),\nampliando a solicitação de exames diagnósticos e\ndo tratamento nos serviços de saúde, podemos concordar que:","options":{"A":"Reduzindo o conhecimento do perfil epidemiológico da Infecção Latente pelo Mycobacterium\ntuberculosis (ILTB) no país, apresentar as\nestratégias de fortalecimento e ampliação da vigilância\nda ILTB no Brasil.","B":"Aumentando o conhecimento do perfil epidemiológico da Infecção Latente pelo Mycobacterium\ntuberculosis (ILTB) no país, apresentar as\nestratégias de fortalecimento e redução da vigilância da\nILTB no Brasil.","C":"Aumentando o conhecimento do perfil epidemiológico da Infecção Latente pelo Mycobacterium\ntuberculosis (ILTB) no país, apresentar as estratégias de fortalecimento e ampliação da vigilância\nda ILTB no Brasil.","D":"Aumentando o conhecimento do perfil epidemiológico da Infecção Latente pelo Mycobacterium\ntuberculosis (ILTB) no país, e não apresentar as estratégias de fortalecimento e ampliação da\nvigilância da ILTB no Brasil."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-315210","number":"315210","sourceNumber":"315210","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O esquema de tratamento da tuberculose pulmonar é adotado em duas fases distintas:\num fase de ataque seguida por uma fase de\nmanutenção. Qual dentre os tratamentos abaixo é\npadronizado pelo ministério da saúde para tratamento da tuberculose pulmonar no Brasil?\n\nRifanpicina ? R. Isoniazida ? H. Pirazidamida ? P. Etambutol ? E.","options":{"A":"R, H ( 2 meses) e P,E ( 2 meses)","B":"R,H,P ( 3 meses) e P,E ( 2 meses)","C":"R,H,P,E (2 meses) e R,H ( 4 meses)","D":"R,H,P,E (4 meses) e R,H ( 2 meses)","E":"Nenhuma das alternativas"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-283718","number":"283718","sourceNumber":"283718","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé\nesquerdo há seis meses. No interrogatório sistemático,\nqueixou-se também de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado reticulo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na: 119mEq/L e K: 6,1mEq/L, necessitando de\ninternação hospitalar. Diante do caso. Identifique a hipótese diagnóstica principal no atendimento\ninicial.","options":{"A":"Paracoccidioidomicose.","B":"Leishmaniose.","C":"Esporotricose.","D":"Tuberculose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-283719","number":"283719","sourceNumber":"283719","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé\nesquerdo há seis meses. No interrogatório sistemático,\nqueixou-se também de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado reticulo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na: 119mEq/L e K: 6,1mEq/L, necessitando de\ninternação hospitalar. Diante do caso. Indique o tratamento de primeira escolha da principal\nhipótese diagnóstica no atendimento inicial.","options":{"A":"Fluconazol.","B":"Itraconazol.","C":"Rifampicina, Isoniazida, Pirazinamida e Etambutol.","D":"Glucantime."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-283720","number":"283720","sourceNumber":"283720","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé\nesquerdo há seis meses. No interrogatório sistemático,\nqueixou-se também de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado reticulo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na: 119mEq/L e K: 6,1mEq/L, necessitando de\ninternação hospitalar. Diante do caso. Indique a hipótese diagnóstica principal diante da\ncomplicação apresentada posteriormente.","options":{"A":"Doença de Addison.","B":"Síndrome de Cushing.","C":"Síndrome perdedora de sal.","D":"Síndrome de secreção inapropriada de hormônio antidiurético."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-280460","number":"280460","sourceNumber":"280460","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A associação do nódulo de Ghon e linfonodomegalias hilares na tuberculose é\ndenominada Complexo de Ranke. Sobre isso, está correto que:","options":{"A":"Esses nódulos são potencialmente focos de bacilos, que nunca podem evoluir para a cura, com\nfibrose e calcificação, ou para a doença.","B":"Esses nódulos são potencialmente focos de bacilos, que podem evoluir para a cura, com fibrose\ne calcificação, e não para a doença.","C":"Esses nódulos são potencialmente focos de bacilos, que jamais podem evoluir para a cura, com\nfibrose e calcificação, e sempre para a doença.","D":"Esses nódulos são potencialmente focos de bacilos, que podem evoluir para a cura, com fibrose\ne calcificação, ou para a doença."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-278671","number":"278671","sourceNumber":"278671","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Intervenções direcionadas aos determinantes socioeconômicos podem contribuir na\nmelhoria do controle da TB no Brasil, sendo adequado o item:","options":{"A":"Erradicar a pobreza, em todas as suas formas e dimensões, excluindo a pobreza extrema,\naparece como requisito indispensável para o\ndesenvolvimento sustentável.","B":"Erradicar a pobreza, em todas as suas formas e dimensões, incluindo a pobreza extrema,\naparece como requisito indispensável para o\ndesenvolvimento não sustentável.","C":"Erradicar a pobreza, em todas as suas formas e dimensões, incluindo a pobreza extrema,\naparece como requisito dispensável para o\ndesenvolvimento sustentável.","D":"Erradicar a pobreza, em todas as suas formas e dimensões, incluindo a pobreza extrema,\naparece como requisito indispensável para o\ndesenvolvimento sustentável."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-280461","number":"280461","sourceNumber":"280461","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A obstrução brônquica total ou parcial na tuberculose pode ocasionar atelectasias, que\nsão visualizadas na radiografia e na TC de tórax.\nPodemos assim concordar com o item:","options":{"A":"O aumento de linfonodos mediastinais não pode ocasionar compressão dos brônquios e lesão\nda parede brônquica com drenagem do material necrótico para dentro da luz brônquica (TB\nendobrônquica).","B":"O aumento de linfonodos mediastinais pode ocasionar compressão dos brônquios e lesão da\nparede brônquica com drenagem do material necrótico para fora da luz brônquica (TB\nendobrônquica).","C":"O aumento de linfonodos mediastinais pode ocasionar compressão dos brônquios e lesão da\nparede brônquica com drenagem do material necrótico para dentro da luz brônquica (TB\nendobrônquica).","D":"O aumento de linfonodos mediastinais não pode ocasionar compressão dos brônquios e lesão\nda parede brônquica sem drenagem do material necrótico para dentro da luz brônquica (TB\nendobrônquica)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-280465","number":"280465","sourceNumber":"280465","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para idosos com tuberculose, podemos determinar como correto o item:","options":{"A":"É raro o acometimento dos segmentos inferiores, assim como menor ocorrência de cavidades,\ndificultando ainda mais o diagnóstico nessa faixa etária.","B":"É comum o acometimento dos segmentos inferiores, assim como menor ocorrência de\ncavidades, facilitando o diagnóstico nessa faixa etária.","C":"É comum o acometimento dos segmentos inferiores, assim como menor ocorrência de\ncavidades, dificultando ainda mais o diagnóstico nessa faixa etária.","D":"É comum o acometimento dos segmentos inferiores, assim como maior ocorrência de\ncavidades, dificultando ainda mais o diagnóstico nessa faixa etária."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-280466","number":"280466","sourceNumber":"280466","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A presença de bacilos ou proteínas do bacilo decorrente de disseminação\nhematogênica e/ou linfática ou contato\nanatômico do bacilo da tuberculose, pode levar a situação\ndescrita corretamente no item:","options":{"A":"Pode acometer a pleura e/ou o pericárdio, com consequente derrame pleural e, menos\nfrequentemente, derrame pericárdico.","B":"Pode acometer a pleura, mas não o pericárdio, com consequente derrame pleural e, menos\nfrequentemente, derrame pericárdico.","C":"Pode acometer a pleura e/ou o pericárdio, com consequente derrame pleural e, nunca com\nderrame pericárdico.","D":"Pode acometer a pleura e/ou o pericárdio, com consequente derrame pleural e, menos\nfrequentemente, miocardite."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-279097","number":"279097","sourceNumber":"279097","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A cintilografia pulmonar ventilação-perfusão pode ser útil na avaliação pré-operatória de\npacientes com indicação de cirurgia para tratamento da tuberculose, sendo adequado o item:","options":{"A":"Porém, não identificando áreas com déficit ventilatório e/ou perfusional.","B":"Identificando áreas com déficit ventilatório e não do perfusional.","C":"Identificando áreas com déficit apenas perfusional.","D":"Identificando áreas com déficit ventilatório e/ou perfusional."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-278678","number":"278678","sourceNumber":"278678","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No Brasil, observou-se uma expansão em ações relacionadas à educação, saúde,\nemprego, habitação, seguridade social e\ndesenvolvimento social durante os últimos 40 anos. Desse\nmodo, os progressos nos determinantes sociais da saúde têm tido um efeito na saúde dos\nbrasileiros. Podemos concordar que:","options":{"A":"A transmissão e adoecimento por TB são influenciados por fatores demográficos, sociais e\neconômicos.","B":"A transmissão e adoecimento por TB não são influenciados por fatores demográficos, sociais e\neconômicos.","C":"A transmissão e não o adoecimento por TB são influenciados por fatores demográficos, sociais e\neconômicos.","D":"A transmissão e adoecimento por TB não são influenciados por fatores demográficos, sociais,\nsomente por econômicos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-279099","number":"279099","sourceNumber":"279099","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Podemos indicar como inadequado a respeito de Tuberculose TB óssea o seguinte\nitem:","options":{"A":"Na TB óssea, a destruição da porção anterior dos corpos vertebrais e áreas de osteólise,\nprincipalmente em epífise de ossos longos, sugere doença em atividade.","B":"O acometimento de tecidos moles adjacentes, como abscessos para vertebrais visualizados na\nRNM, também sugere doença ativa.","C":"A involução desses achados adjacentes às alterações ósseas na RNM é útil no\nacompanhamento da doença e pode, em conjunto\ncom critérios clínicos, definir a alta do tratamento\ndas formas ósseas.","D":"Na TB óssea, a destruição da porção anterior dos corpos vertebrais e áreas de osteólise,\nprincipalmente em epífise de ossos longos, sugere doença em regressão."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-279102","number":"279102","sourceNumber":"279102","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Determinado a partir desse foco inicial, pode ocorrer a progressão para necrose\ncaseosa, eliminação do material necrótico e\ndisseminação broncogênica da tuberculose. As\napresentações radiológicas dessa fase são as cavidades, consolidações, nódulos, massas ou\nopacidades retículo-nodulares. Podemos indicar que:","options":{"A":"O acometimento das cadeias ganglionares depende da localização do processo inflamatório no\nparênquima pulmonar.","B":"O acometimento das cadeias ganglionares independe da localização do processo inflamatório no\nparênquima pulmonar.","C":"O acometimento das cadeias ganglionares depende da localização do processo inflamatório na\npleura.","D":"O acometimento das cadeias neuronais depende da localização do processo inflamatório no\nparênquima pulmonar."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249445","number":"249445","sourceNumber":"249445","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito de medidas de controle ambiental, grupo de medidas inclui adaptação de\nconsultórios que precisam ser arejados, com entrada de luz solar e janelas abertas. Sendo incorreto\nque:","options":{"A":"ventiladores direcionados para janelas podem contribuir para criar um direcionamento do fluxo\nde ar para área externa.","B":"exaustores exercem essa função de forma mais eficaz. Quando adquiridos, devem levar em\nconsideração a capacidade do equipamento e o volume de ar da sala que deve ser trocado cerca\nde seis a 15 vezes por hora.","C":"a instalação de aparelhos de ar condicionado em consultórios facilita a obtenção de exaustão\nadequada.","D":"em locais muito quentes, cuja utilização de aparelhos de ar condicionado proporciona conforto\nadicional, estudo de fluxo e adequação do\nexaustor, com trocas adequadas ao condicionador de ar,\npode ser feito por profissionais qualificados."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-252942","number":"252942","sourceNumber":"252942","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"\"Estima-se que ¼ da população mundial esteja infectada pelo Mycobacterium\ntuberculosis, agente causador da tuberculose\n(TB). Em 2015, a Organização Mundial da Saúde\n(OMS) publicou a Estratégia pelo Fim da Tuberculose (End TB Strategy), que estabelece metas\narrojadas para o fim da TB como problema de saúde pública até 2035. De acordo com a OMS, para\no alcance dessas metas, é imprescindível aumentar o rastreio, diagnóstico e o tratamento da\ninfecção latente pelo Mycobacterium tuberculosis, reduzindo o risco de adoecimento e,\nconsequentemente, evitando a contaminação. Quanto maior o número de Unidades Básicas de\nSaúde (UBS) e de profissionais capacitados desenvolvendo ações de controle da TB, mais\nabrangente serão as atividades voltadas ao alcance das metas.\" BRASIL, Ministério da Saúde.\n\nSecretário de Vigilância em Saúde, Departamento de Vigilância das Doenças Transmissíveis,\nProtocolo de vigilância da infecção pelo\nMycobacterium tuberculosis no Brasil/Ministério da Saúde,\nBrasília 2018. Adolescente, 17 anos de idade, contactante de paciente com tuberculose pulmonar\nbacilífera, apresenta teste tuberculínico com induração de 5mm. O adolescente fez uso de BCG na\ninfância e é HIV negativo. Está assintomático e tem RX de tórax normal. Esse paciente deve ser\nconsiderado:","options":{"A":"Portador de imunidade conferida pelo BCG, com menos risco de contágio, sem indicação para\nseguimento.","B":"Indeterminado do ponto de vista clínico/epidemiológico, com indicação para seguimento clínico\nsem tratamento.","C":"Portador de tuberculose latente com risco de desenvolver tuberculose ativa nos próximos dois\nanos.","D":"Portador de tuberculose latente e com indicação para tratamento prioritário com rifampicina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-252943","number":"252943","sourceNumber":"252943","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"\"Estima-se que ¼ da população mundial esteja infectada pelo Mycobacterium\ntuberculosis, agente causador da tuberculose\n(TB). Em 2015, a Organização Mundial da Saúde\n(OMS) publicou a Estratégia pelo Fim da Tuberculose (End TB Strategy), que estabelece metas\narrojadas para o fim da TB como problema de saúde pública até 2035. De acordo com a OMS, para\no alcance dessas metas, é imprescindível aumentar o rastreio, diagnóstico e o tratamento da\ninfecção latente pelo Mycobacterium tuberculosis, reduzindo o risco de adoecimento e,\nconsequentemente, evitando a contaminação. Quanto maior o número de Unidades Básicas de\nSaúde (UBS) e de profissionais capacitados desenvolvendo ações de controle da TB, mais\nabrangente serão as atividades voltadas ao alcance das metas.\" BRASIL, Ministério da Saúde.\n\nSecretário de Vigilância em Saúde, Departamento de Vigilância das Doenças Transmissíveis,\nProtocolo de vigilância da infecção pelo\nMycobacterium tuberculosis no Brasil/Ministério da Saúde,\nBrasília 2018. No diagnóstico de tuberculose latente, têm sido usados testes alternativos. A\ncomparação entre os Testes de Expressão de Interferon Gama (IGRAM) e o Teste Tuberculínico\npermite a seguinte conclusão:","options":{"A":"A acurácia e os valores preditivos dos dois testes são semelhantes.","B":"Ambos os testes são afetados pela vacinação prévia pelo BCG.","C":"A interferência de micobactérias atípicas é semelhante nos dois testes.","D":"Ambos os testes estão disponíveis nos Centros de Referência para TB do SUS."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-252944","number":"252944","sourceNumber":"252944","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"\"Estima-se que ¼ da população mundial esteja infectada pelo Mycobacterium\ntuberculosis, agente causador da tuberculose\n(TB). Em 2015, a Organização Mundial da Saúde\n(OMS) publicou a Estratégia pelo Fim da Tuberculose (End TB Strategy), que estabelece metas\narrojadas para o fim da TB como problema de saúde pública até 2035. De acordo com a OMS, para\no alcance dessas metas, é imprescindível aumentar o rastreio, diagnóstico e o tratamento da\ninfecção latente pelo Mycobacterium tuberculosis, reduzindo o risco de adoecimento e,\nconsequentemente, evitando a contaminação. Quanto maior o número de Unidades Básicas de\nSaúde (UBS) e de profissionais capacitados desenvolvendo ações de controle da TB, mais\nabrangente serão as atividades voltadas ao alcance das metas.\" BRASIL, Ministério da Saúde.\n\nSecretário de Vigilância em Saúde, Departamento de Vigilância das Doenças Transmissíveis,\nProtocolo de vigilância da infecção pelo\nMycobacterium tuberculosis no Brasil/Ministério da Saúde,\nBrasília 2018. A investigação para tuberculose latente está indicada em várias condições de\nexposição. Entre os indivíduos listados, identifique o paciente no qual os testes para investigação\nda TB latente são dispensáveis, passando-se diretamente para a quimioprofilaxia.","options":{"A":"Paciente portador de HIV.","B":"Profissional de saúde exposto.","C":"Paciente com imunossupressão.","D":"Recém-nascido de mãe com TB ativa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249454","number":"249454","sourceNumber":"249454","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"É necessário que, aliado ao fortalecimento das ações de saúde, haja também o\nincremento das ações de políticas de\ninclusão de proteção de direitos, como os programas sociais,\npara manter a tendência de queda da incidência e mortalidade por TB, bem como evitar o\ncrescimento dos índices de abandono do tratamento na população pobre ou extremamente pobre.","options":{"A":"O sucesso futuro do controle da TB pode não depender do progresso em todas essas áreas,\nsendo fundamental enfrentar também a discriminação\ne o preconceito, a fim de eliminar barreiras e\nampliar o acesso a bens e serviços públicos.","B":"O sucesso futuro do controle da TB pode depender do progresso em todas essas áreas, sendo\nirrelevante enfrentar também a discriminação e o preconceito, a fim de eliminar barreiras e ampliar\no acesso a bens e serviços públicos.","C":"O sucesso futuro do controle da TB pode depender do progresso em todas essas áreas, sendo\nfundamental enfrentar também a discriminação e o preconceito, a fim de eliminar barreiras e\nampliar o acesso a bens e serviços públicos.","D":"O sucesso futuro do controle da TB pode depender do progresso em todas essas áreas, sendo\nfundamental enfrentar também a discriminação e o preconceito, a fim de eliminar barreiras e reduzir\no acesso a bens e serviços públicos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249455","number":"249455","sourceNumber":"249455","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Fortalecer a articulação intra e intersetorial para garantia dos direitos humanos e\ncidadania nas ações de controle da doença, para pautar a tuberculose nas seguintes agendas de\ntrabalho da assistência social, educação, justiça e de direitos humanos. Nesse contexto, não\npodemos assumir o item:","options":{"A":"Implementar as recomendações das políticas vigentes de articulação intra e intersetorial.","B":"Implementar as recomendações da Instrução Operacional conjunta entre Secretaria de Vigilância\nem Saúde (SVS) e Secretaria Nacional de\nAssistência Social (SNAS).","C":"Fomentar a elaboração de legislações que contribuam para proteção social da pessoa com\ntuberculose.","D":"Não permitir a exposição da tuberculose nos meios de comunicação disponíveis."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249456","number":"249456","sourceNumber":"249456","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Fortalecer a participação da sociedade civil nas estratégias de enfrentamento da\ndoença, para articulação entre gestão e\nsociedade civil para o controle da tuberculose; podemos\napenas aceitar que:","options":{"A":"Inibir ações de comunicação e mobilização social desenvolvidas pela sociedade civil.","B":"Excluir a participação da sociedade civil na elaboração de campanhas de comunicação de\ntuberculose.","C":"Fomentar ações comunitárias de mobilização social para o enfrentamento da doença.","D":"Desarticulação entre gestão e sociedade civil para o controle da tuberculose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249457","number":"249457","sourceNumber":"249457","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa que não se caracteriza como um dos Princípios da Estratégia\npelo Fim da Tuberculose:","options":{"A":"Proteção e promoção dos direitos humanos, éticos e de equidade.","B":"Adaptação da estratégia sem metas nos países, com colaboração no âmbito global.","C":"Forte envolvimento das organizações da sociedade civil e de base comunitária.","D":"Gestão e responsabilização do governo, com componentes de monitoramento e avaliação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249276","number":"249276","sourceNumber":"249276","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Todo ambiente onde os pacientes com TB circulam, produz aerossóis contendo\nMycobacterium tuberculosis (bacilo da tuberculose), e oferece algum risco de transmissão. Para\ndiminuí-lo é preciso considerar alguns pressupostos, estando errado apenas que:","options":{"A":"a transmissão da tuberculose se faz por via respiratória, pela inalação de aerossóis produzidos\npela tosse, fala ou espirro de um doente com TB\nativa de vias aéreas, salvo raríssimas exceções.","B":"quanto maior a ventilação desse ambiente, maior será a probabilidade de infectar os\ncircunstantes.","C":"quanto maior a intensidade da tosse é a concentração de bacilos no ambiente.","D":"com o início do tratamento adequado e o uso correto de medicamentos antiTB, a\ntransmissibilidade diminui rapidamente em duas a três semanas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-219891","number":"219891","sourceNumber":"219891","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Qual dos achados abaixo não se espera encontrar na radiografia de tórax de paciente\ncom tuberculose primária?","options":{"A":"Adenopatia hilar.","B":"Derrame pleural.","C":"Infiltrado pulmonar.","D":"Lesão cavitária."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-180149","number":"180149","sourceNumber":"180149","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação a tuberculose . Assinale a alternativa correta:","options":{"A":"Os corticosteroides devem ser utilizados como\nadjuvantes no tratamento","B":"A forma meníngea geralmente apresenta evolução\nbenigna","C":"O diagnostico de tuberculose ativa na infância sugere fortemente o contato com adulto bacilifero\nno domicilio","D":"O PPD maior que 5 mm em crianças vacinadas há\nmais de 2 anos significa doença ativa","E":"A pesquisa direta do bacilo álcool acido resistente no liquor é altamente sensível , podendo ser\ndescartada a meningite tuberculosa se negativa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-158779","number":"158779","sourceNumber":"158779","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No manuseio de neonato de mãe com tuberculose, é correto afirmar:","options":{"A":"Em casos de mães com qualquer tuberculose cuja infectividade não pode ser afastada e sem\ncondições de afastamento dos recém-nascidos, deve ser mantida a amamentação com máscara,\niniciado ou continuado tratamento materno, iniciado isoniazida por três meses para o neonato e, em\nseguida, realizado teste tuberculínico.","B":"Em casos de mães com tuberculose extrapulmonar ou pulmonar não tratada (considerada\nbacilífera), devem ser mantidos os neonatos junto à\nmãe e, somente após o teste tuberculínico,\niniciado isoniazida.","C":"Em casos de mães com diagnóstico recente de tuberculose, com doença mínima não tratada ou\ntratamento de menos de duas semanas, mas não bacilífera, não há risco para o recém-nascido.","D":"Em casos de mãe com tratamento completo e adequado, pela remota possibilidade de haver\nexacerbação na gestação, não deve ser realizado teste tuberculínico no neonato.","E":"Em casos de mães apenas com teste tuberculínico positivo, Rx normal, não bacilífera e sem\ndoença ativa, deverá ser realizado teste\ntuberculínico também no neonato."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-131384","number":"131384","sourceNumber":"131384","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"São sinais presentes na dengue hemorrágica, EXCETO:","options":{"A":"Plaquetopenia (< 100.000) e hipoalbuminemia.","B":"Sangramento espontâneo e hipotensão.","C":"Choque e icterícia.","D":"Plaquetopenia e hipotensão.","E":"NDA."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-109795","number":"109795","sourceNumber":"109795","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à dengue, são considerados sinais e sintomas de alarme, pelo Ministério da\nSaúde do Brasil:","options":{"A":"febre alta e contínua, vômitos persistentes, lipotímia e hepatomegalia dolorosa.","B":"sonolência, dor abdominal intensa e contínua, desconforto respiratório e vômitos persistentes.","C":"febre alta e contínua, queda abrupta das plaquetas, hematêmese e aumento repentino do\nhematócrito.","D":"lipotímia, diminuição da diurese, hiporexia e queda abrupta das plaquetas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-109806","number":"109806","sourceNumber":"109806","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Estima-se que mais de 40% da população mundial esteja exposta ao risco de\nadquirir Malária. Em 2006, só no Brasil, foram\nregistrados 549.182 casos de Malária, 99,7% dos\nquais na Amazônia Legal. A transmissão nessa área está relacionada a fatores: biológicos\n(presença de alta densidade de mosquitos vetores), geográficos (altos índices de pluviosidade,\namplitude da malha hídrica e cobertura vegetal), ecológicos (desmatamento, construção de\nhidroelétricas, estradas, de sistema de irrigação e açudes), e sociais (presença de numerosos\ngrupos populacionais, morando em habitação com ausência completa ou parcial de paredes\nlaterais e trabalhando próximo ou dentro das matas e dos criadouros). É caso suspeito de Malária\ntoda pessoa que apresentar quadro:","options":{"A":"Febril, que seja residente ou que tenha se deslocado para área onde haja transmissão de\nMalária no período de 8 a 30 dias, anteriores à data dos primeiros sintomas.","B":"De paroxismo febril com os seguintes sintomas: calafrios, tremores generalizados, cansaço,\nmialgia, desde que seja em área em que haja transmissão de Malária há mais de 12 meses.","C":"Febril, independente da região em que vive, e que tenha se deslocado para área onde haja\ntransmissão de Malária no período de 7 a 15 dias, anteriores à data dos primeiros sintomas.","D":"De paroxismo febril com os seguintes sintomas: calafrios, tremores generalizados, cansaço,\nmialgia, desde que seja residente em área onde haja transmissão de Malária, independente do\ntempo de residência."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-158390","number":"158390","sourceNumber":"158390","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Quais as drogas que compõem a primeira fase do Esquema básico do tratamento da\ntuberculose pulmonar em adultos?","options":{"A":"Rifampicina + isoniazida.","B":"Rifampicina + Isoniazida + Pirazinamida + Etambutol.","C":"Rifampicina + Claritromicina + Etambutol.","D":"Rifampicina + Isoniazida + Estreptomicina.","E":"Rifampicina + Isoniazida + Etambutol."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-108613","number":"108613","sourceNumber":"108613","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação ao tratamento para malária vivax em menor de 6 meses, devemos\nconsiderar:","options":{"A":"Não há tratamento específico para esta faixa etária.","B":"Trata-se com cloroquina e primaquina.","C":"Trata-se só com primaquina.","D":"Trata-se só com cloroquina.","E":"Trata-se com artesunato."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-362429","number":"362429","sourceNumber":"362429","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Gestante adquiriu tuberculose pulmonar durante a gestação. Persiste bacilífera mesmo\napós o nascimento do bebê. Em relação ao\nrecém-nascido dessa mãe, é CORRETO afirmar que:","options":{"A":"Deve-se realizar vacina da BCG e contraindicar o aleitamento materno.","B":"Não há risco de tuberculose congênita, e o aleitamento materno está contraindicado até a mãe\nnão ser mais bacilífera.","C":"A vacina da BCG está indicada ao nascimento, não sendo necessária a quimioprofilaxia.","D":"Deve-se iniciar quimioprofilaxia com isoniazida ou rifampicina e, após 3 meses, se teste\ntuberculínico for negativo, vacinar com BCG."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-362455","number":"362455","sourceNumber":"362455","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"J.B.S, 23 anos iniciou o tratamento com esquema básico para tuberculose pulmonar\nconfirmada por meio do teste rápido\nmolecular (TRM-TB) há 7 dias. A enfermeira da equipe de\nsaúde solicitou que os contatos de J.B.S. viessem até a UBS para serem avaliados. Dentre os\ncontatos intradomiciliares está L.B.S, irmã de J.B.S, de 17 anos, que está com 11 semanas de uma\ngestação sem intercorrências até aqui. L.B.S demonstrou bastante preocupação quanto a\nmanifestar a doença do irmão, embora não tenha nenhum sintoma respiratório no momento.\n\nPosteriormente, a mesma retorna com o exame de PPD que acusa o resultado de 5mm. Diante\ndesse resultado, a enfermeira da equipe deve:","options":{"A":"Solicitar radiografia de tórax e TRM-TB para excluir tuberculose ativa.","B":"Iniciar tratamento para infecção latente da tuberculose com o esquema 3HP (Rifapentina 150mg\n\n(P) e Isoniazida (H) 300mg) em doses semanais durante 3 meses.","C":"Postergar tratamento infecção da latente da tuberculose para 13 semanas de gestação.","D":"Postergar tratamento da infecção latente da tuberculose para após o parto."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-362448","number":"362448","sourceNumber":"362448","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A cidade de Manaus tem sofrido, nos últimos meses, efeitos do fenômeno \"El Niño\". A\nescassez de chuvas e o tempo seco tem\nfavorecido a proliferação de queimadas, estando a cidade\ncoberta de fumaça durante vários dias. Este fenômeno climático tem intensificado a ocorrência de\nproblemas respiratórios, como a tosse. Em uma manhã de atendimento em sua UBS você atendeu\nvários pacientes com queixa de tosse, listados nas alternativas abaixo, entretanto apenas UM\ndestes pacientes possui tosse com SINAL DE ALERTA para causas subjacentes de maior\ngravidade que deve ser encaminhado ao especialista focal para cuidado compartilhado. Qual?","options":{"A":"Paciente com tosse há três dias associada a coriza.","B":"Paciente com tosse seca persistente, com sensação de bola na garganta e \"\"queimação no\nestômago\"\", sem perda ponderal.","C":"Paciente tabagista, apresentando tosse produtiva com secreção purulenta e síndrome\nconsumptiva.","D":"Paciente com tosse seca após início do uso de enalapril para HAS."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-327233","number":"327233","sourceNumber":"327233","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Maurício tem 37 anos, é um paciente com transtorno de adição por substâncias ilícitas,\nconsome cocaína e inala crack. Adoeceu por tuberculose pulmonar confirmada por exame de\nescarro e imagem 2 anos atrás, entretanto abandonou o tratamento ainda no quarto mês. A equipe\nde saúde não conseguiu contato na busca ativa na época do abandono e agora retorna com queixa\nde tosse produtiva, perda ponderal, febre vespertina e astenia. Qual das alternativas a seguir\ndiscrimina a conduta mais apropriada para Maurício nesse momento?","options":{"A":"Solicito TRM-TB pois já avalia se há resistência a rifampicina e radiografia de tórax em PA e\nperfil.","B":"Reinicio tratamento, prescrevendo RH por mais 3 meses para completar os 2 meses de\ntratamento faltantes, com dose ajustada de acordo com o peso atual.","C":"Por tratar-se de abandono, encaminho o paciente para internação em uma unidade terciária com\nisolamento respiratório. Pela alta probabilidade de tratar- se de tuberculose multirresistente.","D":"Solicito radiografia de tórax em PA e perfil, baciloscopia do escarro e cultura para\nmicobactérias\nno escarro com tipificação e teste de\nsensibilidade, pois o abandono pode ter gerado alguma\nresistência. Se a baciloscopia vier positiva inicio tratamento com RHZE e aguardo resultado da\ncultura."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-298205","number":"298205","sourceNumber":"298205","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"H.T.S., 33 anos, procedente de Itacoatiara, católico, ensino médio completo, pedreiro,\ncasado, com 2 filhos. Relata que se\nencontrava em bom estado de saúde até 5 semanas atrás,\nquando começou a apresentar quadro de tosse produtiva com expectoração amarelada. Há cerca\nde 2 semanas houve piora do quadro, evoluindo com febre vespertina, astenia e a tosse evoluiu\ncom hemoptoicos. Observou ainda que perdeu 5 kg no período. Relata contato com tuberculose há\ncerca de 3 anos atrás (irmã). Nega doenças crônicas, nega etilismo, nega tabagismo. Você solicita\nradiografia de tórax em PA e perfil e baciloscopia do escarro em 2 amostras para investigação\ndiagnóstica. O paciente retorna uma semana depois com a radiografia de tórax evidenciando\nopacidades acinares heterogêneas em lobo superior direito e baciloscopia do escarro positiva\n(2+/4+). Qual a conduta mais apropriada em relação aos contatos desse paciente?","options":{"A":"Solicitar que todos venham à unidade, avaliar a presença de sintomas sugestivos de\ntuberculose, investigando os sintomáticos com\nradiografia de tórax em PA e perfil e baciloscopia do\nescarro em 2 amostras. Os assintomáticos com menos de 10 anos devem ser investigados com\nrealização de PPD e radiografia de tórax em PA e perfil e os maiores de 10 anos com PPD.","B":"Solicitar que venham à unidade apenas os contatos que estiverem apresentando algum sintoma\nrespiratório, investigando com baciloscopia do escarro em 2 amostras.","C":"Solicitar que todos venham à unidade e investigar apenas os sintomáticos com radiografia de\ntórax em PA e perfil e baciloscopia do escarro em 2 amostras.","D":"Tratar imediatamente os sintomáticos respiratórios, pois não há necessidade de investigação\ncom exames quando já há um doente confirmado na\ncasa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-298275","number":"298275","sourceNumber":"298275","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose pulmonar é uma condição de saúde pública que deve ser conduzida na\nAtenção Primária à Saúde de forma resolutiva e, para isso, o médico deve conhecer alguns\nmétodos diagnósticos da doença. Normalmente são utilizadas a baciloscopia de escarro, o teste\nrápido molecular para TB com teste de sensibilidade à rifampicina e a cultura. Sobre métodos\ndiagnósticos e de seguimento de tuberculose pulmonar, considere as afirmativas a seguir e\nassinale a CORRETA:","options":{"A":"A baciloscopia do escarro em duas amostras é o padrão-ouro para o diagnóstico de tuberculose\npulmonar.","B":"O teste rápido molecular para M. tuberculosis é indicado para o 9 seguimento terapêutico mensal\nde controle do tratamento.","C":"Dada a dificuldade em se obter uma amostra adequada de escarro em crianças, deve-se\nsolicitar cultura do material obtido quando o\nmesmo for coletado para a realização de teste rápido\nmolecular para M. tuberculosis.","D":"Casos suspeitos de falência do tratamento com esquema básico dispensam a realização do\nteste de sensibilidade à rifampicina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-286775","number":"286775","sourceNumber":"286775","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um paciente de 7 anos, recebeu BCG ao nascer, é contactante intradomiciliar de\ntuberculoso bacilífero, apresenta-se assintomático, Rx de tórax normal e prova tuberculínica de 8\nmm, deve receber a orientação de:","options":{"A":"Repetir o PPD em 8 semanas","B":"Realizar lavado gástrico","C":"Tratar infecção latente","D":"Revacinar"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-286776","number":"286776","sourceNumber":"286776","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Logo após o parto, a parturiente informa que o marido acabou de fazer diagnóstico de\nTB pulmonar bacilífera. Nesse caso, a conduta\nCORRETA é:","options":{"A":"Suspender a amamentação.","B":"Iniciar isoniazida logo ao nascimento.","C":"Iniciar esquema RIP logo ao nascimento.","D":"Realizar lavado gástrico, RX tórax e realizar BCG."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-256580","number":"256580","sourceNumber":"256580","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Adolescente de 13 anos é encaminhado por tosse produtiva, febre e perda de peso há\n2 meses. Mãe com tuberculose bacilífera em\ntratamento há 10 dias. Ao exame, encontra-se\nemagrecido e apresenta estertoração grossa esparsa em campos pleuropulmonares. Prova\ntuberculínica não reatora; radiografia de tórax com infiltrado peri-hilar, bacterioscopia de escarro\ncom BAAR positivo. De acordo com as diretrizes para tratamento da tuberculose no Brasil, o\nesquema terapêutico e o tempo de tratamento preconizado para o caso é:","options":{"A":"Rifampicina (6 meses), isoniazida (6 meses), pirazinamida (2 meses) e etambutol (2 meses).","B":"Rifampicina (6 meses), isoniazida (6 meses) e pirazinamida (2 meses).","C":"Rifampicina (4 meses), estreptomicina (2 meses), isoniazida (6 meses) e pirazinamida (2\nmeses).","D":"Rifampicina (4 meses), isoniazida (6 meses), pirimetamina (6 meses) e etambutol (2 meses)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-252306","number":"252306","sourceNumber":"252306","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Rui, 45 anos, tem tosse há 2 meses e perdeu 7 kg nesse período. Veio para consulta\nmédica na UBS entregar o resultado do\nBAAR, que foi positivo. Você inicia o tratamento e pergunta\nsobre os seus contactantes. Rui mora com a esposa Patrícia, de 38 anos. Você agenda então\nconsulta para Patrícia. Durante a consulta, Patrícia encontra-se assintomática e tem ausculta\nnormal. Você deve, num primeiro momento para Patrícia:","options":{"A":"Solicitar BAAR.","B":"Solicitar Prova tuberculínica (PT).","C":"Solicitar Raio X de tórax.","D":"Iniciar tratamento para Infecção latente pelo M. tuberculosis (ILTB)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-176073","number":"176073","sourceNumber":"176073","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"De acordo com o Plano nacional de Controle da Tuberculose (PNCT), o objetivo do\ncomponente da vigilância epidemiológica da tuberculose é monitorar a situação e a tendência da\ndoença para recomendar, executar e avaliar as atividades de controle. Qual das seguintes ações\nnão se enquadra nesses objetivos?","options":{"A":"Reforçar a investigação de casos como uma ação de acolhimento, atitude que deve perpassar\npor toda a equipe.","B":"Intensificar a identificação de sintomáticos respiratórios, examiná-los com baciloscopia e\nimplementar o registro dos mesmos na rede laboratorial do SUS.","C":"Monitorar os eventos adversos temporalmente associados à vacina BCG, em conjunto com os\ntécnicos do PNI municipal/estadual/regional.","D":"Implantar a procura de sintomáticos respiratórios nos ambulatórios de hospitais e emergências\ndos grandes centros urbanos e criar facilidades\npara examiná-los."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-152028","number":"152028","sourceNumber":"152028","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose apresenta taxa de incidência ainda muito elevada em nosso Estado (66,7\nno Amazonas, enquanto no Brasil é de 33,8 ?\ndados de 2014, Boletim Epidemiológico nº 13 ? 2016,\nMinistério da Saúde, disponível em www.saude.gov.br). No ano de 2014, foi aprovada, pela\nAssembleia Mundial de Saúde, a Estratégia pelo Fim da Tuberculose, com objetivo de um mundo\nlivre desta doença e que se propõe a traçar estratégias para o fim da epidemia global da doença.\n\nEm relação a esta enfermidade e as estratégias desenvolvidas para seu controle, NÃO podemos\nafirmar que:","options":{"A":"Enfatiza a necessidade de realização de cultura do escarro e teste de sensibilidade,\nprincipalmente nos casos de retratamento onde há\nmaior risco de resistência aos fármacos e nos\ncasos de baciloscopia positiva ao final do 2º mês de tratamento.","B":"Dentre as metas do programa estão a redução dos coeficientes de incidência (< 10 casos por\n100.000 habitantes) e de mortalidade (95%) da doença até 2035. Esta redução representa, para a\nOrganização Mundial da Saúde, o fim da tuberculose como problema de saúde pública.","C":"Seus indicadores epidemiológicos (coeficiente de incidência, coeficiente de mortalidade,\nproporção de casos de retratamento, proporção\nde cura, proporção de multirresistência, dentre\noutros) refletem a qualidade dos serviços prestados, servindo de apoio para tomada/mudança de\ndecisões.","D":"No Brasil, o esquema padronizado para tratamento desta doença é com 4 drogas (rifampicina,\nisoniazida, pirazinamida e etambutol), priorizando o tratamento diretamente observado (quando o\npaciente toma as medicações quinzenalmente no centro de saúde) e por no mínimo 9 meses."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-151975","number":"151975","sourceNumber":"151975","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre tuberculose é CORRETO afirrmar:","options":{"A":"A amamentação é contraindicada em pacientes que estejam em tratamento de tuberculose.","B":"A tuberculose na criança (menores de 10 anos) costuma ser bacilífera, assim como no adulto.","C":"Quando a reação adversa corresponde a uma reação de hipersensibilidade grave como\nplaquetopenia, anemia hemolítica, insuficiência renal etc, o medicamento suspeito pode ser\nreiniciado após a suspensão.","D":"Os casos bacilíferos são a principal fonte de disseminação da doença, a descoberta precoce por\nmeio da busca ativa do sintomático respiratório é importante medida para interromper a cadeia de\ntransmissão, desde que acompanhada pelo tratamento oportuno."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-107753","number":"107753","sourceNumber":"107753","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A.M.T., adolescente, viajou para Careiro, após 1 semana apresentou cefaleia intensa,\nfebre, mialgia, artralgia (febre quebra-ossos) e\napós alguns dias começou exantema. O diagnóstico\nprovável é:","options":{"A":"Sarampo.","B":"Sepse.","C":"Dengue.","D":"Varicela."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81070","number":"81070","sourceNumber":"81070","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"AMT, adolescente viajou para o Careiro e após 1 semana apresentou cefaleia intensa,\nfebre, mialgia, artralgia (febre quebra-ossos)\ne após alguns dias começou exantema o diagnóstico\nprovável é:","options":{"A":"Sarampo","B":"Sepse","C":"Dengue","D":"Rubéola","E":"Varicela"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-34185","number":"34185","sourceNumber":"34185","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A febre amarela é uma infecção aguda caracterizada em sua forma mais grave por\napresentar:","options":{"A":"Febre, anicterícia, trombocitopenia e hemorragia.","B":"Afebril, icterícia, proteinúria e trombocitopenia.","C":"Febre, insuficiência cardíaca, colesterol elevado e hemorragia.","D":"Febre, icterícia, proteinúria e hemorragia.","E":"Afebril, anicterícia, insuficiência cardíaca e hemorragia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-34295","number":"34295","sourceNumber":"34295","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No Brasil, desde 1986, vêm ocorrendo epidemias de dengue nos principais centros\nurbanos do país, com cerca de 5 milhões de\ncasos e tem-se observando um aumento na\nseveridade destes. No período de 1990 a 2008, foram registrados 12.681 casos de Febre\nHemorrágica por Dengue, principalmente em adultos com a ocorrência de 786 óbitos (Dengue:\nDecifra-se ou Devoro-te). Em relação a este agravo, podemos afirmar:","options":{"A":"Apresenta três sorotipos; a infecção por um sorotipo garante imunidade duradoura para os\noutros dois.","B":"A Dengue clássica apresenta febre súbita, cefaleia, dor retro-orbital, mialgias, astenia,\nartralgias.","C":"Os sinais de agravamento/alerta da doença são dor abdominal intensa, dispneia, hipotensão,\nhepatoesplenomegalia dolorosa, entre outros e costumam ocorrer no período febril.","D":"Todos os pacientes com suspeita de Dengue devem ter a pressão arterial aferida em\nortostatismo preferencialmente ou a prova do laço realizada.","E":"As medidas de prevenção a este agravo são de execução estritamente individual e envolvem o\ncontrole ambiental e uso de repelentes."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-26452","number":"26452","sourceNumber":"26452","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa INCORRETA, para as doenças infecciosas abaixo relacionadas:","options":{"A":"Os principais diagnósticos diferenciais da leptospirose na sua forma ictérica são: febre amarela,\nmalária pelo P. vivax, sepsis e hepatite aguda grave","B":"<P>A leptospirose é uma zoonose que ocorre de forma endêmica no mundo inteiro, exceto nas\nregiões polares. A pesquisa de AC, por meio de reações sorológicas, constitui o principal método\nde confirmação diagnóstica</P>","C":"<P>A&nbsp;dengue, depois da malária, é a mais importante doença transmitida por artrópodes.\n\nA sua transmissão ocorre pela picada da fêmea do mosquito do gênero Aedes, sendo que a\nplaquetopenia e hemoconcentração caracteriza a forma hemorrágica da doença</P>","D":"A malária no Brasil é causada por três gêneros de Plasmodium: P.vivax, P.falciparum e\nP.malarie. O falciparum é considerado\ndoença grave em pessoas não imunes, mesmo que no início\nnão se observem parâmetros de gravidade","E":"A febre tifoide é de transmissão feco-oral, predominantemente através da água contendo\nSalmonella typhi. A reação de Widal, devido a\nbaixa sensibilidade e especificidade, tem perdido seu\nespaço no diagnóstico da doença"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-26478","number":"26478","sourceNumber":"26478","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente do sexo masculino, 25 anos, apresenta história de dor abdominal há 2\nsemanas. O paciente é residente de\ncomunidade ribeirinha e faz uso de água não tratada, do rio,\niniciou quadro de dor abdominal em cólicas e febre alta que evoluiu com diarreia esverdeada franca\ne desidratação severa. Foi encaminhado a Manaus e foi internado em unidade básica de saúde\nsendo tratado com cloranfenicol por 7 dias, sem melhora satisfatória. Hoje apresentou piora súbita\nda dor abdominal, inicialmente mesogástrica, que posteriormente irradiou para todo o abdome e\nombro esquerdo, há cerca de 6 horas. Apresentou vômitos. Ao exame físico apresenta-se febril,\nsudoreico, com mucosas secas e taquicárdico e discretamente hipotenso. O paciente se encontra\nimóvel na maca, com respiração rápida e superficial. O abdome é difusamente doloroso à palpação\ne muito tenso. Blumberg positivo. O hematócrito era 32%, a hemoglobina 10 mg/dl e o leucograma\né de 15.000 leucócitos com 90% de neutrófilos. Marque a alternativa correta:","options":{"A":"<P>Trata-se de abdome agudo inflamatório já que o paciente apresenta quadro de evolução\narrastada, acompanhado de febre e leucocitose, estando indicada a transferência para UTI para\ncompensação do quadro prévia à laparotomia</P>","B":"Já que o caso tem 2 semanas de evolução seu tratamento não deve ser cirúrgico, sendo a\nconduta mais adequada a troca do antibiótico e hidratação vigorosa do paciente","C":"Trata-se de abdome agudo hemorrágico já que o paciente apresenta hipotensão e taquicardia,\nestando indicada a transfusão sanguínea e\nlaparotomia imediata","D":"A radiografia de tórax provavelmente indicará laparotomia exploradora para o paciente acima","E":"Com os dados acima podemos afirmar que se trata de abdome agudo cirúrgico por úlcera\npéptica perfurada, já que o paciente apresenta\nabdome em tábua e irradiação da dor para o ombro."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-34932","number":"34932","sourceNumber":"34932","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No sentido de orientar as ações de controle, as doenças infecciosas e parasitárias, no\nBrasil, vêm sendo classificadas pelo Ministério da Saúde, segundo três tendências principais:\ndoenças com tendência decrescente, doenças com quadro de persistência e as doenças\nemergentes e reemergentes. Um exemplo de doença com quadro de persistência é:","options":{"A":"o tétano acidental.","B":"a AIDS.","C":"a dengue.","D":"a cólera.","E":"a leishmaniose."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-27503","number":"27503","sourceNumber":"27503","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A febre amarela é uma doença grave, cuja principal medida de controle é a imunização\nde todas as pessoas maiores de nove meses de\nidade que estejam expostas ao risco de infecção,\npor residir, trabalhar ou viajar para áreas endêmicas. Epidemiologicamente, está dividida em febre\namarela urbana e febre amarela silvestre. Com relação à forma urbana, o vetor principal é:","options":{"A":"Haemagogus.","B":"Aedes aegypti.","C":"P. vivax.","D":"P. falciparum.","E":"Borrelia burgdorferi."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-11140","number":"11140","sourceNumber":"11140","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Pelos critérios do Ministério da Saúde, em caso de dengue o internamento hospitalar é\nrecomendado quando há:","options":{"A":"febre acima de 39°C, após dois dias de doença.","B":"hematócrito acima de 50%, após hidratação.","C":"sangramentos espontâneos, em qualquer fase.","D":"plaquetas abaixo de 120 mil/mm³, em qualquer fase.","E":"prova do laço positiva, após 2 dias de doença."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-314295","number":"314295","sourceNumber":"314295","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"\"Pela variedade de suas manifestações clínicas, recomenda-se que o diagnóstico de\ntuberculose (TB) pulmonar, em crianças e em adolescentes com baciloscopia negativa ou TRM-TB\nnão detectado, seja realizado com base em um sistema de escores [...]\" (BRASIL, 2021, p.467).\n\nEste escore varia com o quadro clínico-radiológico, o contato, a prova tuberculínica e o estado\nnutricional. Considerando esse sistema de escores para diagnóstico da tuberculose pulmonar em\ncrianças e adolescentes, é corretor afirmar que","options":{"A":"se o somatório de pontos for ?40 (diagnóstico muito provável), recomenda-se iniciar o tratamento\nda tuberculose.","B":"se o somatório de pontos for <25 (diagnóstico muito provável), recomenda-se iniciar o\ntratamento da tuberculose.","C":"se o somatório de pontos for entre 10 e 24 (diagnóstico provável), é indicativo de tuberculose, e\norienta-se iniciar o tratamento a critério médico.","D":"se o somatório de pontos for entre 05 e 15 (diagnóstico possível), é indicativo de tuberculose, e\norienta-se iniciar o tratamento a critério médico.","E":"se o somatório de pontos for entre 5 a 25 (diagnóstico muito provável), é indicativo de\ntuberculose, e orienta-se iniciar o tratamento a critério médico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-281860","number":"281860","sourceNumber":"281860","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O diagnóstico e o tratamento da Infecção Latente da Tuberculose (ILTB) em pessoa\nvivendo com HIV PVHIV são fundamentais para minimizar o risco de adoecimento. Sendo correto\nque:","options":{"A":"O tratamento preventivo não reduziu esse risco em diversos estudos, quando orientado ou não\npela prova tuberculínica, respectivamente.","B":"O tratamento preventivo reduziu esse risco em diversos estudos, somente quando orientado pela\nprova tuberculínica, respectivamente.","C":"O tratamento preventivo aumentou esse risco em diversos estudos, quando orientado ou não\npela prova tuberculínica, respectivamente.","D":"O tratamento preventivo reduziu em 62% e 32% esse risco em diversos estudos, quando\norientado ou não pela prova tuberculínica, respectivamente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249720","number":"249720","sourceNumber":"249720","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O sistema esquelético alberga até 35% dos casos de tuberculose extrapulmonar. A\nalternativa que contém o sítio esquelético mais frequentemente afetado pela tuberculose é","options":{"A":"Fêmur.","B":"Escápula.","C":"Osso ilíaco.","D":"Coluna vertebral.","E":"Articulações interfalangianas distais."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-250017","number":"250017","sourceNumber":"250017","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para tratar de forma adequada e oportuna todos os casos diagnosticados de\ntuberculose visando à integralidade do cuidado. Somente não indicamos:","options":{"A":"Desenvolver ações que favoreçam a adesão ao tratamento da tuberculose.","B":"Tratamento indiretamente observado.","C":"Integrar o cuidado do paciente com tuberculose com outros equipamentos da rede da saúde e\nassistência social.","D":"Implantar a vigilância da tuberculose droga resistente."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-250020","number":"250020","sourceNumber":"250020","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Fomentar ações para garantir a realização das atividades de cuidado e prevenção da\ndoença com recursos adequados, somente sendo\ninadequado o item:","options":{"A":"Inserir ações de controle da tuberculose nos Planos Plurianuais.","B":"Pautar a tuberculose nas instâncias de pactuação e controle social.","C":"Implementar ações de comunicação e mobilização social para diminuir a visibilidade da doença.","D":"Disponibilizar insumos para o diagnóstico e medicamentos para o tratamento de todas as formas\nde tubérculos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-250021","number":"250021","sourceNumber":"250021","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Os progressos nos determinantes sociais da saúde têm tido um efeito na saúde dos\nbrasileiros e isso provavelmente contribuiu também para a redução de doenças infecciosas, como a\nTB, no país. Somente não podemos aceitar que:","options":{"A":"Intervenções direcionadas aos determinantes socioeconômicos podem contribuir na melhoria do\ncontrole da TB no Brasil, a redução da pobreza não aparece como tema central","B":"Erradicar a pobreza, em todas as suas formas e dimensões, incluindo a pobreza extrema,\naparece como requisito indispensável para o\ndesenvolvimento sustentável.","C":"Assegurar uma vida saudável e promover o bem-estar para todas e todos, devendo-se acabar\ncom a epidemia global de tuberculose.","D":"A Estratégia pelo Fim da Tuberculose propõe a inclusão de intervenções socioeconômicas para\nprevenir e controlar a doença e também recomenda estratégias de proteção social para os\npacientes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-250023","number":"250023","sourceNumber":"250023","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Nos casos clínicos, de TB pulmonar pós-primária ou secundária a tosse é produtiva, a\nexpectoração pode ser purulenta ou mucoide, com ou sem sangue. Indique o item inadequado:","options":{"A":"A febre vespertina, sem calafrios, não costuma ultrapassar os 38,5ºC.","B":"A sudorese noturna e a anorexia são raras.","C":"O exame físico geralmente mostra fácies de doença crônica e emagrecimento, embora\nindivíduos com bom estado geral e sem perda do apetite também possam ter TB pulmonar.","D":"A ausculta pulmonar pode apresentar diminuição do murmúrio vesicular, sopro anfórico ou\nmesmo ser normal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-250027","number":"250027","sourceNumber":"250027","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Tuberculose TB pleural, é a forma mais comum de TB extrapulmonar em pessoas não\ninfectadas pelo HIV. Não podemos aceitar que:","options":{"A":"Nos pacientes com menor tempo de evolução dos sintomas pode ocorrer dispneia.","B":"Ocorre mais em jovens e cursa com dor torácica do tipo pleurítica.","C":"A tríade astenia, emagrecimento e anorexia ocorre em 70% dos pacientes.","D":"Ocorre febre com tosse seca, em 60%."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-215600","number":"215600","sourceNumber":"215600","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O tratamento diretamente observado (TDO) é uma estratégia recomendada para todas\nas pessoas com diagnóstico de tuberculose.\nSendo INCORRETO que:","options":{"A":"Define-se como TDO a ingestão diária dos medicamentos antituberculose pelo paciente sob a\nobservação direta de um profissional de saúde.","B":"O TDO deve ser realizado diariamente (de segunda a sexta-feira) ou, excepcionalmente, uma\nvez na semana.","C":"O local e o horário devem estar acordados com o paciente.","D":"Os medicamentos deverão ser ingeridos preferencialmente em jejum, uma vez ao dia, inclusive\nnos finais de semana e feriados."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-215584","number":"215584","sourceNumber":"215584","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O tratamento da tuberculose sensível dura no mínimo 6 meses, desde o diagnóstico até\nsua alta. O estabelecimento de vínculo entre profissional de saúde e usuário auxilia tanto no\ndiagnóstico como na adesão ao tratamento, sendo que o paciente deve ser orientado, de forma\nclara, quanto às características clínicas da tuberculose, bem como acerca de eventos adversos.\n\nSomente se mostrando INADEQUADO que:","options":{"A":"No regime de tratamento com isoniazida, o mais importante é somente o tempo de tratamento.","B":"Recomenda-se a utilização de, no mínimo, 270 doses com isoniazida, que poderão ser tomadas\nde 9 a 12 meses.","C":"Deve-se considerar a utilização de 180 doses com isoniazida, a serem tomadas entre 6 a 9\nmeses em casos individuais, após avaliação da adesão.","D":"Há evidências de que o uso de 270 doses com isoniazida protege mais do que o uso de 180\ndoses. Esforços devem ser feitos para que o paciente complete o total de doses programadas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-162478","number":"162478","sourceNumber":"162478","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Joana, uma criança de nove anos, está com quadro febril com três dias de evolução.\nRefere dor de cabeça, dor atrás dos olhos, dor\nnos músculos e indisposição, são sinais de alarme:","options":{"A":"dor abdominal intensa e contínua e vômitos persistentes.","B":"edema de membros inferiores e exantema.","C":"plaquetopenia e hipertensão arterial.","D":"prova do laço positiva e exantema.","E":"anemia e perda de peso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-134682","number":"134682","sourceNumber":"134682","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O Aedes aegypti é o mosquito responsável pela transmissão de várias doenças, dentre\nelas:","options":{"A":"Malária, Dengue, Leishmaniose visceral e Zika.","B":"Dengue, Chikungunya, Febre Amarela Urbana e Leishmaniose Cutânea Mucosa.","C":"Zika, Dengue, Febre Amarela Urbana e Chikungunya.","D":"Dengue, Leishmaniose visceral, Zika e Chikungunya."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-350815","number":"350815","sourceNumber":"350815","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Tales, de 17 anos, procura atendimento médico referindo tosse diária há quatro meses,\nevoluindo há 1 semana com expectoração esbranquiçada e com episódios de expectoração com\nraias de sangue. Relata que o quadro iniciou enquanto cumpria pena de privação provisória de\nliberdade em instituição socioeducativa. Refere perda ponderal não-intencional nos últimos dois\nmeses, com ?febre interna? diária. Refere uso diário de cigarro por tabaco e por cannabis.\n\nConsiderando o conceito de Sintomático Respiratório (SR), assinale a alternativa correta.","options":{"A":"Tales não pode ser considerado SR ainda, pois seus sintomas podem ser de natureza associada\nao fumo. É preciso reavaliar o quadro clínico\napós a cessação do fumo. Caso permaneça com\nsintomas respiratórios, afastadas as causas externas, ele deve ser considerado SR e deve ser\niniciada a investigação clínica apropriada.","B":"Tales não pode ser considerado SR ainda, pois seu quadro de tosse produtiva só tem duração\nde uma semana.","C":"Tales passou a ser considerado SR a partir do momento em que permaneceu sintomático por\npelo menos três semanas.","D":"Tales poderia ser considerado SR a qualquer momento de duração enquanto estava em\nprivação provisória de liberdade (PPL)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-350814","number":"350814","sourceNumber":"350814","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Lana, de 3 anos, é trazida para atendimento na UBS por sua avó, dona Benzarina. A\navó relata que a criança falta\nrecorrentemente à escola por ?estar sempre gripada?. Queixa-se de\nque ?a menina está sempre com nariz escorrendo e tossindo?, que ?toda noite ela dorme mal, com\ncrises de tosse?, que ?a menina está tossindo todos os dias, há pelo menos um mês, uma tosse\nseca horrível?, que ?o tempo não pode mudar, que a criança começa a espirrar e tossir?, e que ?só\nesse ano ela já precisou tomar antibiótico três vezes, tudo de tipo diferente, passado pelo médico\ndo posto de saúde, por gripe mal curada?. Por fim, relata que o quadro piorou desde que Tales, tio\nde Lana, voltou a morar com elas, há 6 meses, depois de cumprir pena de privação provisória de\nliberdade. Tales apresenta sintomas semelhantes e fuma todos os dias. A investigação\ncomplementar para esclarecer os diagnósticos diferenciais do quadro respiratório de Lana deve ser\ncomposta, fundamentalmente, de quais exames?","options":{"A":"Prova tuberculínica (PPD) e radiografia de tórax.","B":"Prova tuberculínica (PPD), radiografia de tórax e espirometria.","C":"Baciloscopia de escarro ou teste rápido molecular para tuberculose (TRM-TB) e radiografia de\ntórax.","D":"Baciloscopia de escarro ou teste rápido molecular para tuberculose (TRM-TB), radiografia de\ntórax e espirometria."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-350813","number":"350813","sourceNumber":"350813","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Lana, de 3 anos, é trazida para atendimento na UBS por sua avó, dona Benzarina. A\navó relata que a criança falta\nrecorrentemente à escola por ?estar sempre gripada?. Queixa-se de\nque ?a menina está sempre com nariz escorrendo e tossindo?, que ?toda noite ela dorme mal, com\ncrises de tosse?, que ?a menina está tossindo todos o dias há pelo menos um mês uma tosse seca\nhorrível?, que ?o tempo não pode mudar que a criança começa a espirrar e tossir? e que ?só esse\nano ela já precisou ficar internada três vezes por gripe mal curada?. Por fim, relata que o quadro\npiorou desde que Tales, tio de Lana, voltou a morar com elas depois de cumprir pena de privação\nprovisória de liberdade. Tales apresenta sintomas semelhantes e fuma todos os dias. A\ninvestigação clínico-laboratorial de Lana descartou tuberculose ativa, mas indicou infecção latente\n(ILTB). Assinale a alternativa que traz o esquema terapêutico vigente e recomendado.","options":{"A":"Regime de tratamento com Isoniazida (H) por seis a nove meses - (6H).","B":"Regime de tratamento com Isoniazida (H) e Rifapentina (P) por três meses - (3HP).","C":"Regime de tratamento com Isoniazida (H) e Rifapentina (P) por seis meses - (6HP).","D":"Regime de tratamento com Isoniazida (H) e Rifampicina (R) por quatro meses - (4RH)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-321341","number":"321341","sourceNumber":"321341","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Durante a reunião estratégica da sua equipe na UBS, foi relatado que não constavam\npessoas em tratamento para tuberculose em\nnenhuma das microáreas sob sua responsabilidade. A\nbase de dados do seu município indicava uma prevalência de tuberculose pulmonar bacilífera de 80\ncasos a cada 100.000 habitantes e a população adscrita nas suas microáreas era de 10.000\nhabitantes. Diante disso, os agentes comunitários foram capacitados para realizar busca ativa,\natravés da aplicação de questionário para identificação de Sintomáticos Respiratórios (SR),\ndetectando a presença de 100 SR. Sobre busca ativa do Sintomático Respiratório (SR), assinale a\nalternativa correta.","options":{"A":"Em população geral, corresponde à pessoa com presença de tosse seca por mais de três\nsemanas.","B":"Em população geral, corresponde à pessoa com presença de tosse produtiva por mais de três\nsemanas.","C":"Em algumas populações específicas de alto risco de adoecimento por tuberculose, pode\ncorresponder à pessoa com presença de tosse de qualquer duração.","D":"A investigação de Sintomáticos Respiratórios encaminhados à UBS, oriundos de busca ativa na\npopulação geral, consiste na coleta de escarro para baciloscopia e radiografia de tórax."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-321350","number":"321350","sourceNumber":"321350","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Isadora, de oito anos, vem acompanhada da avó para a consulta. A avó relata\ninapetência, perda ponderal progressiva, tosse\nseca, palidez e febre não aferida há quatro meses.\nRefere ainda que não trouxe a neta antes por dificuldade de locomoção à UBS. Quando\nquestionada a respeito dos pais de Isadora, relata que o pai está preso e que a mãe faleceu há um\nano por tuberculose. Ao exame físico, você nota quadro de desnutrição grave e ausculta pulmonar\nabolida em ápice à esquerda. Assinale a alternativa com a conduta a ser tomada.","options":{"A":"Solicitar baciloscopia de escarro e radiografia de tórax para diagnóstico de tuberculose por\nsistema de escore.","B":"Solicitar baciloscopia de escarro e prova tuberculínica para diagnóstico de tuberculose por\nsistema de escore.","C":"Solicitar baciloscopia de escarro, radiografia de tórax e prova tuberculínica para diagnóstico de\ntuberculose por sistema de escore.","D":"Estabelecer o possível diagnóstico clínico-epidemiológico de tuberculose pelo sistema de escore\ne iniciar tratamento para tuberculose\ncorrigido para o peso da paciente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-292857","number":"292857","sourceNumber":"292857","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Durante seu acompanhamento com Edmilson, você nota que a baciloscopia antes de\nreiniciar a RHZE foi positiva (3+), que a baciloscopia com 15 dias após reinício de tratamento\npersistiu positiva (1+), mas que ele ficou assintomático. A baciloscopia realizada após o primeiro\nmês de tratamento permaneceu positiva (1+). Em sua consulta, ao término do segundo mês de\ntratamento, você atende Edmilson, que está assintomático e com baciloscopia negativa. Assinale a\nalternativa correta em relação ao seguimento clínico.","options":{"A":"Considerando a persistência de baciloscopia positiva até o término do primeiro mês de\ntratamento, estender a fase de ataque (RHZE) por um terceiro mês e solicitar baciloscopias\nquinzenais.","B":"Considerando que o paciente evoluiu assintomático e a baciloscopia está negativa, iniciar a fase\nde manutenção (RH) por quatro meses e solicitar\nbaciloscopia de escarro em periodicidade mensal.","C":"Considerando que o paciente evoluiu assintomático e a baciloscopia está negativa, mas que o\npaciente tem histórico de abandono de tratamento prévio, estender a fase de ataque (RHZE) por\num terceiro mês e solicitar baciloscopia mensal.","D":"Considerando que o paciente evoluiu assintomático e a baciloscopia está negativa, mas que o\npaciente tem histórico de abandono de tratamento prévio, estender a fase de manutenção (RH) por\ntrês meses adicionais, totalizando sete meses de fase RH."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-259763","number":"259763","sourceNumber":"259763","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem de 62 anos recebe diagnóstico de tuberculose pulmonar bacilífera na Unidade\nBásica de Saúde. Seus contactantes são convocados à consulta médica, cujos dados constam na\ntabela a seguir: Qual dos contactantes tem indicação, neste momento, de terapia para infecção\nlatente com rifampicina?","options":{"A":"Neta.","B":"Nora.","C":"Filho.","D":"Esposa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/259763.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-234069","number":"234069","sourceNumber":"234069","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Mulher de 24 anos procura a Unidade Básica de Saúde (UBS) com queixas de febre\nvespertina, tosse produtiva com expectoração amarelada, hemoptoicos e perda de peso há 1 mês.\nNo retorno, traz raio X de tórax mostrando cavitação em lobo superior do pulmão direito. Após ter\nsido feito o diagnóstico da principal hipótese para o caso, qual a conduta a ser tomada, ainda na\nUBS, no momento da consulta?","options":{"A":"Teste rápido para HIV.","B":"Exame dos contactantes.","C":"Teste urinário de gravidez.","D":"Administração da primeira dose dos medicamentos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-199670","number":"199670","sourceNumber":"199670","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Adulto jovem, brasileiro, com história de tosse produtiva, febre irregular e astenia há 1\nmês. Fez uso de amoxicilina no início do quadro sem melhora clínica. Realizou três baciloscopias,\ntodas negativas para BAAR. Sua radiografia de tórax em PA é mostrada abaixo. Legenda: BAAR:\nBacilo Álcool-Ácido Resistente. Considerando que o paciente permanece com os mesmos\nsintomas, o exame mais indicado para confirmar o diagnóstico mais provável, neste momento seria:","options":{"A":"Broncoscopia.","B":"Escarro induzido.","C":"Cultura do escarro.","D":"Teste tuberculínico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/199670.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-173005","number":"173005","sourceNumber":"173005","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Mulher de 32 anos, usuária de crack e moradora de rua, em Fortaleza, é admitida para\ninvestigação de quadro de febre intermitente, perda de peso, tosse produtiva com hemoptoicos e\ndor torácica ventilatório-dependente à direita. Vinha em uso de levofloxacino há 1 semana. Ao\nexame, encontra-se emagrecida, pálida 2+/4+; ausculta: sopro tubário e roncos em terço superior\ndo hemitórax direito; restante normal. Exames iniciais: Hb = 9,5 g/dl (VR = 11,5-15,5 g/dl); Ht =\n25%\n(VR = 36-48%); leucócitos = 5.200 (VR = 4.000-10.000); plaquetas = 400.000 (VR =\n\n150.000-450.000); anti-HIV: não reagente; radiografia de tórax: cavitação em terço superior do\ncampo pulmonar direito e velamento do seio\ncostofrênico direito. Baciloscopia do escarro (2\namostras): negativas. Legenda: VR: Valor de Referência; Hb: Hemoglobina; Ht: Hematócrito.\nConsiderando a indisponibilidade de teste molecular e broncoscopia no seu hospital, qual a\nrecomendação CORRETA?","options":{"A":"Internar em isolamento para aerossóis e iniciar terapia empírica para tuberculose.","B":"Internar em leito convencional e iniciar terapia empírica para tuberculose.","C":"Internar em isolamento para aerossóis e aguardar cultura do escarro.","D":"Internar em leito convencional e aguardar cultura do escarro."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-173013","number":"173013","sourceNumber":"173013","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em reunião de equipe em uma unidade de atenção básica, o agente de saúde (ACS) é\ndemandado a realizar busca ativa de paciente faltoso à consulta do 3º mês de retratamento de\ntuberculose pulmonar. Na semana seguinte, o ACS relata que o paciente em questão, que é\ndependente de substâncias psicoativas, por estar se sentindo melhor, havia voltado às ruas\n(mesmo motivo do abandono anterior) e há 15 dias estava evadido do domicílio. Em relação ao\ntratamento diretamente observado, qual deve ser a proposta adotada pela equipe?","options":{"A":"Administrar tratamento na UBS quando o paciente retornar ao domicílio.","B":"Reiniciar tratamento na UBS após cessar o uso de substâncias psicoativas.","C":"Compartilhar supervisão do tratamento com a rede de atenção psicossocial.","D":"Indicar o tratamento e encaminhar para serviço de referência em infectologia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-150811","number":"150811","sourceNumber":"150811","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança de 3 anos mora com a avó, que recebeu diagnóstico de tuberculose pulmonar\nhá 1 mês e já iniciou tratamento. A família\nrealizou o protocolo solicitado e a criança não apresenta\nalterações clínicas e nem radiológicas, e o PPD é negativo. Não apresenta cicatriz de BCG e não\ntem caderneta de saúde. A mãe não lembra de ter aplicado a vacina. Como está classificado e qual\na conduta a ser adotada com essa criança?","options":{"A":"Contato com infecção ? quimioprofilaxia secundária com isoniazida por 6 meses.","B":"Contato sem infecção ? observação e repetição do teste tuberculínico em dois meses.","C":"Doente ? tratamento com esquema de curta duração com rifampicina, isoniazida e pirazinamida.","D":"Contato sem infecção ? quimioprofilaxia primária com isoniazida por 3 meses e repetição da\nprova tuberculínica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-127008","number":"127008","sourceNumber":"127008","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente de 48 anos, no sexto dia de seguimento por dengue, comparece à UPA por\nsonolência e tonturas. Na admissão, você observa extremidades frias, pulso filiforme de 120 ppm e\npressão arterial de 80 x 60 mmHg. Exames mostram albumina de 2,8 g/dl e Hematócrito (Ht) de\n49%. É feita, então, fase de hidratação com 20 ml/kg de soro Ringer lactato. Após 2h você observa\nedema de membros inferiores e novo Ht é de 48%. Conforme diretrizes atuais do Ministério da\nSaúde, qual dos itens abaixo representa próximo passo terapêutico?","options":{"A":"Hidroxietilamido 10 ml/kg.","B":"Albumina humana 1 g/kg.","C":"Cloreto de sódio 0,9% 10 ml/kg.","D":"Solução de Ringer lactato 20 ml/kg."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-127014","number":"127014","sourceNumber":"127014","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem de 65 anos é internado por quadro de febre diária e síndrome anêmica. Ao\nexame, você observa palidez, discretas petéquias em tronco e esplenomegalia Boyd III.\nHemograma mostrou pancitopenia, sorologia K-39 foi positiva assim como o mielograma mostrou\nLeishmanias. Outros exames mostraram ureia de 90 mg/dl e creatinina de 2,1 mg/dl. Não há\nantecedentes mórbidos relevantes. Com base nas diretrizes atuais do Ministério da Saúde, qual a\nescolha terapêutica adequada ao caso?","options":{"A":"Isotionato de pentamidina.","B":"Antimoniato de meglumina.","C":"Anfotericina B lipossomal.","D":"Anfotericina B desoxicolato."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-127019","number":"127019","sourceNumber":"127019","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Ao atender uma criança de 5 anos de idade na Emergência, o médico percebe um\nquadro clínico grave de Dengue. Assinale a alternativa que contém os critérios que o médico\nutilizou para chegar a essa conclusão.","options":{"A":"Hemorragia conjuntival.","B":"Vômitos e dor abdominal.","C":"Queda lenta das plaquetas.","D":"Diminuição repentina da temperatura corpórea ou hipotermia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-102129","number":"102129","sourceNumber":"102129","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente masculino, 34 anos, dá entrada na emergência com história de 5 dias de febre\nalta, cefaleia intensa, mialgia e náuseas.\nNegava artrite, artralgia ou coriza. No exame físico, chama\natenção a hiperemia conjuntival, faringite e um exantema maculopapular com descamação. Não há\nrelato de caso semelhante em sua região. O paciente é missionário e refere viagem para a Guiné\nhá 15 dias. Caso o paciente desenvolva choque associado a fenômenos hemorrágicos, sem quadro\nrespiratório relevante, a etiologia mais provável será:","options":{"A":"Ebola.","B":"Influenza.","C":"Hantavírus.","D":"Chikungunya."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-102140","number":"102140","sourceNumber":"102140","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança de quatro anos apresenta há vários dias: febre, dor abdominal, cefaleia,\nmialgia, artralgia, prostração, exantema. Há 48\nhoras a dor abdominal tornou-se mais intensa e\ncontínua; foi detectado hepatomegalia dolorosa, sonolência e hipotermia. RX de tórax revelou\npequeno derrame pericárdico. Qual a principal hipótese diagnóstica?","options":{"A":"Dengue.","B":"Influenza.","C":"Febre amarela.","D":"Meningococcemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81282","number":"81282","sourceNumber":"81282","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em casos de dengue hemorrágica, quais os sinais clínicos que podem ser indicativos\nde alarme para formas clínicas graves?","options":{"A":"Cefaleia intensa, hematúria, exantema.","B":"Persistência da febre alta, diarreia, gengivorragia.","C":"Recusa alimentar, dor retro-orbitária, plaquetopenia.","D":"Vômitos persistentes, dor abdominal intensa, melena."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81284","number":"81284","sourceNumber":"81284","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Após 15 dias de chuva intensa, um município do interior do Ceará ficou alagado. Os\nserviços de saúde foram danificados e parte da população ficou desabrigada. As escolas e creches\ntornaram-se moradias para mulheres e crianças. O médico de família passou a realizar\natendimentos nesses abrigos e percebeu aumento de casos de febre, icterícia rubínica, calafrios,\ncefaleia e mialgia nos atendimentos de demanda espontânea. Diante dessa situação, como deverá\nser a abordagem do médico e da sua equipe nesse momento?","options":{"A":"A vigilância epidemiológica deve ser acionada para realização da notificação compulsória.","B":"O médico deverá aguardar confirmação laboratorial dos casos suspeitos para realizar notificação\ncompulsória.","C":"A demanda programada deve ser priorizada para não prejudicar o trabalho da prevenção e\npromoção de saúde.","D":"A notificação compulsória deve ser feita, porém de forma sigilosa, só podendo ser divulgada fora\ndo âmbito médico-sanitário em caso de risco\npara a comunidade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-65754","number":"65754","sourceNumber":"65754","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente de 33 anos, sexo feminino, comparece a uma unidade de emergência de\nFortaleza com história de febre iniciada há\n6 dias. Evoluiu no segundo dia com aparecimento de\ncefaleia, mialgia e exantema. Nas últimas 24 horas, passou a apresentar dor abdominal, prostração\ne gengivorragia. Ao exame: PA = 60 x 40 mmHg; FC = 112 bpm; letárgica; eupneica; anictérica;\ndesidratada; corada; AP com murmúrio vesicular diminuído na base do hemitórax direito; fígado\ndoloroso e palpável 3 cm abaixo do RCD. Exames do segundo dia de evolução revelaram\nleucócitos 5.300/mm³; Ht 36%; plaquetas 232.000/mm³. Exames do sexto dia de evolução\napresentaram leucócitos 3.800/mm³; Ht 47%; plaquetas 22.000/mm³; albumina 3,0 g/dl; TGO = 150\nUI/L; TGP = 180 UI/L; BT = 0,8 mg/dl; BD = 0,3 mg/dl. RX de tórax com derrame pleural à direita.\n\nSorologia para dengue: IgG reagente; IgM reagente. Considerando o caso acima e a última diretriz\npara diagnóstico e tratamento da dengue da\nOrganização Mundial de Saúde, assinale a alternativa\nque representa a classificação clínica e o principal processo fisiopatológico envolvido:","options":{"A":"Dengue complicada; congestão pulmonar.","B":"Dengue clássica; formação de imunocomplexos.","C":"Febre hemorrágica da dengue; vasculite sistêmica.","D":"Dengue grave; aumento da permeabilidade capilar.","E":"Síndrome de choque da dengue; coagulopatia de consumo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-65705","number":"65705","sourceNumber":"65705","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um Centro de Saúde da Família se prepara para uma eventual epidemia de dengue\nnos próximos meses. O médico de família ficou\nencarregado de capacitar as Equipes de Saúde da\nFamília em relação às ações de controle vetorial. Neste contexto, o médico precisará enfatizar que:","options":{"A":"as larvas ainda não manifestam resistência ao temephós, e ele deve e pode ser aplicado em\nágua potável.","B":"o mosquito adulto já apresenta resistência aos inseticidas organoclorados, mas é sensível aos\norganofosforados.","C":"o Aedes aegypti é uma espécie antropofílica e tem hábitos noturnos, alimentando-se e\ndepositando seus ovos, preferencialmente, ao anoitecer.","D":"os organofosforados são pouco utilizados para o controle vetorial da dengue por não serem\nbiodegradáveis e se acumularem nos tecidos.","E":"a aplicação espacial de inseticida em ultrabaixo volume deve ser reservada para situações de\nsurtos epidêmicos, tendo em vista sua baixa eficácia, os danos ao meio ambiente e o custo\nelevado."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-65691","number":"65691","sourceNumber":"65691","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente masculino, 38 anos, caminhoneiro, natural e procedente de Cândido Mendes\n\n? MA, foi atendido na emergência de um hospital de referência para doenças infecciosas em\nFortaleza-CE, com história de febre com calafrios há 3 dias. Refere que os calafrios são intensos e\nseguidos de febre prolongada e sudorese profusa. Refere que trafegou por região endêmica para\nmalária no Maranhão há 2 semanas e que já teve malária duas vezes nos últimos 10 anos.\n\nConsiderando o caso acima, no que diz respeito ao tratamento, assinale a alternativa CORRETA:","options":{"A":"Os esquizonticidas sanguíneos agem nos gametócitos do parasito, objetivando a cura clínica.","B":"Para as infecções por P. vivax e P. ovale, são necessários medicamentos que atuem apenas na\nfase eritrocítica.","C":"O tratamento visa também eliminar os gametócitos, afetando, deste modo, manifestações\nclínicas agudas da doença e eventuais complicações.","D":"O objetivo imediato do tratamento da malária é erradicar as formas latentes do parasito no ciclo\ntecidual (hipnozoítos), impedindo recidivas da infecção.","E":"Os esquizonticidas teciduais atuam na forma pré-eritrocítica (exoeritrocítica), sendo\nfundamentais para a obtenção da cura radical nas infecções por P. vivax."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-51271","number":"51271","sourceNumber":"51271","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Qual a assertiva verdadeira em relação ao uso de inseticidas para o combate ao Aedes\naegypti em nosso meio?","options":{"A":"O inseticida atualmente mais utilizado para o controle de pupas no Brasil é o malathion.","B":"A principal substância empregada no país é o organofosforado temephos no controle de larvas.","C":"A substância utilizada pelos carros ?fumacê? é o Diclorodifeniltricloroetano (DDT) que tem ação\nsobre o mosquito adulto.","D":"O malathion é um organofosforadolarvicida que, adsorvido em grãos de areia numa formulação\ncontendo 1%, pode ser aplicado em água para o consumo humano."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-37450","number":"37450","sourceNumber":"37450","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"São sinais e sintomas suspeitos de dengue hemorrágica, em áreas com casos de\ndengue clássica:","options":{"A":"Febre, cefaleia, odinofagia e coriza, durante período epidêmico.","B":"Febre por mais de 10 dias e trombocitopenia.","C":"Febre alta com sorologia positiva para dengue.","D":"Febre aguda, cefaleia, diarreia.","E":"Febre aguda, prova do laço positiva, hematêmese,\nhipotensão."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-37605","number":"37605","sourceNumber":"37605","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Marque a opção INCORRETA:","options":{"A":"A forma clássica da leishmaniose visceral se apresenta com febre prolongada,\nhepatoesplenomegalia, pancitopenia, fraqueza e\nemagrecimento. Os sintomas surgem de alguns\nmeses até dois anos após a exposição.","B":"Na leishmaniose visceral, a maioria das infecções é sintomática, em uma razão de 1:10 ou 1:100\nem relação aos assintomáticos.","C":"O diagnóstico da leishmaniose visceral é feito pela identificação ou cultura do parasita em\nmaterial biopsiado de baço, fígado, medula óssea ou linfonodo.","D":"Os fatores de risco para o desenvolvimento da leishmaniose visceral sintomática incluem\ndesnutrição, uso de imunossupressores e infecção pelo HIV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-30895","number":"30895","sourceNumber":"30895","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Segundo as Novas Diretrizes do Ministério da Saúde para tratamento da leishmaniose\nvisceral, uma criança de 2 anos que\napresente icterícia e edema generalizado deverá receber\ntratamento inicial com:","options":{"A":"Antimoniato de N-metilglucamina.","B":"Anfotericina B lipossomal.","C":"Desoxicolato de anfotericina B.","D":"Pentamidina.","E":"Antimoniato de N-metilglucamina + alopurinol."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-22929","number":"22929","sourceNumber":"22929","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente masculino, 18 anos, morador de bairro sem saneamento básico na periferia de\ngrande cidade brasileira. Histórico de quadro progressivo de febre irregular (39ºC) com mal-estar,\ncefaleia, mialgia, anorexia, tosse, náuseas e vômitos, com piora a partir da segunda semana com\nintensificação da febre, prostração, delirium, apatia, dor abdominal difusa, diarreia. Apresentou\ntambém pápulas rosadas, cerca 3 mm cada, que desapareciam ao toque, localizadas no tronco.\n\nEncaminhado para emergência após ter iniciado quadro de enterorragia, dor abdominal difusa com\nperitonismo, tendo sido diagnosticada perfuração intestinal. O caso acima descrito é sugestivo de:","options":{"A":"tifo epidêmico","B":"dengue","C":"febre tifoide","D":"cólera","E":"N.R.A."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-22933","number":"22933","sourceNumber":"22933","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O agente etiológico do calazar (leishmaniose visceral) é:","options":{"A":"Leishmania braziliensis","B":"Leishmania guyanensis","C":"Leishmania amazonensis","D":"Leishmania lainsoni","E":"Leishmania donovani pático"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-24309","number":"24309","sourceNumber":"24309","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Deoclecio, 10 anos, atendido na emergência e com provável quadro de dengue,\npreocupou o plantonista por estar apresentando\num achado característico da síndrome de choque\nnessa doença. Por favor, marque a opção CORRETA.","options":{"A":"Exantema com intenso prurido","B":"Pressão arterial convergente (menor ou igual a 20 mmHg)","C":"Cefaleia acentuada","D":"Plaquetopenia"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-25387","number":"25387","sourceNumber":"25387","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A leptospirose é uma zoonose de ocorrência global, endêmica nos países tropicais,\nincluindo o Brasil. O acometimento renal é comum na sua forma grave. O correto manejo dos\npacientes é fundamental para a evolução favorável destes casos. Sobre o tratamento da\nleptospirose é correto afirmar:","options":{"A":"O tratamento dialítico deve ser criteriosamente indicado, uma vez que sua instituição precoce\ntem sido associada à redução da mortalidade.","B":"Tratamento específico é importante, uma vez que a Leptospira é altamente sensível a\ndeterminados antibióticos (ATB), incluindo a\npenicilina cristalina. Na literatura já há o consenso que\no ATB deva ser indicado na fase grave da doença (forma íctero-hemorrágica).","C":"O uso de diuréticos de alça tem sido indicado na admissão, uma vez que a forma oligúrica está\nassociada a um pior prognóstico.","D":"Hidratação venosa deve ser feita de maneira agressiva, com volumes acima de 3000 mL/dia,\numa vez que o componente pré-renal é\nfundamental na patogênese da insuficiência renal aguda na\nleptospirose.","E":"A reação de Jarisch-Herxheimer é comumente observada após o uso de penicilina cristalina,\ndevendo-se evitar o seu uso na leptospirose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-25350","number":"25350","sourceNumber":"25350","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma criança de 4 anos com Calazar foi admitida com quadro de febre, palidez,\nemagracimento, hepatoesplenomegalia e relato de\nepistaxe. Pela Classificação Nutricional de\nGomez foi considerado como Desnutrição Energético-Proteica de II Grau. De acordo com as\nrecomendações atuais do Ministério da Saúde do Brasil, o tratamento de primeira escolha neste\ncaso é: ? Brasil. Ministério da Saúde. Secretaria de Vigilância em Saúde. ? Leishmaniose\nvisceral grave: normas e condutas/Ministério da Saúde, Secretaria de Vigilância em Saúde,\nDepartamento de Vigilância Epidemiológica. ? Brasília: 6 Editora do Ministério da Saúde, 2006.\n\n? (Série A. Normas e Manuais Técnicos)","options":{"A":"Antimoniato de n-metil glucamina","B":"Desoxicolato de anfotericina B","C":"Anfotericina B lipossomal","D":"Miltefosine","E":"Alopurinol"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-24396","number":"24396","sourceNumber":"24396","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"As principais medidas de controle da leptospirose humana consistem em:","options":{"A":"Diagnóstico e tratamento precoces dos casos humanos.","B":"Detecção e eliminação dos canídeos infectados.","C":"Educação da população para a adequada higiene.","D":"<P>Controle dos ratos, como a desratização e a antirratização.</P>"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-25358","number":"25358","sourceNumber":"25358","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem, 24 anos, procurou assistência médica por apresentar febre alta, mialgia e dor\nretro-orbitária intensa há 4 dias. Ao exame, apresenta exantema petequial nos membros inferiores.\nA radiografia de tórax mostrou derrame pleural bilateral. O paciente evoluiu bem e a sorologia para\ndengue colhida dois dias depois foi positiva. Para a confirmação desse caso como Dengue\nHemorrágico necessita-se do resultado de:","options":{"A":"Leucograma","B":"Hemoglobina","C":"Albumina","D":"Plaquetas","E":"Prova do laço"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-7276","number":"7276","sourceNumber":"7276","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Quais as classes de drogas mais indicadas na terapia da disfunção assintomática do\nventrículo esquerdo?","options":{"A":"Betabloqueadores e inibidores da ECA.","B":"Inibidores da ECA e digitálicos.","C":"Diuréticos e antagonistas da aldosterona.","D":"Diuréticos e inibidores da ECA.","E":"Não se indica terapia medicamentosa para a disfunção ventricular assintomática."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-9028","number":"9028","sourceNumber":"9028","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na emergência pediátrica do IJF havia quatro crianças com DENGUE. Três delas foram\ninternadas com sinais de alarme da doença. Por favor, marque a opção na qual, a princípio, o (a)\npaciente está com um quadro de dengue clássica:","options":{"A":"Anita tem febre, cefaleia e dor retro-orbital.","B":"Bernardo tem dor abdominal intensa e contínua.","C":"Carla apresentou queda abrupta do número de plaquetas, hematêmese e melena","D":"Dorinha apresenta desconforto respiratório, extremidades frias e cianose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-6957","number":"6957","sourceNumber":"6957","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre a terceira bulha, é correto afirmar:","options":{"A":"É um som de alta frequência.","B":"É produzida nos átrios.","C":"É melhor audível com o diafragma do estetoscópio.","D":"É melhor audível com o paciente em decúbito lateral esquerdo.","E":"Ocorre no período de enchimento ventricular lento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-6965","number":"6965","sourceNumber":"6965","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na avaliação de um paciente com ascite de origem recente, assinale o item que melhor\ndefine a etiologia:","options":{"A":"Nível de glicose no líquido ascítico.","B":"Gradiente soro-ascítico de proteínas.","C":"Nível de LDH no líquido ascítico.","D":"Gradiente soro-ascítico de albumina.","E":"Gradiente soro-ascítico de LDH."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-8919","number":"8919","sourceNumber":"8919","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A ocorrência aumentada de leishmaniose visceral em crianças está principalmente\nassociada a:","options":{"A":"Susceptibilidade à infecção e depressão imunológica","B":"Hábitos precários de higiene","C":"Apresentação em indivíduos maiores de cinco anos","D":"Dificuldades no estabelecimento precoce do diagnóstico","E":"Famílias muito numerosas"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-9155","number":"9155","sourceNumber":"9155","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"São consideradas antroponoses:","options":{"A":"Gonorreia, coqueluche, ascaridíase e febre tifoide","B":"cisticercose, coqueluche, doença de Chagas e febre tifoide","C":"gonorreia, ascaridíase, leishmaniose visceral e doença de Chagas","D":"gonorreia, coqueluche, leishmaniose visceral e ascaridíase"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-9160","number":"9160","sourceNumber":"9160","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Das afirmativas relacionadas às propriedades dos agentes biológicos, assinale a\nFALSA:","options":{"A":"Todas as pessoas igualmente expostas a um agente infeccioso são infectadas","B":"Entre os infectados, alguns não apresentam sintomas durante o curso da infecção","C":"Os sinais e sintomas de doença podem ser de duração e grau variáveis","D":"A gravidade de uma infecção aparente é medida em termos da morbidade e mortalidade\nassociadas à doença"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-9146","number":"9146","sourceNumber":"9146","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para o Ministério da Saúde, a esquistossomose está presente, de forma endêmica, no\nBrasil:","options":{"A":"Nos estados do Centro-Oeste e do Nordeste","B":"do Pará até Bahia","C":"do Maranhão até Minas Gerais","D":"nos estados do Norte e do Nordeste"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-17820","number":"17820","sourceNumber":"17820","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre as leptinas, é correto afirmar que:","options":{"A":"inibe a melanocortina","B":"é antagonista da insulina","C":"estimula liberação de neuropeptídio Y","D":"inibe liberação do hormônio corticotrófico","E":"inibe liberação de orexinas"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-349753","number":"349753","sourceNumber":"349753","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma menina de cinco anos está em investigação por apresentar febre de origem não\nesclarecida há um mês, associada à perda de peso nas últimas semanas, sem outras queixas. Seu\npai, que morava na mesma casa, teve uma doença de pulmão, tratada por longo período, segundo\na pessoa que acompanha a menina. A radiografia de tórax apresenta imagens micronodulares\ndisseminadas. Ao exame físico: eupneica, ausculta pulmonar rude, com queixa de tosse eventual.\nA principal hipótese diagnóstica e orientação nesse caso serão:","options":{"A":"Histoplasmose pulmonar aguda / Fazer desinfecção do ambiente.","B":"Pneumonia atípica por vírus sincicial respiratório / Isolar por 15 dias.","C":"Tuberculose miliar pulmonar / Iniciar esquema preconizado.","D":"Pneumonia linfocítica intersticial / Broncoscopia.","E":"Pneumonia por Pneumocystis Carinii / Descolonizar com antibiótico via oral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-365610","number":"365610","sourceNumber":"365610","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O diagnóstico da tuberculose na infância é um desafio. Ele baseia-se em uma\ncombinação de critérios clínicos,\nepidemiológicos, associados a teste imunológico não específico\nde infecção tuberculosa e à radiografia de tórax. Até o momento, não existe um método\nconsiderado padrão-ouro. De acordo com as recomendações do Ministério da Saúde para o\ncontrole da tuberculose no Brasil, assinale a alternativa correta.","options":{"A":"O diagnóstico de infecção latente pelo M. tuberculosis é feito por meio de dados\nclínico-radiológicos.","B":"A dosagem sanguínea de interferon gama (IGRA) possui acurácia e valores preditivos\nsemelhantes à prova tuberculínica, mas não está\nindicada em crianças menores de 2 anos de\nidade.","C":"Na infância, as formas extrapulmonares são mais frequentes do que as formas pulmonares.","D":"Nos adolescentes, os aspectos radiológicos mais encontrados são infiltrados ou consolidações\nnos terços inferiores dos pulmões."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-284280","number":"284280","sourceNumber":"284280","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose é endêmica no Brasil e o aumento da sua incidência nas últimas décadas\nestá relacionado à epidemia do vírus HIV. A\nrespeito dessas patologias, julgue o item a seguir. O\nteste cutâneo com tuberculina (PPD) pode ser falso-positivo em pacientes com hanseníase e\n\nfalso-negativo em pacientes em uso de imunossupressores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-284307","number":"284307","sourceNumber":"284307","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma menina de um ano e oito meses de idade foi internada para tratamento de\npneumonia adquirida na comunidade, evoluindo de\nforma grave e permanecendo na UTI por quinze\ndias. Após retorno para a enfermaria, mantinha tosse, cansaço e imagem radiológica pulmonar\ninalterada. Foi realizado o PPD, que demonstrou valor de 12 mm. Na história familiar, o pai\napresentava tosse e emagrecimento há um mês e iniciara tratamento especifico há duas semanas\ne o irmão de quatro anos de idade era assintomático respiratório, com radiografia de tórax normal e\nPPD com valor de 5 mm. Com base nessa situação hipotética, julgue o item a seguir. De acordo\ncom o escore de pontos do Ministério da Saúde para o diagnóstico de tuberculose na infância, o\ndiagnóstico de tuberculose pulmonar é muito provável, com a recomendação de se iniciar o\ntratamento da doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-284308","number":"284308","sourceNumber":"284308","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma menina de um ano e oito meses de idade foi internada para tratamento de\npneumonia adquirida na comunidade, evoluindo de\nforma grave e permanecendo na UTI por quinze\ndias. Após retorno para a enfermaria, mantinha tosse, cansaço e imagem radiológica pulmonar\ninalterada. Foi realizado o PPD, que demonstrou valor de 12 mm. Na história familiar, o pai\napresentava tosse e emagrecimento há um mês e iniciara tratamento especifico há duas semanas\ne o irmão de quatro anos de idade era assintomático respiratório, com radiografia de tórax normal e\nPPD com valor de 5 mm. Com base nessa situação hipotética, julgue o item a seguir. Deve-se\niniciar isoniazida para o irmão da paciente, visando a tratar uma tuberculose latente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-284309","number":"284309","sourceNumber":"284309","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma menina de um ano e oito meses de idade foi internada para tratamento de\npneumonia adquirida na comunidade, evoluindo de\nforma grave e permanecendo na UTI por quinze\ndias. Após retorno para a enfermaria, mantinha tosse, cansaço e imagem radiológica pulmonar\ninalterada. Foi realizado o PPD, que demonstrou valor de 12 mm. Na história familiar, o pai\napresentava tosse e emagrecimento há um mês e iniciara tratamento especifico há duas semanas\ne o irmão de quatro anos de idade era assintomático respiratório, com radiografia de tórax normal e\nPPD com valor de 5 mm. Com base nessa situação hipotética, julgue o item a seguir. Deve-se\nprescrever isoniazida para a paciente durante a internação, visando à profilaxia de tuberculose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-284310","number":"284310","sourceNumber":"284310","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma menina de um ano e oito meses de idade foi internada para tratamento de\npneumonia adquirida na comunidade, evoluindo de\nforma grave e permanecendo na UTI por quinze\ndias. Após retorno para a enfermaria, mantinha tosse, cansaço e imagem radiológica pulmonar\ninalterada. Foi realizado o PPD, que demonstrou valor de 12 mm. Na história familiar, o pai\napresentava tosse e emagrecimento há um mês e iniciara tratamento especifico há duas semanas\ne o irmão de quatro anos de idade era assintomático respiratório, com radiografia de tórax normal e\nPPD com valor de 5 mm. Com base nessa situação hipotética, julgue o item a seguir. Deve-se\nrepetir o PPD do irmão da paciente em quatro semanas, para verificar viragem tuberculínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-284311","number":"284311","sourceNumber":"284311","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma menina de um ano e oito meses de idade foi internada para tratamento de\npneumonia adquirida na comunidade, evoluindo de\nforma grave e permanecendo na UTI por quinze\ndias. Após retorno para a enfermaria, mantinha tosse, cansaço e imagem radiológica pulmonar\ninalterada. Foi realizado o PPD, que demonstrou valor de 12 mm. Na história familiar, o pai\napresentava tosse e emagrecimento há um mês e iniciara tratamento especifico há duas semanas\ne o irmão de quatro anos de idade era assintomático respiratório, com radiografia de tórax normal e\nPPD com valor de 5 mm. Com base nessa situação hipotética, julgue o item a seguir. Deve-se\niniciar tratamento para tuberculose pulmonar se a bacterioscopia da paciente for positiva para\nBAAR no escarro ou no lavado gástrico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-255722","number":"255722","sourceNumber":"255722","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um paciente de 11 anos de idade apresenta linfonodomegalia cervical, dor de garganta,\nfebre, esplenomegalia e perda de peso. O médico\nentão solicita exames que demonstram\nlinfocitose linfócitos atípicos. Com base nesse caso e nos conhecimentos médicos correlatos, julgue\no item a seguir. Diante de casos de suspeita nos quais os anticorpos heterófilos vierem negativos,\nprovavelmente a sorologia também não será capaz de auxiliar no diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-239368","number":"239368","sourceNumber":"239368","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma paciente de 58 anos de idade, hipertensa, com história de mau controle,\nobesidade grau 1, dislipidêmica, tabagista\n40 anos/maços, com histórico de participação sem\nsucesso em programa de abandono ao tabagismo, é atendida em consulta de acolhimento em\nUnidade de Saúde da Família, após dois anos da última consulta agendada. Alega que procura\natendimento em razão da dor de intensidade grau quatro em hemitórax anterior esquerdo há dois\ndias, contínua, sem irradiações, realizando \"sinal do apontamento\" para demonstrar local exato da\ndor, sem fator gatilho ou fator de piora notados. Além disso, relata que vem apresentando tosse\nnão produtiva frequente há um mês, sem febre, dispneia, emagrecimento ou demais\ncomemorativos. Não vem fazendo uso das respectivas medicações, alegando que se esquece de\nadministrá-las. Leva boletim de atendimento em consulta realizada há duas semanas em unidade\nde pronto atendimento em razão da dor lombar, mostrando receita de corticoide intramuscular\nfornecida na alta, medicação da qual admite fazer uso com certa frequência, afirmando que esta\nsempre lhe é prescrita quando consulta na UPA. Mostra também exames realizados, há dois\nmeses, solicitados em consulta médica em clínica popular, com os seguintes resultados: Hb = 13,2\ng/dl, Ht = 37,1%, leucócitos = 7,2 mil, plaquetas = 148 mil, Cr = 1,1 mg/dl, Ur = 42 mg/dl,\ncolesterol\ntotal = 270 mg/dl, HDL = 38 mg/dl, LDL =192 mg/dl, triglicerídeos = 198 mg/dl e glicemia de jejum =\n123 mg/dl. Com relação a esse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. Há indicação de pesquisa de BAAR em pelo menos duas amostras de\nescarro, em razão de a paciente enquadrar-se nos critérios de sintomático respiratório.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177650","number":"177650","sourceNumber":"177650","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimeste da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos de patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatos, julgue o item a seguir. Para a prevenção de infecção latente no\nrecém-nascido, usa-se, como droga de escolha, a isoniazida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177655","number":"177655","sourceNumber":"177655","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimestre da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos de patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatos, julgue o item a seguir. O teste de Mantoux (PPD) deve ser\nrealizado por ocasião do nascimento, podendo-se vacinar a criança com BCG, se o PPD for menor\nque 5 mm.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177660","number":"177660","sourceNumber":"177660","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimeste da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos de patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatos, julgue o item a seguir. O uso de isoniazida deve ser mantida\nsempre por 6 meses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177666","number":"177666","sourceNumber":"177666","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimeste da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos de patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatos, julgue o item a seguir. Caso haja uma pessoa vivendo com\nHIV/AIDS na moradia de J.A.S. e não haja disponibilidade de PPD, deve-se realizar o tratamento\nde infecção latente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177593","number":"177593","sourceNumber":"177593","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimestre da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos e patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatados, julgo o item a seguir. Na ausência de PPD, C.A.S. deve\nreceber isoniazida por 12 meses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177601","number":"177601","sourceNumber":"177601","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimestre da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos e patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatados, julgue o item a seguir. A abordagem em relação à rede de\napoio da paciente e ao entendimento acerca da doença não são variáveis a serem consideradas na\navaliação da capacidade da paciente em aderir ao tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-140700","number":"140700","sourceNumber":"140700","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um pré-escolar de seis anos de idade, proveniente de área com índice de infestação de\n5% por Aedes aegypti, foi atendido em\nemergência hospitalar apresentando febre alta ?\ntemperatura axilar de 39 °C ?, prostração, dor retroorbitária, mialgia e exantema, sintomas que\npermaneciam havia quatro dias. Ao exame físico, foram observados os seguintes dados clínicos:\ntemperatura axilar de 38,5 °C, boca seca, turgor levemente diminuído, pressão arterial de 100\nmmHg x 70 mmHg ? percentil 95 da curva de pressão por idade ?, frequência respiratória de 40\nirpm e prova do laço negativa. Com relação a esse caso clínco, julgue o item seguinte. Essa criança\ndeverá receber terapia de reidratacão oral, para a reposição de líquidos, e anti-inflamatórios não\nhormonais ou salicilatos, para o controle da febre.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-135030","number":"135030","sourceNumber":"135030","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A dengue é a mais importante arbovirose humana e um grave problema de saúde\npública no Brasil. Acerca dessa doença, julgue o item subsecutivo. O Aedes aegypti, vetor da\ndengue e da febre amarela urbana, está presente em todos os estados brasileiros, mas chama\natenção o fato de não suportar temperaturas acima de 40 °C e abaixo de 5 °C.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-135034","number":"135034","sourceNumber":"135034","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A dengue é a mais importante arbovirose humana e um grave problema de saúde\npública no Brasil. Acerca dessa doença,\njulgue o item subsecutivo. A dengue provoca, em sua\nforma mais típica, dor abdominal intensa, hepatoesplenomegalia ocasional, hemorragias e choque,\nsintomas esses que podem aparecer isolados ou em grupo, bem como manifestar diferentes graus\nde intensidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-135017","number":"135017","sourceNumber":"135017","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito de doenças infectocontagiosas, julgue o item a seguir. Testes sorológicos\npara detecção de anticorpos das classes IgM e IgG\ndevem ser solicitados para indivíduos que\napresentem, há pelo menos três dias, sintomas clássicos de dengue, como dor abdominal intensa,\nvômitos persistentes, derrame cavitário, hepatomegalia e alteração do nível de consciência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-140737","number":"140737","sourceNumber":"140737","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito das doenças infecciosas, julgue o seguinte item. Nos casos de dengue em\nque ocorra plaquetopenia, as plaquetas\nrapidamente atingem valores superiores a 100.000/mm³\nentre dois e três dias, independentemente da terapia utilizada, o que representa uma rápida\nresolução dos imunocomplexos formados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-105538","number":"105538","sourceNumber":"105538","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O tratamento para dengue recomendado pelo Ministério da Saúde baseia-se na\nhidratação adequada, levando em consideração o\nestadiamento da doença em 4 grupos: A, B, C e\n\nD. Considerando essa informação, assinale a alternativa que apresenta uma característica do grupo\nB:","options":{"A":"Presença de petéquias.","B":"Prova do laço negativa.","C":"Oligúria.","D":"Choque cardiocirculatório.","E":"Insuficiência respiratória."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-108160","number":"108160","sourceNumber":"108160","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Julgue o item seguinte, relativo às doenças de acometimento comum na população. A\nsinovite é um achado comum nos pacientes portadores de dengue.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-108214","number":"108214","sourceNumber":"108214","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No que diz respeito ao estadiamento e ao tratamento dos casos suspeitos de dengue,\njulgue o item subsequente. Pacientes do\nsexo masculino, em idade adulta, com hematócrito de\n50%, plaquetas de 100.000/mm³ e leucócitos de 900/mm³ devem ser imediatamente encaminhados\npara tratamento hospitalar em unidade de terapia intensiva.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-108218","number":"108218","sourceNumber":"108218","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No que diz respeito ao estadiamento e ao tratamento dos casos suspeitos de dengue,\njulgue o item subsequente. Paciente com prova do laço negativa e ausência de manifestações\nhemorrágicas e de sinais de alarme deve ser tratado com hidratação oral, analgésicos e\nantitérmicos, devendo-se evitar a prescrição de AAS.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-108138","number":"108138","sourceNumber":"108138","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito das doenças infecciosas, julgue o item seguinte. Os achados laboratoriais da\nleishmaniose, zoonose na sua apresentação mais grave que é a visceral ou a calazar, incluem\nanemia, leucocitose, plaquetocitose e hipoalbuminemia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-82031","number":"82031","sourceNumber":"82031","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No que se refere à dengue, doença que afeta milhões de pessoas no mundo, julgue o\nitem subsecutivo. O vírus causador da dengue possui os sorotipos DEN-1, DEN-2, DEN-3 e DEN-4,\nsendo que a infecção por um deles confere proteção permanente para esse sorotipo e imunidade\nparcial e temporária contra os outros três tipos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-82041","number":"82041","sourceNumber":"82041","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No que se refere à dengue, doença que afeta milhões de pessoas no mundo, julgue o\nitem subsecutivo. Algumas das razões que tornaram trabalhosa a erradicação do mosquito Aedes\naegypti consistem no fato de o embrião do mosquito se desenvolver em apenas 48 horas em\ncondições de calor e umidade e de seus ovos sobreviverem até um ano em condições inóspitas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-82047","number":"82047","sourceNumber":"82047","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação à doenças respiratórias e infecciosas, julgue o item a seguir. A\nleptospirose, doença ubiquitária com período de\nincubação variável de três a treze dias, pode\napresentar-se tanto sem sintomatologia específica, assemelhando-se à síndrome gripal, quanto em\nquadros de icterícia grave, comprometendo as funções renal e hepática.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-82030","number":"82030","sourceNumber":"82030","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma paciente de dezoito anos de idade, moradora de Planaltina - DF, procurou o\npronto-socorro de um hospital relatando\nque apresentava, havia três meses, febre diária vespertina\nde 38°C associada a hiporexia e perda de 15 kg (mais de 10% do seu peso anterior). O exame\nfísico revelou palidez cutâneo-mucosa e hepatoesplenomegalia. O hemograma mostrou\npancitopenia com ausência de eosinófilos e, na dosagem de proteínas séricas, identificou-se\ninversão da relação albumina/globulina. Na revisão de sistemas, apurou-se a recente ocorrência de\nmorte de cães na vizinhança da casa do paciente. Com base no caso clínico apresentado acima,\njulgue o item a seguir. No caso em apreço, o tratamento da doença deve ser realizado o mais\nprecocemente possível com a indicação de uso do fármaco benzonidazol.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-82033","number":"82033","sourceNumber":"82033","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma paciente de dezoito anos de idade, morador de Planaltina - DF, procurou o\n\npronto-socorro de um hospital relatando que apresentava, havia três meses, febre diária vespertina\nde 38°C associada a hiporexia e perda de 15 kg\n(mais de 10% do seu peso anterior). O exame\nfísico revelou palidez cutaneomucosa e hepatoesplenomegalia. O hemograma mostrou\npancitopenia com ausência de eosinófilos e, na dosagem de proteínas séricas, identificou-se\ninversão da relação albumina/globulina. Na revisão de sistemas, apurou-se a recente ocorrência de\nmorte de cães na vizinhança da casa do paciente. Com base no caso clínico apresentado acima,\njulgue o item a seguir. O diagnóstico do caso em consideração pode ser feito por meio da\nintradermorreação de Montenegro.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-82037","number":"82037","sourceNumber":"82037","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma paciente de dezoito anos de idade, moradora de Planaltina - DF, procurou o\npronto-socorro de um hospital relatando\nque apresentava, havia três meses, febre diária vespertina\nde 38°C associada à hiporexia e perda de 15 kg (mais de 10% do seu peso anterior). O exame\nfísico revelou palidez cutaneomucosa e hepatoesplenomegalia. O hemograma mostrou\npancitopenia com ausência de eosinófilos e, na dosagem de proteínas séricas, identificou-se\ninversão da relação albumina/globulina. Na revisão de sistemas, apurou-se a recente ocorrência de\nmorte de cães na vizinhança da casa do paciente. Com base no caso clínico apresentado acima,\njulgue o item a seguir. A transmissão da doença em questão se dá pela picada de insetos\nflebotomídios do gênero Lutzomyia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-79656","number":"79656","sourceNumber":"79656","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa que apresenta a patologia que está diretamente vinculada ao\nrisco de contração em áreas onde há falta de tratamento de água.","options":{"A":"Dengue.","B":"Rubéola.","C":"Toxoplasmose.","D":"Sarampo.","E":"Leishmaniose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-88662","number":"88662","sourceNumber":"88662","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Julgue o item que se segue, relativo à leishmaniose visceral humana. O diagnóstico da\nleishmaniose visceral humana pode ser feito pela pesquisa direta do parasita em material coletado\npor punção da medula óssea realizada na crista ilíaca ou no esterno.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-88677","number":"88677","sourceNumber":"88677","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Julgue o item que se segue, relativo à leishmaniose visceral humana. O agente\netiológico da leishmaniose visceral humana é um\nprotozoário do gênero Leishmania, o qual pode\nser transmitido ao homem por meio da picada de um mosquito (flebotomíneo), sendo o cão o\nprincipal hospedeiro doméstico desse protozoário.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-88695","number":"88695","sourceNumber":"88695","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No que se refere às doenças infectocontagiosas e parasitárias, julgue o item\nsubsecutivo. No Brasil, a dengue não é considerada doença de notificação compulsória.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-64693","number":"64693","sourceNumber":"64693","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação ao atendimento a um paciente com dengue, assinale a alternativa que\napresenta os sinais de alarme, de acordo com o Ministério da Saúde.","options":{"A":"Hiporexia e prova do laço positiva.","B":"Hipotensão postural e leucopenia.","C":"Hematêmese e/ou melena e leucocitose.","D":"Dor abdominal intensa e contínua e vômitos persistentes.","E":"Área endêmica da dengue."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-32157","number":"32157","sourceNumber":"32157","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Desde 1986, no Brasil, têm emergido epidemias da dengue nos grandes centros\nurbanos. Acerca dessa doença, assinale a alternativa correta.","options":{"A":"O mosquito Aedes aegypti é o principal hospedeiro do vírus da dengue.","B":"A febre é o correspondente clínico mais importante da doença, cuja viremia dura em torno de\ndez a quatorze dias.","C":"As crianças com menos de um ano de idade podem ter adquirido passivamente anticorpos\nantidengue da mãe durante a gestação e, em uma\ninfecção primária pelo mesmo vírus, este pode\nproduzir a forma hemorrágica da doença.","D":"Somente os casos confirmados de dengue devem ser notificados à vigilância epidemiológica.","E":"Os pacientes com febre hemorrágica da dengue devem ser orientados para manutenção de\nrepouso e hidratação em casa, não havendo necessidade de internação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-27561","number":"27561","sourceNumber":"27561","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Desde 1986, o Brasil assistiu ao ressurgimento da dengue em território nacional, com\ndisseminação para quase a totalidade dos estados brasileiros. Quanto aos aspectos preventivos,\nfisiopatológicos e da assistência à doença NÃO é correto afirmar que:","options":{"A":"a suscetibilidade do hospedeiro, a imunidade preexistente, a magnitude e duração da viremia em\nhumanos relacionada à linhagem do vírus, além\nda densidade e comportamento da população\nvetorial são fatores que predispõem ao aparecimento de novas epidemias.","B":"a trombocitopenia, que frequentemente aparece no quadro clínico da dengue hemorrágica, tem\ncomo causa uma coagulopatia de consumo determinada pelo vírus e a presença de anticorpos\nantiplaquetários; são provavelmente resultantes da reação cruzada entre antígenos virais e\nantígenos presentes nas plaquetas.","C":"os exames específicos para diagnóstico de dengue têm, sobretudo, a finalidade de orientar\nações de vigilância epidemiológica, uma vez\nque a conduta terapêutica raramente será alterada em\nfunção da confirmação diagnóstica de dengue.","D":"a forma clínica conhecida como dengue hemorrágica/síndrome do choque por dengue, tem\ncomo alteração principal o extravasamento do plasma, na qual o paciente tem uma etapa febril,\nevoluindo posteriormente com trombocitopenia, hemoconcentração, derrames serosos (pleural,\nascítico ou pericárdico), hipotensão e choque, assim como hemorragias que podem colocar o\npaciente sob risco.","E":"a suscetibilidade à infecção é universal em humanos, devendo-se proceder à notificação dos\ncasos a partir de sua confirmação."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-366230","number":"366230","sourceNumber":"366230","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma mulher de 42 anos de idade apresenta queixa de \"\"anemia de longa data\"\". À\nrevisão de sistemas, relata episódios\nrecorrentes de epistaxe espontâneas desde a infância, com\nmúltiplas idas ao Pronto Atendimento, especialmente em dias de clima seco. A paciente informa ter\ntratado a anemia anteriormente com diferentes reposições de sulfato ferroso, mas sem alcançar a\ncura. Destaca que considera isso normal, pois seu pai, irmãos e sobrinha enfrentam quadros\nsemelhantes. Quanto aos antecedentes, não apresenta comorbidades prévias. No exame físico,\nobserva-se palidez cutaneomucosa e a presença de várias telangiectasias cutâneas, algumas\nlocalizadas nas palmas das mãos e plantas dos pés, além de afetar a mucosa oral conforme\nimagem acima. Considerando o quadro clínico apresentado, bem como os assuntos correlatos,\nJulgue o item a seguir. Embora seja rara Actinomicose do sistema nervoso central, abcessos\ncerebrais únicos ou múltiplos são os mais comuns e a condição clínica do paciente aumenta o risco\nde abcessos cerebrais por Actinomyces como potencial agente etiológico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/366230.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-343388","number":"343388","sourceNumber":"343388","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Considerando os tipos dos aspectos do escarro e suas possíveis causas, é CORRETO\nafirmar:","options":{"A":"Mucopurulento: carcinoma de células alveolares.","B":"Geleia de framboesa: pneumonia estreptocócica.","C":"Róseo com bolhas de ar: edema pulmonar.","D":"Sanguíneo: infecção por Klebsiella Pneumoniae."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-291511","number":"291511","sourceNumber":"291511","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um paciente de 35 anos de idade, vivendo com HIV/AIDS há alguns anos, sem adesão\nà terapia antirretroviral indicada (TARV), é\ninternado em hospital de média complexidade com\nquadro de tosse produtiva, febre e dor torácica, associados à imagem radiológica compatível com\ncondensação em base direita, sendo iniciado tratamento com amoxicilina-clavulanato. Revendo os\nexames de admissão do paciente, o médico que o atende percebe que o infiltrado radiológico evolui\ncom áreas de cavitação, o que o leva a considerar a hipótese diagnóstica de tuberculose pulmonar\natípica, decorrente da presença de imunossupressão. Visando a proceder à investigação\ndiagnóstica indicada no caso, a recomendação atual da Organização Mundial de Saúde é que o\nteste diagnóstico de 1.ª linha para tais pacientes com doença pulmonar ativa, tendo ainda a\nvantagem de detectar resistência antimicrobiana, seria","options":{"A":"pesquisa de bacilo álcool-ácido resistente no escarro.","B":"realização de ensaio de liberação de gama-interferon no sangue periférico.","C":"amplificação automatizada de ácido nucleico (ensaio Xpert MTB/RIF) no escarro.","D":"cultura de escarro (meio de Lowenstein-Jensen)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-291523","number":"291523","sourceNumber":"291523","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um homem, com 20 anos de idade, desempregado, reside em casa de madeira com\num cômodo junto com o pai, mãe e 5 irmãos. Ele\nprocurou a unidade de saúde da família, com\nqueixa de tosse, febre e dispneia há mais ou menos 2 meses, inicialmente aos esforços e,\nposteriormente, em repouso. Nega Tuberculose (TB) anterior. Relata que o pai teve tuberculose,\nporém abandonou o tratamento 2 vezes. Há 6 meses, foi solicitado investigação dos contatos,\nconsiderando o reingresso após abandono do tratamento do pai, porém nenhum dos membros da\nfamília compareceu à unidade para avaliação clínica e/ou realizou os exames. No atendimento de\nhoje, o paciente realizou teste rápido (lgM/lgG) para covid-19 com resultado negativo. Aplicando as\nevidências científicas, preceitos éticos e legais, assinale a afirmativa com a melhor conduta.","options":{"A":"Realizar avaliação clínica, coletar e encaminhar 3 amostras de escarro para realizar baciloscopia\nde escarro, teste molecular rápido para a TB\n(TMR-TB) e cultura de escarro, solicitar raio-X, realizar\no teste rápido para o HIV, orientar o uso de máscara de tecido, agendar nova consulta e investigar\nos contatos.","B":"Realizar avaliação clínica, coletar e encaminhar 3 amostras de escarro para realizar baciloscopia\nde escarro, teste molecular rápido para a TB\n(TMR-TB) e cultura de escarro, solicitar raio-X, realizar\no teste rápido para o HIV, orientar o uso de máscara de cirúrgica, investigar os contatos e\nencaminhar o paciente para o serviço de referência.","C":"Realizar avaliação clínica, coletar e encaminhar 2 amostras de escarro para realizar teste\nmolecular rápido para a TB (TMR-TB) e cultura\nde escarro, solicitar raio-X, realizar teste rápido para\no HIV, orientar o uso de máscara cirúrgica, agendar nova consulta e investigar os contatos.","D":"Realizar avaliação clínica, coletar e encaminhar 2 amostras de escarro para realizar baciloscopia\ne cultura de escarro, solicitar raio-X,\nrealizar teste rápido para o HIV, orientar o uso de máscara\n\nN-95, agendar nova consulta e investigar os contatos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-266490","number":"266490","sourceNumber":"266490","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Wilson, de 63 anos de idade, negro, aposentado, procurou uma Unidade Básica de\nSaúde (UBS) na região administrativa de São\nSebastião, por apresentar tosse havia 4 semanas,\nfebre vespertina e um episódio de hemoptise. Luísa, médica recém-formada, o atendeu no\nconsultório reservado para casos suspeitos de covid-19. Wilson realizou o teste rápido IgG/IgM\npara SARS-CoV-2, que resultou positivo. Considerando que a sensibilidade do referido teste rápido\nseja de 80% e que a sua especificidade seja de 90%, julgue o item a seguir, referentes ao caso\nclínico apresentado. Havendo confirmação diagnóstica de tuberculose em Wilson, recomenda-se o\nrastreamento de HIV, que deverá ser consentido pelo paciente, observando-se o sigilo e a\nconfidencialidade e utilizando-se os algoritmos diagnósticos estabelecidos para esse fim.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-266491","number":"266491","sourceNumber":"266491","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Wilson, de 63 anos de idade, negro, aposentado, procurou uma unidade básica de\nsaúde (UBS) na região administrativa de São\nSebastião, por apresentar tosse havia 4 semanas,\nfebre vespertina e um episódio de hemoptise. Luísa, médica recém-formada, o atendeu no\nconsultório reservado para casos suspeitos de covid-19. Wilson realizou o teste rápido IgG/IgM\npara SARS-CoV-2, que resultou positivo. Considerando que a sensibilidade do referido teste rápido\nseja de 80% e que a sua especificidade seja de 90%, julgue o item a seguir, referentes ao caso\nclínico apresentado. Wilson deve ser considerado sintomático respiratório e, com base nisso, Luísa\ndeve realizar a notificação compulsória de caso suspeito de tuberculose no Sistema Nacional de\nAgravos de Notificação (SINAN).","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-263426","number":"263426","sourceNumber":"263426","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um homem com 24 anos de idade comparece à Unidade de Saúde da Família do seu\nbairro. Há uma semana, iniciou quadro de tosse produtiva, febre de 38ºC e inapetência. Afirmou\nfazer uso regular de antirretrovirais para tratamento de HIV/aids há 2 anos. Houve emagrecimento\nde 5 kg nos últimos seis meses. Sem alterações na ausculta pulmonar e cardíaca ou nos demais\nitens do exame físico. Qual deve ser a conduta médica para a investigação diagnóstica desse\npaciente, além da solicitação de radiografia de tórax?","options":{"A":"Solicitar teste rápido molecular para tuberculose caso haja alteração na radiografia de tórax.","B":"Solicitar teste rápido molecular para tuberculose e, se negativo, indicar a cultura de escarro\ncom\nteste de sensibilidade.","C":"Solicitar teste rápido molecular para tuberculose e cultura de escarro com teste de sensibilidade\njá na primeira consulta.","D":"Solicitar teste rápido molecular para tuberculose e cultura de escarro com teste de sensibilidade\nsomente se resistência à rifampicina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-291550","number":"291550","sourceNumber":"291550","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um paciente masculino, 33 anos de idade, agricultor, é internado com quadro de\ncansaço, adinamia, tosse, emagrecimento\nimportante nos últimos 6 meses (cerca de 14 kg). Ao\nexame, mostra-se emagrecido, mucosas pouco coradas, ausculta pulmonar com murmúrio\nvesicular preservado, estertores bilaterais. Tomografia de tórax apresenta lesões em brotamento\ncom suspeita de tuberculose pós-primária. Diante desse caso, quais são, respectivamente, o\ndiagnóstico diferencial, o exame a ser solicitado para confirmação da tuberculose e o tratamento a\nser instituído?","options":{"A":"Pneumonia por estafilococo; solicitar pesquisa de BK e fungo em escarro; iniciar tratamento com\nrifampicina.","B":"Pneumonia por paracoccidioidomicose; solicitar biópsia tran-brônquica; iniciar rifampicina,\nisoniazida, pirazinamida.","C":"Pneumonia por estafilococo; solicitar lavado bronco alveolar para pesquisa de BK; iniciar\nrifampicina e pirazinamida.","D":"Pneumonia por paracoccidioidomicose; solicitar pesquisa de BK e fungo no escarro; iniciar\nrifampicina, isoniazida, pirazinamida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-230625","number":"230625","sourceNumber":"230625","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Estima-se que em 2015 cerca de 10,4 milhões de pessoas desenvolveram Tuberculose\n(TB), 580 mil na forma de TB Multirresistente\n(TB MDR) ou TB Resistente à Rifampicina (TB RR), e\n1,4 milhão morreram da doença. Os pilares e componentes da Estratégia pelo Fim da Tuberculose\nsão listados abaixo, indique a alternativa ERRADA:","options":{"A":"Prevenção e cuidado integrado e centrado no paciente.","B":"Diagnóstico precoce","C":"Teste de sensibilidade antimicrobiano universal.","D":"Investigação sistemática dos contatos e das populações menos vulneráveis."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-227451","number":"227451","sourceNumber":"227451","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação às demandas de saúde na atenção primária à saúde (APS), relacionadas\nàs doenças infecciosas e transmissíveis, julgue\no item que se segue. A Organização Mundial da\nSaúde (OMS) estima que um quarto da população mundial tenha infecção latente por tuberculose\n(ILTB), condição em que a pessoa, mesmo infectada, permanece saudável por anos, com\nimunidade parcial ao bacilo, sem apresentar sintomas, mas com transmissibilidade baixa do bacilo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-230633","number":"230633","sourceNumber":"230633","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Estudos sugerem que o adoecimento por TB resulta da relação entre determinantes\nprovenientes de diferentes níveis, podemos apenas CONCORDAR que:","options":{"A":"Determinantes a comunidade e ambiente domiciliar, mas não características individuais.","B":"Os padrões de vida em uma comunidade conformam a posição socioeconômica domiciliar.","C":"Oportunidades individuais em termos de educação, ocupação, qualidade da habitação e\ninterações sociais não interagem.","D":"A transmissão e adoecimento por TB não são influenciados por fatores demográficos, sociais e\neconômicos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-230638","number":"230638","sourceNumber":"230638","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A probabilidade de uma pessoa ser infectada depende de fatores exógenos. Assim,\nsomente podemos determinar como ERRADA a alternativa:","options":{"A":"Entre eles, pode-se citar a infectividade do caso-fonte, a duração do contato e o tipo de\nambiente partilhado.","B":"Os pacientes com exame bacteriológico de escarro positivo não sustentam a cadeia de\ntransmissão da doença.","C":"Estima-se que uma pessoa com baciloscopia positiva infecte de 10 a 15 pessoas em média, em\numa comunidade, durante um ano.","D":"Entre pessoas que têm contatos duradouros com pacientes com TB pulmonar, aqueles com\nBAAR positivo no escarro são os que mais\ntransmitem a doença."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-206119","number":"206119","sourceNumber":"206119","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A radiografia de tórax é um método complementar importante na investigação da\ndoença e deve ser solicitada para todo\npaciente com suspeita clínica de tuberculose pulmonar. Em\ncasos raros, mesmo existindo a doença, a radiografia do paciente pode não apresentar alterações.\nSendo INADEQUADO que:","options":{"A":"Diferentes achados radiológicos apontam para a suspeita de doença em atividade ou anterior.","B":"Existem diversas imagens radiológica patognomônicas de tuberculose.","C":"Sempre devem ser realizados exames laboratoriais comprobatórios.","D":"As principais funções do exame radiológico em pacientes com baciloscopia positiva são excluir\noutra doença pulmonar associada e avaliar a extensão do acometimento e sua evolução\nradiológica, sobretudo nos pacientes que não respondem ao tratamento antituberculose."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-225148","number":"225148","sourceNumber":"225148","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um menino de 4 anos de idade foi encaminhado ao ambulatório de pediatria porque\nsua mãe havia sido recém-diagnosticada com\ntuberculose pulmonar, com tratamento iniciado havia\n3 semanas. Na consulta, a criança apresentava sinais\n\ngripais com tosse seca e coriza hialina havia 10 dias, sem febre. O cartão vacinal estava completo\ne, no exame físico, foi constatada apenas a\npresença de coriza e de cicatriz de bacilo de\n\nCalmette-Guérin (BCG). O pediatra solicitou radiografia de tórax e derivado proteico purificado\n(PPD). O resultado da radiografia foi normal,\nao passo que o do PPD foi de 4 mm. Com relação a\nesse caso clínico, julgue o item que se segue. Considerando os sinais e sintomas respiratórios\napresentados\n\npela criança, deve-se iniciar o tratamento de tuberculose com o esquema RIPE (esquema 1 do\nMinistério da Saúde).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-212101","number":"212101","sourceNumber":"212101","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um menino de 4 anos de idade foi encaminhado ao ambulatório de pediatria porque\nsua mãe havia sido recém-diagnosticada com\ntuberculose pulmonar, com tratamento iniciado havia\n3 semanas. Na consulta, a criança apresentava sinais gripais com tosse seca e coriza hialina havia\n10 dias, sem febre. O cartão vacinal estava completo e, no exame físico, foi constatada apenas a\npresença de coriza e de cicatriz de Bacilo de Calmette-Guérin (BCG). O pediatra solicitou\nradiografia de tórax e derivado proteico purificado (PPD). O resultado da radiografia foi normal, ao\npasso que o do PPD foi = 4 mm. Com relação a esse caso clínico, julgue o item que se segue. A\ncriança deve ser isolada dos outros familiares e afastada da escola, pelo risco de estar com\ntuberculose pulmonar, na forma bacilífera, que ocorre na sua faixa etária.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-212121","number":"212121","sourceNumber":"212121","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um menino de 4 anos de idade foi encaminhado ao ambulatório de pediatria porque\nsua mãe havia sido recém-diagnosticada com\ntuberculose pulmonar, com tratamento iniciado havia\n3 semanas. Na consulta, a criança apresentava sinais gripais com tosse seca e coriza hialina havia\n10 dias, sem febre. O cartão vacinal estava completo e, no exame físico, foi constatada apenas a\npresença de coriza e de cicatriz de Bacilo de Calmette-Guérin (BCG). O pediatra solicitou\nradiografia de tórax e Derivado Proteico Purificado (PPD). O resultado da radiografia foi normal, ao\npasso que o do PPD foi de 4 mm. Com relação a esse caso clínico, julgue o item que se segue.\n\nDiante dos resultados da radiografia de tórax e PPD, é correto concluir que essa criança tem\ngrande risco de apresentar tuberculose.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-212103","number":"212103","sourceNumber":"212103","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um menino de 4 anos de idade foi encaminhado ao ambulatório de pediatria porque\nsua mãe havia sido recém-diagnosticada com\ntuberculose pulmonar, com tratamento iniciado havia\n3 semanas. Na consulta, a criança apresentava sinais gripais com tosse seca e coriza hialina havia\n10 dias, sem febre. O cartão vacinal estava completo e, no exame físico, foi constatada apenas a\npresença de coriza e de cicatriz de Bacilo de Calmette-Guérin (BCG). O pediatra solicitou\nradiografia de tórax e Derivado Proteico Purificado (PPD). O resultado da radiografia foi normal, ao\npasso que o do PPD foi de 4 mm. Com relação a esse caso clínico, julgue o item que se segue.\n\nDeve ser solicitada uma baciloscopia do escarro para afastar o diagnóstico de tuberculose na\nreferida criança.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-206114","number":"206114","sourceNumber":"206114","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para prevenção da transmissão da tuberculose nas unidades de saúde, devem ser\nimplementadas nas unidades de saúde as seguintes etapas. Determine qual está INCORRETA:","options":{"A":"Reconhecer o Sintomático Respiratório SR ou paciente com TB pulmonar ativa é o primeiro\npasso nas medidas administrativas. Pode ser\nobtido com a preparação de um profissional de saúde\npara realizar a busca ativa de SR em todo paciente que chega à unidade, interrogando a presença\ne duração da tosse.","B":"Oferecer ao SR máscara cirúrgica para uso durante sua permanência na unidade e instruí-lo\ncom relação à etiqueta da tosse (levar o braço ou\nlenço à boca quando tossir).","C":"SR ou pacientes com TB de vias aéreas em atividade ainda infectantes devem esperar\natendimentos ou procedimentos em áreas fechadas ventiladas.","D":"Priorizar o atendimento do paciente no serviço, independentemente do motivo da procura. O\npaciente deve passar à frente na fila de consultas, exames e/ou dispensa de medicamentos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-206146","number":"206146","sourceNumber":"206146","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"As medidas de proteção individual consistem no uso correto de máscaras adequadas,\npor profissionais de saúde, em situações e ambientes\nde maior risco. Sendo INADEQUADO que:","options":{"A":"o uso de máscaras (respiradores) no atendimento de sintomático respiratório SR ou pacientes\ncom TB deve ser feito de forma criteriosa.","B":"muitos profissionais dedicam a esse item valor prioritário, negligenciando medidas\nadministrativas e de controle ambiental, que\ncertamente têm maior impacto na sua proteção e nos\ndemais pacientes.","C":"não podemos confiar nas máscaras tipo PFF2? padrão brasileiro e da União Europeia . Apenas\na N95 ? padrão dos Estados Unidos? é eficaz\npara a proteção de profissionais de saúde.","D":"as máscaras devem ser utilizadas somente em áreas de alto risco de transmissão, como quartos\nde isolamento respiratório, sala\n\nde escarro induzido."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-183924","number":"183924","sourceNumber":"183924","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Acerca das infecções e suas implicações clínico-cirurgícas, julgue o próximo item. A\ntuberculose pulmonar gera, com frequência, a dissociação clínico-radiológica, situação\ncaracterizada pela existência de sinais e sintomas clínicos exuberantes e ausência de alterações\nsignificativas nos exames de imagem do tórax.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-183903","number":"183903","sourceNumber":"183903","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação ao tratamento das doenças infecciosas e parasitárias, julgue o item que se\nsegue. São exemplos de efeitos maiores ? aqueles que implicam interrupção ou alteração do\nregime terapêutico ? no tratamento da tuberculose: nefrite tubulointersticial associada ao uso de\netambutol; rabdomiólise com mioglobinúria e insuficiência renal associada ao uso de isoniazida; e\nneuropatia periférica decorrente do uso de pirazinamida.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177240","number":"177240","sourceNumber":"177240","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito das medidas de bloqueio e de rastreio epidemiológico relativas à\ntuberculose, assinale a alternativa correta.","options":{"A":"Quando houver recém-nascido de mulher diagnosticada com tuberculose bacilífera durante a\ngestação, tal criança deve receber vacina BCG ao nascer e receber tratamento com isoniazida por\n3 meses, seguido por prova tuberculínica, para se definir a continuidade do tratamento.","B":"Recém-nascidos de mãe HIV positiva, mas sem sintomas da Aids, devem receber a vacina BCG\nao nascer.","C":"No caso de recém-nascido de mãe com tuberculose bacilífera, caso não haja prova tuberculínica\ndisponível, o tratamento com isoniazida\ndeve ser realizado por 6 meses.","D":"Moradores do mesmo domicílio que paciente com tuberculose bacilífera que possuam\ninsuficiência renal em tratamento dialítico\ndevem ser submetidos ao tratamento da infecção latente\nse a prova tuberculínica for de 5 mm.","E":"O uso de insulina é fator de risco definidor no tratamento ou não da infecção latente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-168462","number":"168462","sourceNumber":"168462","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma criança com 4 anos de idade, cujos pais são diagnosticados com tuberculose\npulmonar, está em acompanhamento em unidade\nbásica de saúde. Ela apresenta cartão vacinal\ncompleto, crescimento e desenvolvimento adequados e está assintomática. Realizou radiografia de\ntórax, que não apresentou alteração, e o teste tuberculínico (PPD), que apresentou enduração de 5\n\nmm. Considerando-se o quadro clínico dessa criança, o tratamento da tuberculose latente\n(quimioprofilaxia):","options":{"A":"Deverá ser realizado, pois ela apresenta enduração do PPD de 5 mm e ausência de tuberculose.","B":"Não deverá ser realizado, pois a presença dessa enduração está relacionada à vacina BCG.","C":"Deverá ser realizado, pois os pais são bacilíferos e estão em tratamento para tuberculose.","D":"Não deverá ser realizado, pois, para isso, a enduração deveria ser de pelo menos 10 mm."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-159567","number":"159567","sourceNumber":"159567","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito do tratamento da tuberculose (TB) no Brasil, julgue o item seguinte. De\nacordo com o Programa Nacional de Controle da\nTuberculose, do Ministério da Saúde (2009), o\ntratamento da TB, em adultos e adolescentes, deve combinar o uso dos seguintes fármacos:\nRifampicina, Isoniazida e Etambutol, de modo que este último deve ser adminstrado durante dez\nmeses ininterruptamente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-159577","number":"159577","sourceNumber":"159577","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito do tratamento da Tuberculose (TB) no Brasil, julgue o item seguinte. Um\nesquema adequado de tratamento para TB deve,\nobrigatoriamente, apresentar as seguintes\ncaracterísticas básicas: ter atividade bacteriostática ? capacidade de eliminar o maior número de\nbacilos o mais rápido possível; prevenir o surgimento de resistência ? evita-se a resistência com\nredução máxima do tempo de uso de fármacos anti-TB; e apresentar ação esterilizante ?\ncapacidade de evitar a seleção de bacilos mutantes resistentes.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-158059","number":"158059","sourceNumber":"158059","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Nos últimos anos, há grandes dificuldades na atenção primária à saúde no que tange a\nabordagem de contactantes de pacientes com tuberculose bacilífera na ausência do teste\ntuberculínico (PPD). Considerando os conhecimentos de medicina preventiva e a Nota Informativa\nnº 8/2014, CGPNTC/DEVEP/SVS/MS, assinale a alternativa CORRETA quanto à abordagem de\nneonatos de mãe bacilífera.","options":{"A":"Havendo disponibilidade de PPD, indica-se não vacinar com BCG ao nascer, tratar com\nisoniazida por seis meses e realizar PPD após para avaliar resposta.","B":"Havendo disponibilidade de PPD, não se deve vacinar com BCG ao nascer, e sim tratar com\nisoniazida por três meses e realizar PPD. Caso PPD > 5 mm, iniciar esquema RIP.","C":"Na ausênia de PPD, os neonatos devem ser tratados com isoniazida por três meses e apenas\napós serem vacinados com BCG.","D":"Na ausência de PPD, os neonatos devem realizar esquema RIP por três meses e depois devem\nser vacinados com BCG, apenas.","E":"Na ausência de PPD, os neonatos devem receber tratamento com isoniazida por seis meses e\nvacinação com BCG apenas após o tratamento."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-97826","number":"97826","sourceNumber":"97826","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um paciente com 45 anos de idade, casado e com três filhos (8 meses, 7 anos e 12\nanos de idade), trabalhador da construção\ncivil, tem histórico de febre vespertina, tosse e\nemagrecimento há seis meses. Radiografia de tórax mostra infiltrado em lobo superior direito\ncontendo cavitação e a baciloscopia do escarro é positiva para tuberculose. Em relação à avaliação\ndos contatos do paciente, é correto afirmar que:","options":{"A":"Nos contatos crianças (< 10 anos), a Prova Tuberculínica menor que 5 mm exclui o diagnóstico\nde tuberculose.","B":"Nos contatos crianças (< 10 anos), assintomáticos, o tempo de vacinação com BCG é fator\nimportante na definição da conduta.","C":"Nos contatos adultos ou adolescentes (>10 anos ), assintomáticos, não há necessidade de\nsolicitação da Prova Tuberculínica.","D":"Nos contatos sintomáticos adultos, o diagnóstico de tuberculose é estabelecido pela cultura de\nescarro positiva para Bacilo de Koch (BK)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-97793","number":"97793","sourceNumber":"97793","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um paciente com 42 anos de idade é atendido no ambulatório de uma Unidade Básica\nde Saúde com quadro de tosse com expectoração\namarelada há mais de três semanas,\nacompanhada de febre vespertina. É submetido à realização de exame de escarro para pesquisa\nde bacilos álcool-ácido-resistentes (BAAR), que é positiva (+++/4+). Informa que reside com a\nesposa, que apresenta os mesmos sintomas. O casal não tem filhos. Diante dessas informações, a\ninvestigação da esposa deverá ser feita com","options":{"A":"realização de prova tuberculínica.","B":"solicitação de radiografia de tórax e PPD.","C":"encaminhamento para tratamento em posto de saúde.","D":"solicitação de radiografia de tórax e baciloscopia de escarro."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-64447","number":"64447","sourceNumber":"64447","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Os sintomas iniciais da febre hemorrágica da dengue não diferem muito da dengue em\nsua forma clássica, porém há um agravamento\ndos sintomas entre o terceiro e quarto dia de\nevolução, com manifestações hemorrágicas e risco de colapso circulatório. O teste rápido para\ndetecção de casos de febre hemorrágica da dengue sem necessidade de exames laboratoriais\nconsiste:","options":{"A":"Punção venosa","B":"Medida da pressão arterial contínua","C":"Permeabilidade arterial","D":"Medida contínua da temperatura corpórea","E":"Prova do laço"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-75488","number":"75488","sourceNumber":"75488","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A Unidade Básica de Saúde de uma pequena cidade é responsável pela atenção a um\nasilo municipal. Em uma das visitas ao asilo, o médico atende um homem de 78 anos de idade com\nquadro de tosse produtiva há aproximadamente um mês. O paciente dorme em um quarto com\noutros três idosos, e, na instituição, vivem ao todo 23 idosos. Já fez uso de antialérgico e\nazitromicina - 500 mg por 5 dias, sem melhora. Após coleta de escarro, é feito diagnóstico de\ntuberculose pulmonar e iniciado tratamento. Qual a conduta a ser adotada em relação aos\ncontactantes?","options":{"A":"Os três idosos que dividem o quarto com o paciente índice devem ser tratados para tuberculose.","B":"Todos os contatos devem coletar duas amostras de escarro para exame de BAAR.","C":"Somente os sintomáticos respiratórios devem ser investigados para tuberculose.","D":"Contatos assintomáticos devem realizar prova\ntuberculínica.","E":"Todos os contatos devem realizar raio-X de tórax."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-137552","number":"137552","sourceNumber":"137552","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um homem de 40 anos de idade é atendido na Unidade Básica de Saúde (UBS) com\nquadro de anorexia, perda de peso e\nadinamia, associados a tosse e discreta falta de ar, iniciado\nhá 30 dias. Ao exame físico foi constatado: paciente emagrecido, IMC 16 kg/m , PA = 110 x 70\nmmHg, FC = 88 bpm, FR = 20 irpm, sopro cavitário no ápice pulmonar esquerdo. Que exames são\nindicados para a elucidação diagnóstica nesse caso?","options":{"A":"Hemograma completo, anti-HIV 1 e 2 e radiografia de tórax.","B":"Pesquisa de BAAR no escarro e radiografia de tórax.","C":"Pesquisa de BAAR no escarro, cultura do escarro pelo método Ogawa-Kudoh e radiografia de\ntórax.","D":"Baciloscopia do escarro, radiografia de tórax e técnica\nmolecular de reação em cadeia mediada pela polimerase.","E":"Cultura do escarro pelo método Löwestein-Jensen e técnica molecular e reação em cadeia\nmediada pela polimerase."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-137596","number":"137596","sourceNumber":"137596","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na Unidade Básica de Saúde (UBS), após o diagnóstico de tuber culose\n(BAAR+++), a mãe de uma criança com sete\nanos de idade, iniciou o tratamento. A criança\nnão apresenta\n\nsintomatologia e foi vacinada com BCG ao nascer. Qual a conduta mais adequada a ser\nseguida em relação à criança?","options":{"A":"Solicitar baciloscopia de escarro e, se o exame for negativo,\nrecomendar\n\nreavaliação em seis meses.","B":"Solicitar baciloscopia de escarro, exame\n\nradiológico do tórax e prova tuberculínica e, se todos forem negativos ou normais, dar alta para a\ncriança.","C":"Solicitar prova\n\ntuberculínica e, se superior a 10 mm, iniciar o tratamento completo com os medicamentos da\nprimeira e segunda fases, conforme norma vigente no país.","D":"Solicitar prova tuberculínica e, se superior a 5 mm, sem achados radiológicos, indicar\ntratamento da infecção latente.","E":"Iniciar tratamento\nprofilático com\n\nhidrazida até 3 meses após a negativação do escarro da mãe."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-137562","number":"137562","sourceNumber":"137562","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma mulher de 29 anos iniciou tratamento para tuberculose pulmonar cavitária há\nduas semanas, com o esquema Rifampicina +\nHidrazida + Pirazinamida + Etambutol. Durante a\nconsulta para avaliação dos exames solicitados, o médico observa que o teste confirmatório\npara detecção do HIV é positivo. Nesse contexto, além do aconselhamento da paciente e\ntestagem de parceiros, a conduta mais adequada para a paciente é","options":{"A":"manutenção do tratamento para tuberculose e\n\nencaminhamento para serviço de referência, mantendo o acompanhamento à paciente.","B":"suspensão do tratamento para tuberculose e encaminhamento para serviço de referência,\nmantendo o acompanhamento à paciente.","C":"suspensão temporária do esquema terapêutico para a tuberculose, início da terapia\nantirretroviral; retomada do tratamento para tuberculose após 30 dias.","D":"alteração do tratamento, com prolongamento da duração para 9 meses: Rifampicina +\nHidrazida + Pirazinamida + Etambutol por 2 meses e Rifampicina + Hidrazida por 7 meses.","E":"substituição do esquema terapêutico da tuberculose para Estreptomicina + Etambutol +\nLinesolida + Pirazinamida + T erizidona por 2 meses e Etambutol + Linesolida + T erizidona\npor 4 meses."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-138580","number":"138580","sourceNumber":"138580","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente, com 49 anos de idade, sexo masculino, lavrador, vem à consulta com queixa\nde lesão em face que iniciou-se como uma\npápula, posteriormente evoluindo com ulceração e\nindolor. A primeira lesão apareceu há 3 meses, sendo seguida de mais duas com as mesmas\ncaracterísticas. Associado ao aparecimento das lesões evoluiu com emagrecimento, não sabendo\nquantificar, porém notou que suas roupas estão mais largas que o habitual. Não apresentou quadro\nsemelhante antes. Relata tabagismo e etilismo desde a infância. Não refere uso de medicamentos.\nDurante o exame físico, foram visualizadas lesões ulceradas, de bordas elevadas, com fundo\ngranuloso em região labial inferior e mentoniana. Foi realizado raspado para exame direto e biópsia\nda lesão. Em ambos os exames foram encontradas formas leveduriformes com múltiplos\nbrotamentos pequenos, em roda de leme. Reação de Montenegro negativa. Qual o diagnóstico e\ntratamento de escolha? (VER IMAGENS)","options":{"A":"Paracoccidioidomicose e itraconazol.","B":"Esporotricose e solução saturada de Iodeto de\npotássio.","C":"Carcinoma de células escamosas e cirurgia.","D":"Tuberculose cutânea e R (Rifampicina) ? H\n(Isoniazida) ? Z (Pirazinamida) ? E (Etambutol).","E":"Leishmaniose cutânea e glucantime."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/138580.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-138718","number":"138718","sourceNumber":"138718","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança, com 5 anos de idade, mora com os pais em bairro de periferia. Seu pai é\nfumante, há três meses apresenta tosse\ncrônica, produtiva, sudorese noturna e febre diária e não\nprocura cuidados médicos. Sua mãe é aparentemente saudável. Há três semanas, a criança iniciou\ntosse produtiva com escarro purulento, febre ao final da tarde e emagrecimento. O cartão de\nvacinas demonstra que ele foi vacinado com BCG ID no primeiro ano de vida. No atendimento é\nconstatada temperatura oral de 37,5 °C, taquipneia e redução de murmúrio vesicular em terço\nmédio do hemitórax direito. O exame radiológico do tórax mostra condensação homogênea em\nápice de pulmão direito. O PPD é de 10 mm. Qual a conduta terapêutica para essa criança?","options":{"A":"quimioprofilaxia primária.","B":"quimioprofilaxia secundária e controle com exames\na cada 2 meses.","C":"revacinar com BCG e controle com exames a cada 2 meses.","D":"esquema tríplice (2HRZ ) e duplo (4HR) e controle\ncom exames a cada 2 meses.","E":"esquema quádruplo 2(HRZE) e duplo (5HR) e controle com exames a cada 2 meses."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-8712","number":"8712","sourceNumber":"8712","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A febre amarela e a dengue são doenças cujas estruturas epidemiológicas apresentam\nsemelhanças. A respeito desses agravos, julgue o próximo item. No ciclo urbano, o mosquito Aedes\naegypti é o principal vetor de transmissão do vírus da febre amarela e do vírus da dengue.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-8713","number":"8713","sourceNumber":"8713","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A febre amarela e a dengue são doenças cujas estruturas epidemiológicas apresentam\nsemelhanças. A respeito desses agravos, julgue o próximo item. Os agentes etiológicos da febre\namarela e da dengue são vírus pertencentes ao mesmo gênero Flavivirus, tendo sido já\nidentificados quatro sorotipos para cada uma dessas doenças.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-8714","number":"8714","sourceNumber":"8714","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A febre amarela e a dengue são doenças cujas estruturas epidemiológicas apresentam\nsemelhanças. A respeito desses agravos, julgue o próximo item. A febre amarela silvestre é\nclinicamente mais grave que a febre amarela urbana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-8715","number":"8715","sourceNumber":"8715","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A febre amarela e a dengue são doenças cujas estruturas epidemiológicas apresentam\nsemelhanças. A respeito desses agravos, julgue o próximo item. A imunidade duradoura adquirida\ncontra o vírus da dengue é específica para cada sorotipo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-19210","number":"19210","sourceNumber":"19210","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Considerando o caso de um paciente diabético que faz uso de 40 UI/dia de insulina e\nque será submetido a colecistectomia\nvideolaparoscópica, julgue o seguinte item. Nesse paciente,\nos níveis de glicemia intraoperatória devem permanecer entre 120 mg/dL e 180 mg/dL.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-19222","number":"19222","sourceNumber":"19222","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um paciente de 45 anos de idade, assintomático, apresentou, em exame de rotina,\nglicemia de jejum de 145 mg/dL. Na\nreavaliação, o resultado desse exame foi de 139 mg/dL. A\npressão arterial desse paciente, que pesa 95 kg e mede 1,75 m de altura, era de 138 mmHg × 88\nmmHg. A circunferência abdominal do paciente, que negou aumento de peso recentemente e\napresentou alterações de reflexos tendíneos, era de 140 cm. Considerando o caso clínico descrito,\njulgue o item que se segue. Nesse caso, deve-se prescrever imediatamente metformina ao\npaciente, pois alterações no estilo de vida nessa fase da doença não seriam úteis nem eficazes\npara o seu controle.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-351603","number":"351603","sourceNumber":"351603","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre as apresentações e manifestações da tuberculose (TB), é INCORRETO afirmar\nque:","options":{"A":"A apresentação da tuberculose na forma pulmonar, além de ser mais frequente, é também a\nmais relevante para a saúde pública.","B":"A tuberculose pleural é a forma mais comum de TB extrapulmonar em indivíduos HIV\nsoronegativos, e ocorre mais em jovens.","C":"A tuberculose ganglionar periférica é a forma mais frequente de TB extrapulmonar em pacientes\nHIV soropositivos e crianças, sendo mais comum\nabaixo dos 40 anos.","D":"A tuberculose miliar é uma forma grave de doença e ocorre em até 50% dos casos de TB em\npacientes HIV soropositivos, em fase avançada de imunossupressão."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-346873","number":"346873","sourceNumber":"346873","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Apesar de ser uma enfermidade antiga, a tuberculose continua sendo um importante\nproblema de saúde pública. Sobre a tuberculose, é CORRETO afirmar que:","options":{"A":"Os bacilos que se depositam em roupas, lençóis, copos e outros objetos facilmente se\ndispersam em aerossóis e, por isso, podem ajudar na transmissão da doença.","B":"Embora o risco de adoecimento seja maior nos primeiros 2 anos após a primoinfecção, uma vez\ninfectada, a pessoa pode adoecer em qualquer momento da sua vida.","C":"Com o início do esquema terapêutico adequado, a transmissão tende a diminuir gradativamente\ne, em geral, após 5 dias de tratamento, chega\na níveis insignificantes.","D":"A suscetibilidade à infecção é praticamente universal. A maioria dos infectados posterga o\nadoecimento após a infecção e desenvolve imunidade total à doença."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-337657","number":"337657","sourceNumber":"337657","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A Tuberculose (TB) é uma doença que pode ser prevenida e curada, mas ainda\nprevalece nas condições de pobreza e contribui\npara a perpetuação da desigualdade social. Sobre\no tratamento da tuberculose, assinale a alternativa INCORRETA:","options":{"A":"Em geral, após duas a três semanas de tratamento com esquema anti TB que contenham\nfármacos com atividade bactericida precoce,\nocorre significativa diminuição da capacidade de\ntransmissão de bacilos pelos indivíduos doentes.","B":"Para a prevenção da seleção de bacilos resistentes e a efetiva cura da doença, é necessária a\nutilização de esquemas terapêuticos com associação de diferentes medicamentos que agirão sobre\nos bacilos sensíveis e nos naturalmente resistentes.","C":"O tratamento de formas extrapulmonares tem a duração de seis meses, mas no caso do\ntratamento de TB em pacientes com HIV, a duração se prolonga para oito meses.","D":"O esquema de tratamento da tuberculose é padronizado, deve ser realizado de acordo com as\nrecomendações do Ministério da Saúde e compreende duas fases: a intensiva ( ou de ataque ), e a\nde manutenção."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-345747","number":"345747","sourceNumber":"345747","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose primária é mais frequente em crianças, mas pode também ocorrer em\nadultos. Sendo correto que:","options":{"A":"Na infância, em razão da facilidade de se estabelecer o diagnóstico baciloscópico, os métodos\nde imagem têm papel menos relevante.","B":"Na infância, em razão da facilidade de se estabelecer o diagnóstico baciloscópico, os métodos\nde imagem têm papel menos relevante.","C":"Na infância, em razão da dificuldade de se estabelecer o diagnóstico baciloscópico, os métodos\nde imagem têm papel ainda mais relevante.","D":"Na infância, em razão da dificuldade de se estabelecer o diagnóstico baciloscópico, os métodos\nde imagem são contraindicados."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-345749","number":"345749","sourceNumber":"345749","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Entre as múltiplas formas de apresentação da doença tuberculose, os achados\nradiográficos mais comuns são representados por alterações associadas:","options":{"A":"Incluindo opacidade(s) parenquimatosa(s), segmentar(es) ou lobar(es), e linfonodomegalias\nhilares e nunca as mediastinais, que\ndeterminam redução volumétrica do pulmão (epituberculose),\nsendo a síndrome do lobo médio a expressão mais conhecida.","B":"Incluindo opacidade(s) parenquimatosa(s), segmentar(es) ou lobar(es), e linfonodomegalias\nhilares e/ou mediastinais, que determinam\naumento volumétrico do pulmão (epituberculose), sendo\na síndrome do lobo médio a expressão mais conhecida.","C":"Incluindo opacidade(s) parenquimatosa(s), segmentar(es) ou lobar(es), e linfonodomegalias\nhilares e/ou mediastinais, que determinam\nredução volumétrica do pulmão (epituberculose), sendo\na síndrome do lobo superior a expressão mais conhecida.","D":"Incluindo opacidade(s) parenquimatosa(s), segmentar(es) ou lobar(es), e linfonodomegalias\nhilares e/ou mediastinais, que determinam\nredução volumétrica do pulmão (epituberculose), sendo\na síndrome do lobo médio a expressão mais conhecida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-345751","number":"345751","sourceNumber":"345751","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A Tuberculose secundária ou de reinfecção:","options":{"A":"É a forma mais comum de adoecimento entre adolescentes e não entre adultos e, nesses, o\ncomprometimento dos pulmões ocorre em 85-90% dos casos.","B":"É a forma mais comum de adoecimento entre adolescentes e adultos e, nesses, o\ncomprometimento dos pulmões ocorre em 85- 90% dos casos.","C":"É a forma mais comum de adoecimento entre adolescentes e adultos e, nesses, o\ncomprometimento dos pulmões ocorre em 5- 9% dos casos.","D":"É a forma mais rara de adoecimento entre adolescentes e adultos e, nesses, o\ncomprometimento dos pulmões ocorre em 85-90% dos casos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-345753","number":"345753","sourceNumber":"345753","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Embora a radiografia do tórax seja o mais importante método de imagem no diagnóstico\ne acompanhamento de pacientes com tuberculose, a TC é\numa realidade cada vez mais presente.\nEstá correto que:","options":{"A":"A TC é menos sensível e específica do que a radiografia do tórax, podendo demonstrar\nalterações iniciais ainda imperceptíveis pelo\nmétodo radiográfico, e deve ser realizada em pacientes\nsintomáticos respiratórios com alterações mal definidas ou duvidosas nos quais o contexto\n\nclínico-epidemiológico aponta para a possibilidade de tuberculose.","B":"A TC é mais sensível e específica do que a radiografia do tórax, podendo demonstrar alterações\niniciais ainda imperceptíveis pelo método\nradiográfico, e nunca deve ser realizada em pacientes\nsintomáticos respiratórios com alterações mal definidas ou duvidosas nos quais o contexto\n\nclínico-epidemiológico aponta para a possibilidade de tuberculose.","C":"A TC é mais sensível e menos específica do que a radiografia do tórax, podendo demonstrar\nalterações iniciais ainda imperceptíveis pelo\nmétodo radiográfico, e deve ser realizada em pacientes\nsintomáticos respiratórios com alterações mal definidas ou duvidosas nos quais o contexto\n\nclínico-epidemiológico aponta para a possibilidade de tuberculose.","D":"A TC é mais sensível e específica do que a radiografia do tórax, podendo demonstrar alterações\niniciais ainda imperceptíveis pelo método\nradiográfico, e deve ser realizada em pacientes\nsintomáticos respiratórios com alterações mal definidas ou duvidosas nos quais o contexto\n\nclínico-epidemiológico aponta para a possibilidade de tuberculose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-313284","number":"313284","sourceNumber":"313284","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O Ministério da Saúde aponta uma lista de reações adversas dos fármacos utilizados\nnos Esquemas Especiais e de Tuberculose\ndrogarresistentes (TB DR) e condutas preconizadas.\nDessa lista, estão associados à neurite óptica os fármacos:","options":{"A":"Etambutol e Linezolida.","B":"Amicacina e Capreomicina.","C":"Estreptomicina e Moxifloxacino.","D":"Bedaquilina e Clofazimina.","E":"Etionamida e Pirazinamida."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-291638","number":"291638","sourceNumber":"291638","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente, sexo feminino, queixa de tosse seca há cerca de 7 dias, seguida de\naparecimento de escarro purulento, inodoro,\nfebre de 38,5ºC e dor pleurítica nas últimas 48 horas.\nTeve perda ponderal de quase 10% do peso nas últimas 3 semanas. RX de tórax com consolidação\nno lobo superior direito e adenomegalias mediastinais ipsilaterais. Os sinais vitais eram estáveis\ne a\npaciente estava em regular estado geral. Qual alternativa abaixo inclui a propedêutica adequada no\ncaso?","options":{"A":"Iniciar com azitromicina e liberar para tratamento ambulatorial.","B":"Coletar hemocultura e cultura de escarro.","C":"Coletar escarro para pesquisa BAAR.","D":"Solicita biópsia de massa pulmonar.","E":"Realizar fibrobroncoscopia com biópsia transbrônquica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-291956","number":"291956","sourceNumber":"291956","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose continua sendo mundialmente um importante problema de saúde,\nexigindo o desenvolvimento de estratégias para o seu controle, considerando aspectos\nhumanitários, econômicos e de saúde pública. São ações de vigilância epidemiológica para a\ntuberculose, EXCETO:","options":{"A":"Definição, investigação do caso e notificação.","B":"Acompanhamento e encerramento dos casos.","C":"Exame e tratamento profilático de todos os contatos.","D":"Visita domiciliar a caso novo e convocação de faltosos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-232105","number":"232105","sourceNumber":"232105","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Qual o esquema básico para tratamento da tuberculose, na fase intensiva, em\npacientes com 10 anos de idade ou mais,\npreconizado pelo Ministério da Saúde, para casos novos\nde tuberculose pulmonar e/ou extrapulmonar (exceto a forma meningoencefálica e osteoarticular),\ninfectados ou não pelo HIV?","options":{"A":"RHZE (150/75/400/275 mg) ? comprimido em dose fixa combinada. Pacientes com 20 a 35 kg: 2\ncomprimidos; 36 a 50 kg: 3 comprimidos, e > 50 kg: 4 comprimidos, durante 2 meses.","B":"Rifampicina (RFM): dose mensal de 600 mg (2 cápsulas de 300 mg) com administração\nsupervisionada, e Dapsona (DDS): dose mensal\nde 100 mg supervisionada e dose diária de 100 mg\nautoadministrada.","C":"RHb (150/75 mg) ? comprimido em dose fixa combinada. Pacientes com 20 a 35 kg: 2\ncomprimidos; 36 a 50 kg: 3 comprimidos, e > 50 kg: 4 comprimidos, durante 2 meses.","D":"Rifampicina (RFM): dose mensal de 600 mg (2 cápsulas de 300 mg) com administração\nsupervisionada, Dapsona (DDS): dose mensal de 100\nmg supervisionada e uma dose diária de 100\nmg autoadministrada, e Clofazimina (CFZ): dose mensal de 300 mg (3 cápsulas de 100 mg) com\nadministração supervisionada e uma dose diária de 50 mg autoadministrada.","E":"Rifampicina (RFM): dose mensal de 600 mg (2 cápsulas de 300 mg) com administração\nsupervisionada, Dapsona (DDS): dose mensal de 100\nmg supervisionada e uma dose diária de 100\nmg autoadministrada, e Isoniazida (H): dose diária de 200 mg (2 comprimidos de 100 mg) com\nadministração supervisionada."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-227081","number":"227081","sourceNumber":"227081","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem de 45 anos se queixa de tosse produtiva com escarro claro, dispneia, perda de\napetite e emagrecimento há 3 meses. Nega febre, sudorese noturna ou outras queixas. É lavrador\ne não está conseguindo exercer as funções por causa de fraqueza. Desconhece comorbidades e\nnega uso de medicamentos. É etilista e tabagista. Ao exame físico, está alerta e orientado, com\nmucosas hipocoradas, hidratadas e anictéricas. Está emagrecido. Palpam-se linfonodomegalias\ncervicais. A oroscopia revela lesão granulada no palato mole. Há roncos holorrespiratórios na\nausculta pulmonar em ambos os hemitórax. Sem outras anormalidades ao exame. Foi realizada\nradiografia do tórax e exame do escarro. Radiografia de tórax: exame do escarro (visualização\ndireta): Considerando o caso descrito, assinale a alternativa que apresenta o tratamento MAIS\nADEQUADO para esse paciente:","options":{"A":"Amoxicilina + clavulanato e azitromicina.","B":"Levofloxacino.","C":"Rifampicina, isoniazida, pirazinamida e etambutol.","D":"Sulfametoxazol + trimetoprima."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/227081.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-234433","number":"234433","sourceNumber":"234433","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Escolar de 6 anos é internado em enfermaria para investigação de quadro respiratório.\nApresenta redução do apetite, perda de peso e tosse persistente há mais de 2 semanas mesmo\napós uso de amoxicilina-clavulanato por 7 dias. A criança mora com o avô que também está\ntossindo há mais de 2 meses. Em relação à principal suspeita clínica do caso em questão, é\nCORRETO afirmar que:","options":{"A":"O diagnóstico pode ser feito através de um sistema de pontuação que leva em consideração\ndados clínicos, radiológicos e epidemiológicos.","B":"A prova tuberculínica não está indicada no caso, pois a vacina BCG feita ao nascimento pode\nocasionar resultado falso-positivo.","C":"O tratamento consiste em 2 meses de rifampicina, isoniazida, pirazinamida e etambutol e 4\nmeses de rifampicina e isoniazida.","D":"A profilaxia com isoniazida deve ser iniciada para o avô da criança por se tratar de um caso de\ninfecção latente pelo M. tuberculosis."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-246752","number":"246752","sourceNumber":"246752","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com 66 anos, etilista, admitido no PS com relato de tosse produtiva (secreção\namarela espessa) há 21 dias, dispneia a médios esforços e febre intermitente diária, sem horário\npredominante, perda ponderal não quantificada. Relata ter feito uso de amoxicilina clavulanato por\n7 dias, sem melhora. Na admissão, estava normotenso e com dispneia leve. Qual seria a\npropedêutica inicial adequada:","options":{"A":"Rx de tórax, hemocultura, hemograma, ureia e creatinina e gasometria arterial","B":"Rx de tórax, hemocultura, hemograma, ureia e creatinina, gasometria arterial, coleta de escarro\npara pesquisa de baar/micobacteria","C":"Hemograma, ureia, creatinina e gasometria arterial","D":"Rx de tórax e coleta de escarro para pesquisa de baar/micobacteria","E":"Rx de tórax e hemograma"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-227113","number":"227113","sourceNumber":"227113","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose continua sendo mundialmente um importante problema de saúde,\nexigindo o desenvolvimento de estratégias para o seu controle, considerando aspectos\nhumanitários, econômicos e de saúde pública. Sobre as recomendações para o controle da\ntuberculose no Brasil, assinale a alternativa INCORRETA:","options":{"A":"A busca ativa do sintomático respiratório deve ser realizada permanentemente por todos os\nserviços de saúde e tem sido uma estratégia recomendada internacionalmente.","B":"O tratamento diretamente observado deve ser realizado para todo caso de tuberculose, pois não\né possível predizer os casos que irão aderir\nao tratamento.","C":"O exame microscópico direto (baciloscopia direta), por ser um método simples e seguro, deve\nser realizado por todo laboratório público de\nsaúde e pelos laboratórios privados tecnicamente\nhabilitados.","D":"A vacina BCG é prioritariamente indicada para crianças de 0 a 4 anos. Lactentes que foram\nvacinados e não apresentem cicatriz vacinal após seis meses, devem ser revacinados quantas\nvezes forem necessárias, até que se forme a cicatriz."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-199580","number":"199580","sourceNumber":"199580","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O time de futebol tailandês \"Javalis Selvagens\" ficou confinado em uma caverna devido\na uma inundação por um período superior a 1\nsemana. Caso essa caverna estivesse localizada no\nBrasil, a quais doenças esse grupo estaria exposto?","options":{"A":"Paracoccidioidomicose, toxoplasmose, leptospirose.","B":"Febre maculosa, leptospirose, tuberculose.","C":"Histoplasmose, tuberculose, paracoccidioidomicose.","D":"Leptospirose, histoplasmose, hantavirose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-220323","number":"220323","sourceNumber":"220323","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à tuberculose, são medidas de controle ambiental e de proteção individual\nem serviços que atendam grande quantidade de\npacientes bacilíferos, EXCETO:","options":{"A":"Deve-se manter o paciente suspeito de tuberculose pulmonar em isolamento respiratório,\nzelando para que seu tempo de permanência no\nsetor seja o menor possível.","B":"É recomendado o uso de máscaras N95 para profissionais de saúde que tenham acesso às\náreas de alto risco de transmissão em ambientes hospitalares.","C":"Aos profissionais do laboratório, não é recomenda a utilização de máscaras N95 durante a\nmanipulação de materiais com suspeita de conter bacilos álcool-ácidos resistentes.","D":"No transporte de doentes bacilíferos ou suspeitos de TB pulmonar em ambulâncias, os\nprofissionais devem utilizar máscaras do tipo\nN95 e os pacientes devem utilizar máscaras cirúrgicas\ncomuns."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-196765","number":"196765","sourceNumber":"196765","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Gestante apresentando quadro de tosse crônica há cerca de 2 meses, tendo sido\ndiagnosticada com tuberculose pulmonar logo após entrar em trabalho de parto, iniciando a terapia\nadequada imediatamente após o parto. Diante do exposto, qual a melhor conduta a ser tomada em\nrelação ao recém-nascido:","options":{"A":"investigar tuberculose congênita, tratar se positivo; caso contrário, não vacinar, administrar\nisoniazida por 3 meses, quando deve-se realizar o teste tuberculínico","B":"investigar tuberculose congênita, tratar se positivo; caso contrário, administrar a vacina BCG e\nrealizar o teste tuberculínico aos 3 meses de idade","C":"administrar isoniazida por 6 meses e, em seguida, realizar o teste tuberculínico","D":"administrar isoniazida apenas de houver sintomas no recém-nascido; caso contrário\nacompanhar no ambulatório de pediatria."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-172836","number":"172836","sourceNumber":"172836","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O Brasil está entre os 22 países priorizados pela Organização Mundial da Saúde\n(OMS), por apresentarem 80% da carga mundial\nda tuberculose. O número de casos estimados de\ntuberculose na infância para países de alta incidência é de mais de 10% de todos os casos.\n\nContudo, em 2013, o Brasil notificou apenas 3,3% dos seus casos em crianças. Provavelmente,\nessa subnotificação é ocasionada pelo subdiagnóstico,\nque, por sua vez, decorre das dificuldades\nna sua realização. Sobre a tuberculose infantil é CORRETO afirmar:","options":{"A":"A tuberculose pode ocorrer em diversos sítios do organismo, sendo os mais comuns na infância\na tuberculose pulmonar seguida da tuberculose\nóssea.","B":"A vacina BCG está indicada em crianças até 5 anos de idade e é contraindicada em\nimunossuprimidos ou recém-nascidos com menos de 2.000 g.","C":"A febre, quando presente, é intermitente, geralmente baixa, e costuma ocorrer pela manhã.","D":"Tosse persistente por mais de 2 semanas leva a suspeita de tuberculose, mas se associada a\nconjuntivite flictenular e eritema nodoso o diagnóstico de tuberculose na infância deve ser\ndescartado."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-155488","number":"155488","sourceNumber":"155488","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Algumas etapas são necessárias para que ocorram emergência e reemergência de\numa doença viral. Assinale verdadeiro (V) ou\nfalso (F). ( ) Mutação, recombinação e rearranjos\nsegmentares genômicos de um novo patógeno. ( ) A disseminação do vírus será tão mais eficiente\nquanto maior for a quantidade de partículas virais necessárias para desencadear a infecção. ( )\nResidir em áreas endêmicas para determinadas doenças e agravos de notificação.( ) Disseminação\nde um patógeno para grande quantidade de indivíduos da nova espécie para desencadear surtos,\nepidemias ou pandemias. ( ) Introdução de um patógeno viral numa nova espécie de hospedeiro.","options":{"A":"V, V, V, F, V.","B":"F, F, V, V, F.","C":"F, V, V, V, F.","D":"V, V, V, V, V.","E":"V, F, F, V, V."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-155377","number":"155377","sourceNumber":"155377","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a opção que indica, após consulta inicial, a conduta a ser adotada frente a um\nadulto assintomático que tem contato domiciliar de paciente com tuberculose pulmonar ativa.","options":{"A":"Colher amostra de escarro para exame.","B":"Investigar tuberculose doença.","C":"Iniciar isoniazida profilática imediatamente.","D":"Fazer teste terapêutico por dois meses.","E":"Realizar a prova tuberculínica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-137825","number":"137825","sourceNumber":"137825","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Quais exames específicos para dengue são realizados para a comprovação laboratorial\ndas infecções pelo vírus (DENV)?","options":{"A":"Captura de IgM por ELISA (MAC ELISA), hemograma, plaqueta, dosagem de albumina sérica,\ncoagulograma, e transaminases.","B":"Sorológico por imunofluorescência (RIFI), ensaio imunoenzimático, testes rápidos\nimunocromatográficos, e isolamento viral.","C":"Cultura com prova de toxigenicidade, inibição da hemoaglutinação, ensaio enzimático,\nhemograma,\n\nplaqueta e coagulograma.","D":"Isolamento viral, detecção do genoma viral pelo método da transcrição reversa, e detecção da\nproteína NS1 do vírus (antígeno).","E":"Pesquisa de anticorpos ? sorologia, hemograma, plaqueta, coagulograma, reação em cadeia da\npolimerase (RT-PCR)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-127231","number":"127231","sourceNumber":"127231","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"São sinais de alerta para risco de choque hemorrágico da dengue.","options":{"A":"Sangramento gengival, vômitos, cefaleia.","B":"Diminuição do volume urinário, aumento repentino do hematócrito, sonolência.","C":"Queda abrupta das plaquetas, prova do laço positiva, febre.","D":"Dor abdominal intensa, piora da mialgia, dispneia.","E":"Hepatomegalia, exantema, lipotimia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-126913","number":"126913","sourceNumber":"126913","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação a dengue, assinale a alternativa CORRETA.","options":{"A":"A dor abdominal intensa e contínua, vômitos persistentes e diminuição da diurese são sinais de\nalerta da doença.","B":"A confirmação do diagnóstico definitivo de dengue deve ser feita com a pesquisa de Ag NS-1 a\npartir do sexto dia do início dos sintomas.","C":"No final da fase febril da dengue pode surgir um rash petequial que desaparece a digitopressão\ne vem acompanhado de intenso prurido e\ndescamação.","D":"Nos pacientes com quadro de dengue hemorrágica ocorre a diminuição da permeabilidade\ncapilar devido à disfunção endotelial, com\nhemoconcentração e choque."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-101016","number":"101016","sourceNumber":"101016","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à síndrome do choque da dengue, assinale a alternativa INCORRETA:","options":{"A":"O choque é de início súbito, geralmente nas primeiras 48 horas após início do quadro febril.","B":"O choque é de curta duração, geralmente não excedendo 24 a 48 horas.","C":"As manifestações hemorrágicas, quando presentes, geralmente se intensificam na fase do\nchoque.","D":"A disfunção miocárdica geralmente é transitória e limitada à fase de choque.","E":"A fase de reabsorção ocorre em cerca de 48 horas após o término do mesmo, com risco\naumentado para hipervolemia, insuficiência cardíaca e congestão pulmonar."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-111629","number":"111629","sourceNumber":"111629","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"As principais doenças relacionadas à ingestão de água contaminada são:","options":{"A":"cólera, gastroenterite, tétano e leptospirose.","B":"diarreia infecciosa, febre maculosa, leptospirose e hepatite A.","C":"cólera, febre tifoide, hepatite A e doenças diarreicas agudas.","D":"diarreia infecciosa, cólera, leptospirose, hepatite A e esquistossomose.","E":"dengue, febre amarela, gastroenterite, hepatiteA e esquistossomose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-101033","number":"101033","sourceNumber":"101033","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"UL, 45 anos, apresenta quadro de dor abdominal localizada em hipocôndrio esquerdo,\nadinamia e febre. A tomografia computadorizada do abdome diagnostica abscesso esplênico.\n\nQuanto ao abscesso esplênico, qual a afirmativa errada?","options":{"A":"Quando apresenta abscessos múltiplos, a mortalidade pode ser de 80%.","B":"Quando apresenta abscesso único, a mortalidade está em torno de 15%.","C":"Entre as doenças predisponentes temos a endocardite bacteriana e a policitemia vera.","D":"Ocorre, na maioria das vezes, após traumatismo abdominal.","E":"Entre os germes mais frequentes estão os Enterococcus e Staphylococcus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-77358","number":"77358","sourceNumber":"77358","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à gripe:","options":{"A":"Vergonhosamente, ainda não há nenhum protocolo do Ministério da Saúde sobre o assunto.","B":"São, entre outros, considerados condições e fatotes de risco para complicações: grávidas em\nqualquer idade gestacional, adultos com mais de 60 anos, crianças de menos de 2 anos e\npopulação indígena aldeada.","C":"A Síndrome Respiratória Aguda Grave fica caracterizada em todo indivíduo com Síndrome\nGripal e que apresente dispneia.","D":"Nos pacientes com febre elevada por mais de 72 horas, principalmente em se tratando de\ncrianças e idosos deve-se iniciar antibioticoterapia profilática, visando reduzir índice de\ncomplicações bacterianas, em especial a pneumonia.","E":"O oseltamivir tem eficácia similar ao placebo, não havendo justificativa para seu uso mesmo nos\ncasos graves, à luz da medicina baseada em\nevidências, principalmente pelo seu risco potencial de\ncausar insuficiência hepática."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-77553","number":"77553","sourceNumber":"77553","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Analise as assertivas abaixo e marque a alternativa que contém apenas assertivas\nCORRETAS com relação à dengue: I. Na forma\nclássica, além de febre alta, mialgia, cefaleia e dor\nretro-orbitária, ocorre exantema maculopapular pruriginoso em 70% dos pacientes; II. O sucesso no\ntratamento do paciente com dengue repousa no reconhecimento precoce dos sinais de alarme,\nentre os quais estão a dor abdominal intensa e contínua e o desconforto respiratório; III. São\nsinais\nde extravasamento plasmático capilar hemoconcentração, hipoalbuminemia e/ou derrames\ncavitários; IV. Uma pequena elevação de aminotransferases (transaminases) ocorre em 90% dos\ncasos de dengue, podendo haver icterícia e sinais de insuficiência hepática nas formas graves; V.\nO início da doença pode passar despercebido na criança, podendo o agravamento súbito ser\nidentificado como sua primeira manifestação clínica.","options":{"A":"I, II e III.","B":"I, IV e V.","C":"I, II e IV.","D":"II, III e V.","E":"III, IV e V."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-59022","number":"59022","sourceNumber":"59022","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente previamente hígida, 30 anos, iniciou há três dias quadro de febre, mialgia,\ncefaleia intensa e prostração. Nas últimas duas\nsemanas vários moradores da vizinhança\nreceberam diagnóstico de dengue. Foi colhido hemograma, que evidenciou: hematócrito de 45%,\nhemoglobina de 13 g/dl, leucócitos de 3600 células/mm³, com predomínio de linfócitos e plaquetas\nde 40.000 células/mm³. De acordo com orientações do Ministério da Saúde, é correto:","options":{"A":"Caso a paciente mantenha febre persistente, fazer uso contínuo de paracetamol, já que o uso de\ndipirona e ácido acetilsalicílico são contraindicados.","B":"Realizar a prova do laço, colher sorologia para dengue e orientar hidratação por via oral no\ndomicílio.","C":"Realizar a prova do laço, prescrever hidratação venosa rápida e monitorizar evolução de\nhematócrito, hemoglobina e plaquetas ambulatorialmente.","D":"Internar a paciente, fazer hidratação venosa vigorosa e colher hematócrito e hemoglobina\ndiariamente, pelo alto risco de sangramento.","E":"Alternativas A e C estão corretas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-59048","number":"59048","sourceNumber":"59048","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente de 25 anos, masculino, trabalhador rural, com perda de peso e episódios de\nfebre nos últimos 30 dias. Ao exame físico,\napresenta gânglios cervicais aumentados, um deles se\ndiferencia por sinais inflamatórios evidentes, baço a três centímetros da reborda costal esquerda. A\nhipótese diagnóstica mais provável é:","options":{"A":"Síndrome mononucleose/toxoplasmose.","B":"Histoplasmose aguda.","C":"Leishmaniose visceral.","D":"Paracoccidioidomicose.","E":"Doença linfoproliferativa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-23167","number":"23167","sourceNumber":"23167","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A vigilância Epidemiológica trabalha com definições dos diversos agravos, sendo, na\nmaior parte das vezes, usada a definição de caso suspeito para precipitar a notificação do mesmo.\nEm relação à dengue, tal definição envolve febre e os seguintes sinais e sintomas: cefaleia, dor\nretro-orbitária, mialgias, artralgias, exantema e prostração. Assinale a alternativa correta:","options":{"A":"A febre tem que ter, no máximo, três dias de evolução, devendo ser acompanhada por três dos\ndemais sinais e sintomas.","B":"A febre tem que ter, no máximo, sete dias de evolução, devendo ser acompanhada por dois dos\ndemais sinais e sintomas.","C":"A febre tem que ter, no máximo, dez dias de evolução, devendo ser acompanhada por mais um\ndos diversos sinais e sintomas.","D":"A febre pode ter qualquer duração, mas é necessária a presença de, pelo menos, três sinais e\nsintomas adicionais.","E":"A febre tem que ter, no máximo, cinco dias de duração, devendo ser acompanhada por dois dos\ndemais sinais e sintomas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-9401","number":"9401","sourceNumber":"9401","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa correta em relação a febre:","options":{"A":"Acima de 37°C, qualquer temperatura é considerada como febre.","B":"Febre de origem indeterminada é definida como febre com duração de pelo menos 3 semanas\nque permanece sem diagnóstico após 1 semana de\ninvestigação.","C":"Febre é sempre um sintoma/sinal de doença de difícil controle.","D":"O uso de antitérmicos para baixar a temperatura deve ser evitado, pois mascara o quadro clínico\ne dificulta o diagnóstico.","E":"Nenhuma das respostas está correta."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-8157","number":"8157","sourceNumber":"8157","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"De acordo com o manual do Ministério da Saúde, devemos considerar como sinais de\nalarme na dengue os sinais e/ou sintomas listados abaixo, exceto:","options":{"A":"Dor abdominal intensa e contínua e queda abrupta de plaquetas.","B":"<P>Hipotensão postural e/ou lipotimia.</P>","C":"Hepatomegalia dolorosa e desconforto respiratório.","D":"Hipotermia e aumento repentino do hematócrito.","E":"Artralgia e exantema."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-354809","number":"354809","sourceNumber":"354809","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Menino de 4 anos de idade vem para consulta\ncom história de tosse seca há 2 meses. Nesse\nperíodo fez uso de várias medicações\n(expectorantes, descongestionantes, mucolíticos e antibiótico), sem qualquer sinal de melhora.\nTrata-se de uma criança previamente hígida, porém apresenta perda ponderal há 2 meses. Ao\nexame físico, encontra-se em bom estado geral, peso entre o escore z -2 e -3, estatura no escore z\n\n0. Sem sinais de desconforto respiratório e sem outras alterações ao exame físico. De acordo com\no relato, os exames a serem solicitados para\no esclarecimento do diagnóstico são:","options":{"A":"radiografia de tórax, teste tuberculínico, pesquisa e cultura para bacilo de Koch no lavado\nbrônquico.","B":"tomografia de tórax, teste tuberculínico, pesquisa e cultura para bacilo de Koch no lavado\nbrônquico.","C":"radiografia de tórax, teste tuberculínico, pesquisa e cultura para bacilo de Koch no lavado\ngástrico.","D":"tomografia de tórax, teste tuberculínico, pesquisa e cultura para bacilo de Koch no lavado\ngástrico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-366990","number":"366990","sourceNumber":"366990","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito da indução de escarro em solução salina hipertônica, é correto afirmar:","options":{"A":"Visa a coleta de escarro alveolar profundo, sendo útil na detecção de patógenos pulmonares.","B":"É um método utilizado para aumentar a concentração de glicose no escarro.","C":"A solução salina hipertônica causa uma reação hipertônica no pulmão, dificultando a\nexpectoração.","D":"A principal indicação é para a avaliação da função renal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-362636","number":"362636","sourceNumber":"362636","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Vale ressaltar também que as medidas e equipamentos de proteção coletiva são\nextremamente importantes quando se trata da prevenção da TB:","options":{"A":"Em trabalhadores e profissionais de saúde, bem como as questões relativas às condições\nadequadas para o atendimento às pessoas com suspeita ou diagnóstico de TB.","B":"Em trabalhadores e não em todos os profissionais de saúde, bem como as questões relativas às\ncondições adequadas para o atendimento às pessoas com suspeita ou diagnóstico de TB.","C":"Em trabalhadores e profissionais de saúde, não com as questões relativas às condições\nadequadas para o atendimento às pessoas com suspeita ou diagnóstico de TB.","D":"Em trabalhadores e profissionais de saúde, bem como as questões relativas às condições\nadequadas para o atendimento às pessoas sem suspeita ou diagnóstico de TB."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-363924","number":"363924","sourceNumber":"363924","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Leia o caso clínico a seguir. Pré-adolescente, atleta, participante ativo de jogos em\ncampeonatos de futebol e com saúde previamente hígida, apresenta, há mais de uma semana,\nepisódios de febre acima de 38ºC, predominantemente vespertina, associada à perda de peso e à\ntosse persistente. Qual é a doença deste pré-adolescente?","options":{"A":"Malária.","B":"Tuberculose pulmonar.","C":"Leishmaniose visceral.","D":"Legionelose."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-337388","number":"337388","sourceNumber":"337388","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Embora com baixa especificidade diagnóstica, a radiografia é:","options":{"A":"Extremamente útil na definição da forma de apresentação, na avaliação de possíveis\ncomorbidades e na evolução durante o tratamento.","B":"Extremamente útil na definição da forma de apresentação, na avaliação de possíveis\ncomorbidades e não na evolução durante o tratamento.","C":"Inútil na definição da forma de apresentação, na avaliação de possíveis comorbidades e na\nevolução durante o tratamento.","D":"Extremamente útil na definição da forma de apresentação, não na avaliação de possíveis\ncomorbidades e na evolução durante o tratamento."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-334100","number":"334100","sourceNumber":"334100","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tosse é um dos principais sintomas do paciente com Tuberculose Pulmonar, sendo\ncorreto que:","options":{"A":"O tempo da tosse deve ser considerado independendo da população.","B":"O tempo da tosse deve ser desconsiderado dependendo da população.","C":"O tempo da tosse deve ser considerado apenas na população tabagista.","D":"O tempo da tosse deve ser considerado dependendo da população."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-334102","number":"334102","sourceNumber":"334102","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Deve-se investigar Tuberculose, com qualquer tempo de tosse:","options":{"A":"Em pessoas sem contato com pacientes com Tuberculose, pessoas vivendo com o HIV (PVHIV),\npopulação privada de liberdade, população em situação de rua, indivíduos que vivem em albergues\nou instituições de longa permanência, indígenas, profissionais de saúde, imigrantes e refugiados\n(quando houver maior vulnerabilidade).","B":"Em pessoas em contato com pacientes com Tuberculose, pessoas vivendo com o HIV (PVHIV),\npopulação privada de liberdade, população em situação de rua, indivíduos que vivem em albergues\nou instituições de longa permanência, indígenas, profissionais de saúde, imigrantes e não\nrefugiados (quando houver maior vulnerabilidade).","C":"Em pessoas em contato com pacientes com Tuberculose, pessoas vivendo com o HIV (PVHIV),\npopulação privada de liberdade, população em situação de rua, indivíduos que vivem em\nalbergues, mas não em instituições de longa permanência, indígenas, profissionais de saúde,\nimigrantes e refugiados (quando houver maior vulnerabilidade).","D":"Em pessoas em contato com pacientes com Tuberculose, pessoas vivendo com o HIV (PVHIV),\npopulação privada de liberdade, população em situação de rua, indivíduos que vivem em albergues\nou instituições de longa permanência, indígenas, profissionais de saúde, imigrantes e refugiados\n(quando houver maior vulnerabilidade)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-334779","number":"334779","sourceNumber":"334779","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente de 57 anos de idade, na terceira semana do tratamento de tuberculose\npulmonar em uso do esquema preferencial\nconforme Manual e Recomendações para Controle da\nTuberculose no Brasil (Ministério da Saúde), passou a apresentar náuseas, vômitos e dor em\nhipocôndrio direito. Procurou Unidade Básica de Saúde, onde não foram constatados sinais de\ngravidade clínica, porém exames laboratoriais demonstraram TGO 460 U/L e TGP 530 U/L.\nPaciente sem história de hepatopatias prévias. Nesse caso, a conduta a ser adotada é a suspensão","options":{"A":"da rifampicina pelas características da hepatotoxicidade, mantendo as demais medicações do\nesquema até o final do tratamento.","B":"do esquema completo, com reintrodução programada das medicações, iniciando-se com\nrifampicina e etambutol após a redução das transaminases.","C":"da pirazinamida pelo maior potencial de hepatotóxico desta, mantendo as demais medicações\ndo esquema até o final do tratamento.","D":"do esquema completo e início de esquema alternativo com levofloxacino, linezolida e amicacina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-330081","number":"330081","sourceNumber":"330081","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Considerando a tuberculose na infância, a alternativa que representa o tipo mais\ncomum na faixa etária pediátrica é:","options":{"A":"Tuberculose óssea.","B":"Tuberculose pulmonar.","C":"Tuberculose ganglionar.","D":"Tuberculose meningoencefálica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-331996","number":"331996","sourceNumber":"331996","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Giovanna, sete anos, recebeu BCG ao nascer, é contactante intradomiciliar de\ntuberculoso bacilífero, apresenta-se assintomática,\nraio-x de tórax normal e prova tuberculínica de\noito milímetros. Deve receber a orientação de:","options":{"A":"Repetir o PPD em oito semanas.","B":"Realizar lavado gástrico.","C":"Tratar infecção latente.","D":"Revacinar."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-321579","number":"321579","sourceNumber":"321579","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Leia o caso clínico. Paciente do sexo masculino, 40 anos de idade e soropositivo para o\nVírus da Imunoeficiência Humana exibia febre e tosse há um mês. O exame físico mostrou\ntemperatura de 37.5ºC, bem como diminuição do murmúrio vesicular no àpice posterior do\nhemitórax direito. A radiografia do tórax exibiu grande área de consolidação na área central, com\nnível hidroaéreo no lobo médio direito. Uma biópsia transbrônquica mostrou organismos\nfilamentosos fracamente álcool-ácido resistentes. Evoluiu para empiema e início agudo de cefaleia.\nUma tomografia computadorizada de crânio apresentava uma lesão de 4cm no hemisfério cerebral\ndireito, com realce anelar do contraste. Qual dos seguintes agentes infecciosos é o mais provável\nde estar provocando a doença?","options":{"A":"Aspergillus fumigatus.","B":"Mycobacterium avium complex.","C":"Nocardia asteroides.","D":"Mucor circinelloides."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-321580","number":"321580","sourceNumber":"321580","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente do sexo feminino, 47 anos de idade, casada e menopausada é portadora de\nartrite reumatoide. Sua médica assistente optou pelo uso de um bloqueador do fator de necrose\ntumoral-alfa, ertanecept. O seu marido foi acometido por tuberculose pulmonar bacilífera há sete\nanos, com tratamento efetivo por 6 meses. Ela, porém, não exibia febre ou sintomas respiratórios.\nNa sua avaliação, no entanto, o teste tuberculínico (TT) foi 4mm e o teste de liberação de\ninterferon-gama (IGRA, do inglês interferon-gama release assay) foi positivo. A radiografia do tórax\nexibiu nódulo calcificado no lobo superior do pulmão direito, ao lado de espessamento pleural\napical ipsilateral. Com base no exposto, qual é a melhor conduta a ser tomada com essa paciente?","options":{"A":"Iniciar tratamento para tuberculose pulmonar com associação de rifampicina, isoniazida,\npirazinamida e etambutol por 02 meses, seguidos por rifampicina e isoniazida por 04 meses.","B":"Contraindicar o uso de ertanecept.","C":"Repetir o TT.","D":"Iniciar tratamento para infecção latente pelo Mycobacterium tuberculosis com a associação de\nrifapentina e isoniazida em dose semanal por 12 semanas consecutivas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-330118","number":"330118","sourceNumber":"330118","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente, jovem, dá entrada em hospital com dispneia, sendo residente em região de\nclima muito frio, relata que apresentou há 30 dias tosse seca, dispneia progressiva e temperatura\nde 37º C. Em exame radiográfico do tórax é constatado velamento do hemitórax direito, com desvio\ndo mediastino contralateralmente. O procedimento CORRETO indicado é:","options":{"A":"Realizar apenas o procedimento para evacuar o conteúdo aéreo ou líquido anômalo da cavidade\npleural.","B":"Realizar apenas a toracotomia de emergência para obter amostras de tecido para exame\nlaboratorial.","C":"Realizar a videotoracoscopia por se tratar de fase aguda do trauma torácico.","D":"Realizar a toracocentese conjuntamente com esvaziamento do derrame pleural e biópsia pleural\ncom agulha de Cope."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-342683","number":"342683","sourceNumber":"342683","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Duas crianças estão internadas, num hospital, com meningite: a criança A com\nmeningite meningocócica, e a criança B, com meningite pneumocócica. Qual é a conduta de\nimediato com relação aos contactantes íntimos das crianças?","options":{"A":"rifampicina para contactantes dos 2 casos","B":"rifampicina para contactantes do caso A apenas","C":"rifampicina para contactantes do caso B apenas","D":"vacina meningocócica C conjugada para crianças do caso A apenas"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-315765","number":"315765","sourceNumber":"315765","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Esquemas para tratamento de tuberculose sem a rifampicina na sua composição, seja\npor resistência ou por intolerância:","options":{"A":"Requerem o uso de fármacos de segunda linha, resultam em tratamento com duração mais\ncurta, com maior potencial de toxicidade e de pior prognóstico.","B":"Requerem o uso de fármacos de segunda linha, resultam em tratamento com duração mais\nprolongada, com maior potencial de toxicidade, mas de melhor prognóstico.","C":"Requerem o uso de fármacos de segunda linha, resultam em tratamento com duração mais\nprolongada, com maior potencial de toxicidade e de pior prognóstico.","D":"Requerem o uso de fármacos de segunda linha, resultam em tratamento com duração mais\nprolongada, com menor potencial de toxicidade e de pior prognóstico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-315768","number":"315768","sourceNumber":"315768","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O tratamento da Tuberculose Drogarresistente (TB DR) é um dos maiores desafios para\no controle da doença no mundo, sendo correto\nque:","options":{"A":"Especialmente a que envolve resistência à rifampicina, isolada ou combinada a outros fármacos,\npois se trata do medicamento mais ativo contra\no bacilo da TB.","B":"Especialmente a que envolve resistência à rifampicina, isolada ou combinada a outros fármacos,\npois se trata do medicamento menos ativo\ncontra o bacilo da TB.","C":"Exceto a que envolve resistência à rifampicina, isolada ou combinada a outros fármacos, pois se\ntrata do medicamento mais ativo contra o bacilo da TB.","D":"Especialmente a que envolve resistência à rifampicina, isolada ou combinada a outros fármacos,\npois se trata do medicamento sem atividade\ncontra o bacilo da TB."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-315771","number":"315771","sourceNumber":"315771","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O diagnóstico precoce de infecção pelo HIV em pessoas com Tuberculose (TB) tem\nimportante impacto no curso clínico da doença. Portanto:","options":{"A":"O teste diagnóstico para HIV, preferencialmente o rápido, deve ser oferecido, o mais cedo\npossível, a toda pessoa com diagnóstico estabelecido de TB.","B":"O teste diagnóstico para HIV, nunca o rápido, deve ser oferecido.","C":"O teste diagnóstico para HIV, preferencialmente o rápido, deve ser oferecido, o mais tardiamente\npossível, a toda pessoa com diagnóstico\nestabelecido de TB.","D":"O teste diagnóstico para HIV, preferencialmente o lento, deve ser oferecido, o mais cedo\npossível, a toda pessoa com diagnóstico estabelecido de TB."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-317171","number":"317171","sourceNumber":"317171","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente DEF, masculino, 19 anos, procura atendimento no Pronto Socorro por quadro\nde dispneia e dor torácica em região basal\nposterior esquerda, principalmente quando respira\nfundo. Diz que há alguns meses percebeu que estava cansado para jogar futebol, e que nas\núltimas duas semanas o quadro piorou, e agora apresentava falta de ar para subir 1 lance de\nescada. Nega alergias ou comorbidades. Nega uso de medicação contínua. Mora em casa de dois\ncômodos com outros 10 familiares. Trabalha de auxiliar de pedreiro, sem uso de EPI. Nega febre,\nmas diz que no final da tarde sente \"moleza no corpo\". Percebeu que a calça está um pouco mais\nlarga. Ao exame físico: Paciente hipocorado, hidratado, acianótico, anictérico. SpO2 96%, FC\n98bpm, PA 110x80. FR 18irpm, Temperatura axilar: 37,5. Peso 60kg, Altura 1,70m. Ausculta\nrespiratória com murmúrio vesicular presente, reduzido em base pulmonar esquerda. Percussão\ncom som submaciço em topografia de 1/3 inferior de hemitórax esquerdo. Sem esforço respiratório.\nAusculta respiratória com bulhas rítmicas e normofonéticas, sem sopros. Abdome flácido, indolor e\ninocente. Extremidade sem edema de membros inferiores. Sem alterações da mímica facial ou\nredução de força ou sensibilidade em membros. Sobre o caso clínico, assinale a alternativa\nverdadeira:","options":{"A":"A principal hipótese diagnóstica é pneumonia adquirida na comunidade, e o tratamento é\nrealizado com quinolona respiratória.","B":"A principal hipótese diagnóstica é tromboembolismo pulmonar, e o tratamento é realizado com\nanticoagulação oral.","C":"A principal hipótese diagnóstica é COVID-19, e o tratamento é com corticoide oral.","D":"A principal hipótese diagnóstica é tuberculose, e o tratamento é realizado com esquema básico\ncombinado com rifampicina, isoniazida, prianzinamida e etambutol."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-295366","number":"295366","sourceNumber":"295366","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente do sexo masculino, de 45 anos, refere há cerca de três meses tosse seca,\ndispneia progressiva até nos moderados esforços,\nfebre de 37,9°C no período vespertino, perda de\noito quilos nesse período e inapetência. Fez uso de vários antibióticos, sem melhora. Nega\ntabagismo e patologias prévias ou uso de medicações contínuas. Ao exame físico: regular estado\ngeral, afebril, eupneico, emagrecido, consciente mv abolida em terço inferior de hemitórax direito e\nsem outras alterações ao exame. Traz raio X de tórax, conforme as imagens a seguir. Resultado de\nanálise laboratorial de líquido pleural por toracocentese em hemitórax direito: líquido seroso.\n\nCitologia: linfócitos 80%, ausência de células mesoteliais, citologia oncótica negativa, pH 7,35,\nadenosina desaminase (ada): 70mg/dl, glicose 70mg/dl, LDH 500u/l, cultura bacteriana e fúngica\nnegativa, cultura micobactérias em andamento, proteína líquido/proteína sérica > 0,5, LDH do\nlíquido/LDH sérica > 0,6. Qual deve ser a conduta inicial para esse paciente?","options":{"A":"Iniciar antibiótico.","B":"Iniciar diurético.","C":"Realizar biópsia pleural.","D":"Realizar drenagem torácica fechada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/295366.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-317172","number":"317172","sourceNumber":"317172","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente DEF, masculino, 19 anos, procura atendimento no Pronto Socorro por quadro\nde dispneia e dor torácica em região basal\nposterior esquerda, principalmente quando respira\nfundo. Diz que há alguns meses percebeu que estava cansado para jogar futebol, e que nas\núltimas duas semanas o quadro piorou, e agora apresentava falta de ar para subir 1 lance de\nescada. Nega alergias ou comorbidades. Nega uso de medicação contínua. Mora em casa de dois\ncômodos com outros 10 familiares. Trabalha de auxiliar de pedreiro, sem uso de EPI. Nega febre,\nmas diz que no final da tarde sente \"moleza no corpo\". Percebeu que a calça está um pouco mais\nlarga. Ao exame físico: Paciente hipocorado, hidratado, acianótico, anictérico. SpO2 96%, FC\n98bpm, PA 110x80. FR 18irpm, Temperatura axilar: 37,5. Peso 60kg, Altura 1,70m. Ausculta\nrespiratória com murmúrio vesicular presente, reduzido em base pulmonar esquerda. Percussão\ncom som submaciço em topografia de 1/3 inferior de hemitórax esquerdo. Sem esforço respiratório.\nAusculta respiratória com bulhas rítmicas e normofonéticas, sem sopros. Abdome flácido, indolor e\ninocente. Extremidade sem edema de membros inferiores. Sem alterações da mímica facial ou\nredução de força ou sensibilidade em membros. Para confirmar a sua principal hipótese diagnóstica\nqual o exame pode auxiliar na sua investigação:","options":{"A":"Prova tuberculinica (PPD).","B":"Toracocentese com dosagem de ADA (adenosina deaminase) no líquido pleural.","C":"Hemocultura para aeróbios e anaeróbios.","D":"Dosagem sérica de D Dímero."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-295367","number":"295367","sourceNumber":"295367","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente do sexo masculino, de 45 anos, refere há cerca de três meses tosse seca,\ndispneia progressiva até nos moderados esforços,\nfebre de 37,9°C no período vespertino, perda de\noito quilos nesse período e inapetência. Fez uso de vários antibióticos, sem melhora. Nega\ntabagismo e patologias prévias ou uso de medicações contínuas. Ao exame físico: regular estado\ngeral, afebril, eupneico, emagrecido, consciente mv abolida em terço inferior de hemitórax direito e\nsem outras alterações ao exame. Traz raio X de tórax, conforme as imagens a seguir. Resultado de\nanálise laboratorial de líquido pleural por toracocentese em hemitórax direito: líquido seroso.\n\nCitologia: linfócitos 80%, ausência de células mesoteliais, citologia oncótica negativa, pH 7,35,\nadenosina desaminase (ada): 70 mg/dl, glicose 70\nmg/dl, LDH 500 u/l, cultura bacteriana e fúngica\nnegativa, cultura micobactérias em andamento, proteína líquido/proteína sérica > 0,5, LDH do\nlíquido/LDH sérica > 0,6. Após avaliação dos exames, qual deve ser o diagnóstico mais provável\npara esse paciente?","options":{"A":"Pneumonia bacteriana complicada.","B":"Tuberculose pleural.","C":"Insuficiência cardíaca congestiva.","D":"Embolia pulmonar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/295367.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-317173","number":"317173","sourceNumber":"317173","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente DEF, masculino, 19 anos, procura atendimento no Pronto Socorro por quadro\nde dispneia e dor torácica em região basal\nposterior esquerda, principalmente quando respira\nfundo. Diz que há alguns meses percebeu que estava cansado para jogar futebol, e que nas\núltimas duas semanas o quadro piorou, e agora apresentava falta de ar para subir 1 lance de\nescada. Nega alergias ou comorbidades. Nega uso de medicação contínua. Mora em casa de dois\ncômodos com outros 10 familiares. Trabalha de auxiliar de pedreiro, sem uso de EPI. Nega febre,\nmas diz que no final da tarde sente \"moleza no corpo\". Percebeu que a calça está um pouco mais\nlarga. Ao exame físico: Paciente hipocorado, hidratado, acianótico, anictérico. SpO2 96%, FC\n98bpm, PA 110x80. FR 18irpm, Temperatura axilar: 37,5. Peso 60kg, Altura 1,70m. Ausculta\nrespiratória com murmúrio vesicular presente, reduzido em base pulmonar esquerda. Percussão\ncom som submaciço em topografia de 1/3 inferior de hemitórax esquerdo. Sem esforço respiratório.\nAusculta respiratória com bulhas rítmicas e normofonéticas, sem sopros. Abdome flácido, indolor e\ninocente. Extremidade sem edema de membros inferiores. Sem alterações da mímica facial ou\nredução de força ou sensibilidade em membros. Com as informações clínicas e exame físico,\nassinale a alternativa correta:","options":{"A":"Na radiografia de tórax é esperado encontrar opacidade em base esquerda, com velamento de\nseios costofrênico e uma imagem de parábola na periferia (sinal do menísco).","B":"Na radiografia de tórax é esperado encontrar uma cavidade com nível líquido em base esquerda,\ncom desvio contra lateral de linha média.","C":"Na radiografia de tórax se houver sinais de derrame pleural com líquido livre, não deve ser\nrealizado toracocentese para avaliação das características do líquido.","D":"Em casos de doenças infecciosas como tuberculose e empiema, o padrão encontrado no líquido\npleural é de transudato."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-302865","number":"302865","sourceNumber":"302865","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose na criança permanece ainda negligenciada e com alta mortalidade no\nmundo. Considere o caso de uma puérpera, em tratamento para tuberculose pulmonar há 1\nsemana. A respeito do caso, considere as seguintes condutas: 1. Vacinar o RN com BCG. 2.\n\nContraindicar a amamentação. 3. Iniciar quimioprofilaxia com isoniazida. 4. Realizar prova\ntuberculínica. É/São conduta(s) adequada(s) a ser realizada(s) no período neo natal com o\nrecém-nascido, que se encontra assintomático, conforme as diretrizes atuais do Ministério da\nSaúde:","options":{"A":"A 3 apenas.","B":"1 e 3 apenas.","C":"2 e 4 apenas.","D":"1, 2 e 4 apenas.","E":"1,2,3 e 4."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-300932","number":"300932","sourceNumber":"300932","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O tratamento da TB em PVHIV tem a duração de seis meses, sendo adequado o item:","options":{"A":"Dependentemente da fase de evolução da infecção viral.","B":"Independentemente da fase da infecção viral.","C":"Independentemente da fase de evolução da infecção viral.","D":"Independentemente da fase de evolução adiantada da infecção viral."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-300938","number":"300938","sourceNumber":"300938","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação à tosse:","options":{"A":"Sintoma que funciona como sinal de alerta para várias doenças.","B":"Caracterizada como um reflexo protetor, trata-se de um mecanismo importante de defesa do\norganismo.","C":"Manobra expulsiva forçada contra a glote fechada, gera um som característico, de controle\nvoluntário ou não.","D":"Tem apenas a função de eliminar secreções e muco de grandes vias aéreas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-300954","number":"300954","sourceNumber":"300954","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Múltiplos obstáculos dificultam a implementação de estratégias de controle da\ntuberculose nas prisões, podemos assim determinar que está CORRETA a seguinte:","options":{"A":"Risco de estigmatização e de segregação considerando a falta de importância da proteção\ngerada pelo pertencimento grupal.","B":"Risco de estigmatização e de segregação considerando a importância da proteção Gerada pelo\npertencimento grupal.","C":"Risco de estigmatização e de segregação considerando a nula importância da proteção Gerada\npelo pertencimento grupal.","D":"Risco somente de estigmatização e não de segregação considerando a importância da proteção\ngerada pelo pertencimento grupal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-300957","number":"300957","sourceNumber":"300957","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O resultado da Prova Tuberculínica (PT) deve ser registrado em milímetros, inclusive\nquando não houver endureção. Nesse caso, o profissional deverá anotar: ZERO mm. Sendo\nCORRETO o item:","options":{"A":"Deve-se medir o menor diâmetro transverso da área do endurado palpável, com régua\nmilimetrada transparente.","B":"Deve-se medir o maior diâmetro transverso da área do endurado palpável, com régua\nmilimetrada transparente.","C":"Deve-se medir o maior diâmetro transverso da área do endurado impalpável, com régua\nmilimetrada transparente.","D":"Deve-se medir o mínimo diâmetro transverso da área do endurado palpável, com régua\nmilimetrada transparente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-317205","number":"317205","sourceNumber":"317205","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Segundo as estratégias de controle da tuberculose que são responsabilidade da\nAtenção Básica, marcar C para as afirmativas\nCertas, E para as Erradas e, após, assinalar a\nalternativa que apresenta a sequência CORRETA: ( ) Será realizado, na Atenção Básica, o\ntratamento supervisionado dos casos positivos. ( ) A fim de efetuar o diagnóstico, a unidade deve\nencaminhar o indivíduo para exames laboratoriais e radiológicos. ( ) Não se inclui, como medida\npreventiva, a busca de indivíduos que coabitam com o paciente tuberculoso.","options":{"A":"C - C - E.","B":"E - C - C.","C":"C - E - E.","D":"E - C - E."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-315833","number":"315833","sourceNumber":"315833","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A PT consiste na inoculação intradérmica do Derivado Proteico Purificado (PPD), com a\nfunção de medir a resposta celular a estes antígenos. Sendo correto o item:","options":{"A":"A resposta à PT deve ser lida após 72 horas após a aplicação, sendo considerada positiva a\nleitura maior ou igual a 5mm.","B":"A resposta à PT deve ser lida de 48 a 72 horas após a aplicação, sendo considerada negativa a\nleitura maior ou igual a 5mm.","C":"A resposta à PT deve ser lida de 48 a 72 horas após a aplicação, sendo considerada positiva a\nleitura maior ou igual a 5mm.","D":"A resposta à PT deve ser lida de 48 a 72 horas após a aplicação, sendo considerada positiva a\nleitura maior ou igual a 15 mm."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-300966","number":"300966","sourceNumber":"300966","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Os ensaios de liberação do interferon-gama (Interferon-Gamma Release Assays -\nIGRA) apresentam vantagens que consistem no\nresultado não sujeito ao viés do leitor e no fato de\no teste ser realizado em amostra biológica, o que reduz o risco de efeitos adversos. Sendo\nadequado que:","options":{"A":"IGRAs possuem vantagens operacionais, pois, ao requerer apenas uma visita do paciente, o\nretorno para a leitura do teste não é necessário.","B":"IGRAs não possuem vantagens operacionais, pois, ao requerer apenas uma visita do paciente, o\nretorno para a leitura do teste não é necessário.","C":"IGRAs possuem vantagens operacionais, pois, ao requerer apenas duas visitas do paciente, o\nretorno para a leitura do teste não é necessário.","D":"IGRAs possuem vantagens operacionais, pois, ao requerer apenas uma visita do paciente, o\nretorno para a leitura do teste é necessário."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-318017","number":"318017","sourceNumber":"318017","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O complexo de Ranke ocorre na seguinte doença:","options":{"A":"tuberculose.","B":"blastomicose.","C":"suberose.","D":"asbestose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-265853","number":"265853","sourceNumber":"265853","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Ocorrem especificidades do desenvolvimento do Mycobacterium Tuberculosis no que\ndiz respeito ao seu metabolismo e à atuação dos medicamentos, sendo ADEQUADO o item:","options":{"A":"Os fármacos só atuam quando há atividade metabólica, ou seja, bacilos em estado de latência\nnão são atingidos pelos medicamentos, mas são\ndestruídos pelo sistema imunológico.","B":"Os fármacos não atuam quando há atividade metabólica, ou seja, bacilos em estado de latência\nnão são atingidos pelos medicamentos, mas\nsão destruídos pelo sistema imunológico.","C":"Os fármacos só atuam quando há atividade metabólica, ou seja, bacilos em estado de latência\nsão atingidos pelos medicamentos, mas são\ndestruídos pelo sistema imunológico.","D":"Os fármacos só atuam quando há atividade metabólica, ou seja, bacilos em estado de latência\nnão são atingidos pelos medicamentos, e não\nsão destruídos pelo sistema imunológico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-281315","number":"281315","sourceNumber":"281315","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A disseminação da doença tuberculose para o sistema linfático pode ser visualizada\ncomo linfonodomegalias hilares e/ou alargamento do\nmediastino.","options":{"A":"Geralmente, são linfonodos menores que 2 cm, com áreas de baixa atenuação central\nassociadas a um aumento de atenuação perinodal,\ncorrespondendo a focos de necrose caseosa\ncentral.","B":"Geralmente, são linfonodos maiores que 2 cm, com áreas de baixa atenuação central\nassociadas a um aumento de atenuação\nperinodal, correspondendo a focos de necrose caseosa\ncentral.","C":"Geralmente, são linfonodos maiores que 2 cm, com áreas de alta atenuação central associadas\na um aumento de atenuação perinodal,\ncorrespondendo a focos de necrose caseosa central.","D":"Geralmente, são linfonodos maiores que 2 cm, com áreas de baixa atenuação central\nassociadas a um aumento de atenuação\nperinodal, correspondendo a focos de necrose caseosa\nperiférico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-265896","number":"265896","sourceNumber":"265896","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Considerando os pilares, objetivos e estratégias do Plano Nacional pelo Fim da\nTuberculose para fortalecer a rede de\ndiagnóstico laboratorial existente no país, somente podemos\nindicar como INCORRETA a alternativa:","options":{"A":"Ampliar o acesso aos métodos diagnósticos com o teste rápido molecular, baciloscopia, cultura e\nteste de sensibilidade.","B":"Ampliar a realização de cultura e teste de sensibilidade para todos os casos de tuberculose.","C":"Promover ações que garantam o acesso ao diagnóstico oportuno da tuberculose sensível e\nresistente, tendo em vista o início oportuno do tratamento.","D":"Intensificar a busca ativa de casos, desconsideradas as particularidades das populações mais\nvulneráveis nos territórios."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-281318","number":"281318","sourceNumber":"281318","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A indicação do tratamento da Infecção Latente pelo Mycobacterium Tuberculosis (ILTB)\ndepende de vários fatores, sendo correto o item:","options":{"A":"Resultado da prova tuberculínica PT ou do Interferon-Gamma Release Assays IGRA, e não\nidade da pessoa, probabilidade de ILTB e risco para o desenvolvimento de TB ativa.","B":"Resultado da prova tuberculínica PT ou do Interferon-Gamma Release Assays IGRA, idade da\npessoa, probabilidade de ILTB e não o risco para o desenvolvimento de TB ativa.","C":"Resultado da prova tuberculínica PT, mas não do Interferon-Gamma Release Assays IGRA,\nidade da pessoa, probabilidade de ILTB e risco para o desenvolvimento de TB ativa.","D":"Resultado da prova tuberculínica PT ou do Interferon-Gamma Release Assays IGRA, idade da\npessoa, probabilidade de ILTB e risco para o desenvolvimento de TB ativa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-281322","number":"281322","sourceNumber":"281322","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para as pessoas infectadas pelo HIV que são contatos de pessoas com TB pulmonar\nou laríngea ativa, está adequado o item:","options":{"A":"Deverão realizar o tratamento para infecção latente pelo Mycobacterium Tuberculosis (ILTB),\nindependentemente do resultado da prova tuberculínica.","B":"Deverão realizar o tratamento para infecção latente pelo Mycobacterium Tuberculosis (ILTB),\ndependentemente do resultado da prova tuberculínica.","C":"Não deverão realizar o tratamento para infecção latente pelo Mycobacterium Tuberculosis\n(ILTB), independentemente do resultado da prova tuberculínica.","D":"Nunca deverão realizar o tratamento para infecção latente pelo Mycobacterium Tuberculosis\n(ILTB), independentemente do resultado da prova\ntuberculínica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-265904","number":"265904","sourceNumber":"265904","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Nas pessoas com TB pulmonar que tem baciloscopia positiva no escarro, têm maior\ncapacidade de transmissão. Indique a alternativa ERRADA:","options":{"A":"Em geral, eles têm a forma TB pulmonar cavitária ou, mais raramente, a TB laríngea transmite a\ndoença.","B":"Aqueles com baciloscopia de escarro negativa, mesmo com TRM-TB ou cultura positivos no\nescarro, têm infectividade menor.","C":"Pessoas com cultura de escarro negativa e as com TB extrapulmonar exclusivamente são\ndesprovidas de infectividade.","D":"Pacientes com TB pulmonar e infecção pelo HIV, na dependência de maior comprometimento da\nimunidade, podem ter menos frequentemente acometimento pulmonar e apresentação cavitária da\ndoença e, assim, também maior infectividade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-281324","number":"281324","sourceNumber":"281324","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assim como os contatos de casos de TB pulmonar ativa, podemos indicar como correto\no item:","options":{"A":"A única população que merece especial atenção durante o rastreamento para a identificação da\ninfecção latente pelo Mycobacterium tuberculosis (ILTB) é a dos profissionais de saúde.","B":"Duas outras populações merecem especial atenção durante o rastreamento para a identificação\nda infecção latente pelo Mycobacterium\ntuberculosis (ILTB): PVHIV e profissionais de saúde.","C":"Outras populações merecem especial atenção durante o rastreamento para a identificação da\ninfecção latente pelo Mycobacterium tuberculosis (ILTB): Pessoa vivendo com HIV PVHIV, exceto\nprofissionais de saúde.","D":"Duas outras populações não merecem especial atenção durante o rastreamento para a\nidentificação da infecção latente pelo\nMycobacterium tuberculosis (ILTB): Pessoa vivendo com HIV\nPVHIV e profissionais de saúde."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-274817","number":"274817","sourceNumber":"274817","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tosse é um mecanismo de defesa das vias aéreas, que funciona como meio de\npropagação de doenças infecciosas, e quando\npersistente, é causa de grande desconforto ao\npaciente. A elucidação diagnóstica da tosse é bastante desafiadora para o médico. Com relação à\ntosse, marque a alternativa correta.","options":{"A":"Em portadores de DPOC, a tosse persistente pode causar dor torácica, abdominal, tontura e\nsíncope. Em casos graves, pode haver fratura de costelas.","B":"A tosse que dura mais de 4 semanas é considerada crônica.","C":"Nas crianças, a tosse que dura menos de 5 semanas é considerada aguda, estando bem\nestabelecida, neste caso, o benefício dos xaropes expectorantes.","D":"Em nosso meio, a causa mais comum de tosse por mais de 3 semanas ainda é a tuberculose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-232219","number":"232219","sourceNumber":"232219","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente do sexo feminino, de 45 anos, teve diagnóstico de\ntuberculose há cinco anos e abandonou o tratamento antes de completar seis meses. Está\ninternada com hemoptise ocasional, para investigação e controle. O radiograma de tórax apresenta\nopacidades heterogêneas com áreas confluentes ao ápice do pulmão esquerdo. No momento do\nexame físico, a paciente apresenta volumosa hemoptise. Nesse caso, qual é a conduta imediata a\nser tomada?","options":{"A":"Intubação orotraqueal em \"\"sequência rápida\"\" para proteção de via aérea.","B":"Pré-oxigenação com O? a 100% sob máscara seguida de intubação traqueal.","C":"Fibrobroncoscopia.","D":"Decúbito de Trendelemburg e sobre o lado esquerdo da paciente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-232237","number":"232237","sourceNumber":"232237","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente do sexo masculino, de 36 anos, morador de rua. Refere há cerca de oito\nmeses mal-estar, febre vespertina não aferida,\nsudorese, dispneia aos moderados esforço, tosse\nseca esporádica e perda de 7 kg no período. Nega tabagismo. Ao exame, apresentava-se em\nregular estado geral, eupneico, consciente. Ausculta pulmonar com redução de murmúrio vesicular\nno terço inferior do hemitórax esquerdo associado com frêmito toracovocal diminuído e percussão\ncom macicez no mesmo local. O raio X de tórax mostra velamento no terço inferior do hemitórax\nesquerda, sem outras alterações. Qual é a conduta indicada para diagnóstico desse caso?","options":{"A":"Tomografia de tórax.","B":"Biópsia pulmonar.","C":"Toracocentese diagnóstica.","D":"Broncoscopia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-232238","number":"232238","sourceNumber":"232238","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente do sexo masculino, de 36 anos, morador de rua. Refere há cerca de oito\nmeses mal-estar, febre vespertina não aferida,\nsudorese, dispneia aos moderados esforços, tosse\nseca esporádica e perda de 7 kg no período. Nega tabagismo. Ao exame, apresentava-se em\nregular estado geral, eupneico, consciente. Ausculta pulmonar com redução de murmúrio vesicular\nno terço inferior do hemitórax esquerdo associado com frêmito toracovocal diminuído e percussão\ncom macicez no mesmo local. O raio X de tórax mostra velamento no terço inferior do hemitórax\nesquerdo, sem outras alterações. Qual é o diagnóstico mais provável para esse paciente?","options":{"A":"Câncer de pulmão.","B":"Tuberculose pleural.","C":"Pneumonia.","D":"Asma."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-241739","number":"241739","sourceNumber":"241739","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Acerca das infecções causadas por micobactérias, assinale a alternativa correta.","options":{"A":"As aparências histológicas das lesões causadas pelo M. tuberculosis são muito distintas\ndaquelas causadas pelas micobactérias não tuberculosas (MNT).","B":"A linfadenite dos linfonodos axilares e inguinais é a manifestação mais comum entre crianças.","C":"A úlcera de Buruli, causada pelo M. ulcerans, inicia-se como um nódulo eritematoso, mais\nfrequentemente nas pernas e braços, após um período de incubação de aproximadamente 3\nmeses. A lesão sofre necrose central e ulceração.","D":"As micobactérias não tuberculosas (MNT) são fontes comuns de infecções associadas a\ncateteres de pacientes hospitalizados.","E":"As infecções pulmonares por micobactérias não tuberculosas (MNT) são mais comuns na\npopulação pediátrica que entre adultos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249542","number":"249542","sourceNumber":"249542","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito de medidas de controle ambiental, grupo de medidas inclui adaptação de\nconsultórios que precisam ser arejados, com entrada de luz solar e janelas abertas. Sendo incorreto\nque:","options":{"A":"ventiladores direcionados para janelas podem contribuir para criar um direcionamento do fluxo\nde ar para área externa.","B":"exaustores exercem essa função de forma mais eficaz. Quando adquiridos, devem levar em\nconsideração a capacidade do equipamento e o volume de ar da sala que deve ser trocado cerca\nde seis a 15 vezes por hora.","C":"a instalação de aparelhos de ar condicionado em consultórios facilita a obtenção de exaustão\nadequada.","D":"em locais muito quentes, cuja utilização de aparelhos de ar condicionado proporciona conforto\nadicional, estudo de fluxo e adequação do\nexaustor, com trocas adequadas ao condicionador de ar,\npode ser feito por profissionais qualificados."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249545","number":"249545","sourceNumber":"249545","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa que não se caracteriza como um dos Princípios da Estratégia\npelo Fim da Tuberculose:","options":{"A":"Proteção e promoção dos direitos humanos, éticos e de equidade.","B":"Adaptação da estratégia sem metas nos países, com colaboração no âmbito global.","C":"Forte envolvimento das organizações da sociedade civil e de base comunitária.","D":"Gestão e responsabilização do governo, com componentes de monitoramento e avaliação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249547","number":"249547","sourceNumber":"249547","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"É necessário que, aliado ao fortalecimento das ações de saúde, haja também o\nincremento das ações de políticas de\ninclusão de proteção de direitos, como os programas sociais,\npara manter a tendência de queda da incidência e mortalidade por TB, bem como evitar o\ncrescimento dos índices de abandono do tratamento na população pobre ou extremamente pobre.","options":{"A":"O sucesso futuro do controle da TB pode não depender do progresso em todas essas áreas,\nsendo fundamental enfrentar também a discriminação\ne o preconceito, a fim de eliminar barreiras e\nampliar o acesso a bens e serviços públicos.","B":"O sucesso futuro do controle da TB pode depender do progresso em todas essas áreas, sendo\nirrelevante enfrentar também a discriminação e o preconceito, a fim de eliminar barreiras e ampliar\no acesso a bens e serviços públicos.","C":"O sucesso futuro do controle da TB pode depender do progresso em todas essas áreas, sendo\nfundamental enfrentar também a discriminação e o preconceito, a fim de eliminar barreiras e\nampliar o acesso a bens e serviços públicos.","D":"O sucesso futuro do controle da TB pode depender do progresso em todas essas áreas, sendo\nfundamental enfrentar também a discriminação e o preconceito, a fim de eliminar barreiras e reduzir\no acesso a bens e serviços públicos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249548","number":"249548","sourceNumber":"249548","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Fortalecer a articulação intra e intersetorial para garantia dos direitos humanos e\ncidadania nas ações de controle da doença, para pautar a tuberculose nas seguintes agendas de\ntrabalho da assistência social, educação, justiça e de direitos humanos. Nesse contexto, não\npodemos assumir o item:","options":{"A":"Implementar as recomendações das políticas vigentes de articulação intra e intersetorial.","B":"Implementar as recomendações da Instrução Operacional conjunta entre Secretaria de Vigilância\nem Saúde (SVS) e Secretaria Nacional de\nAssistência Social (SNAS).","C":"Fomentar a elaboração de legislações que contribuam para proteção social da pessoa com\ntuberculose.","D":"Não permitir a exposição da tuberculose nos meios de comunicação disponíveis."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249553","number":"249553","sourceNumber":"249553","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Fortalecer a participação da sociedade civil nas estratégias de enfrentamento da\ndoença, para articulação entre gestão e\nsociedade civil para o controle da tuberculose; podemos\napenas aceitar que:","options":{"A":"Inibir ações de comunicação e mobilização social desenvolvidas pela sociedade civil.","B":"Excluir a participação da sociedade civil na elaboração de campanhas de comunicação de\ntuberculose.","C":"Fomentar ações comunitárias de mobilização social para o enfrentamento da doença.","D":"Desarticulação entre gestão e sociedade civil para o controle da tuberculose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-249555","number":"249555","sourceNumber":"249555","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A TB pulmonar primária normalmente ocorre em seguida ao primeiro contato do\nindivíduo com o bacilo e, por isso, é mais comum em crianças. Somente está errado o item:","options":{"A":"As manifestações clínicas podem ser insidiosas.","B":"Paciente apresentando-se irritadiço, com febre baixa, sudorese noturna e inapetência.","C":"O exame físico pode ser inexpressivo.","D":"Sempre a tosse está presente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-229598","number":"229598","sourceNumber":"229598","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A TB persiste como importante e desafiador problema no âmbito da saúde da\npopulação, contribuindo para manutenção do quadro de desigualdade e exclusão social em\ndiversos países. Somente NÃO podemos aceitar que:","options":{"A":"É uma das enfermidades mais prevalentes entre as pessoas em situação de pobreza no mundo\ncom elevada carga em termos de mortalidade,\njuntamente com o HIV/AIDS e a malária.","B":"A distribuição do número de casos ocorre de forma igual no mundo, concentrando-se nos grupos\nsociais favorecidos.","C":"Concentrando-se em pessoas em situação de pobreza e fome, pessoas privadas de liberdade,\nminorias étnicas (como os indígenas no Brasil) e aquelas vivendo com HIV/AIDS.","D":"A TB, além de decorrente, é também perpetuadora da pobreza, pois compromete a saúde dos\nindivíduos e suas famílias causando impactos econômicos e sociais."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-229599","number":"229599","sourceNumber":"229599","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A cultura é um método de elevada especificidade e sensibilidade no diagnóstico da\nTuberculose (TB). Somente podemos ACEITAR que:","options":{"A":"Os métodos para cultura de micobactérias utilizam a semeadura da amostra em meios de cultura\nsólidos apenas.","B":"Nos casos pulmonares com baciloscopia negativa, a cultura do escarro pode aumentar em até\n30% o diagnóstico bacteriológico da doença.","C":"Os meios de cultura mais comumente utilizados são os sólidos à base de ovo,\nLöwenstein-Jensen e Ogawa-Kudoh. Eles têm a\nvantagem de serem de menor custo e de\napresentarem um baixo índice de contaminação.","D":"A desvantagem do meio sólido é o tempo de detecção do crescimento bacteriano, que varia de\n14 a 30 dias, podendo estender-se por até\noito semanas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-229602","number":"229602","sourceNumber":"229602","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No Brasil, o Programa Nacional de Controle da Tuberculose (PNCT) é responsável,\nentre outras ações, por estabelecer as diretrizes\npara o controle da doença, que tem tratamento\npadronizado, exclusivamente oferecido no serviço público de saúde. Somente NÃO podemos\naceitar que:","options":{"A":"O controle da Tuberculose (TB) envolve uma série de ações relacionadas a práticas clínicas,\norganização de serviços, interações com outras áreas dentro e fora do setor saúde e sistema de\ninformação e vigilância.","B":"O PNCT conta com uma equipe de monitoramento e avaliação que visita regularmente\nprogramas de controle de tuberculose locais,\nmunicipais e estaduais, além de manter comunicação\ndireta e reuniões com coordenadores estaduais e municipais considerados prioritários para o\ncontrole da TB.","C":"Nas últimas décadas, desde a reemergência da Tuberculose (TB) no mundo, o ano de 2015\ntornou-se um novo marco na história dessa doença, quando a Organização Mundial da Saúde\n(OMS) propôs acabar com a TB como um problema de saúde pública.","D":"O recrudescimento da tuberculose em consequência da epidemia de AIDS e os seus efeitos\nsutis nas pessoas vivendo com o HIV."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-229603","number":"229603","sourceNumber":"229603","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A nova estratégia amplia as ações de controle da doença, valoriza a inovação e a\nincorporação de novas tecnologias, fortalece a necessidade do compromisso político, somente\nsendo INADEQUADO que:","options":{"A":"Exclui as ações de proteção social aos pacientes e recomenda o acesso universal à saúde.","B":"Tratamento de todos os casos de tuberculose, incluindo casos de tuberculose drogar resistente\ne apoio ao paciente.","C":"Atividades colaborativas TB-HIV e manejo de outras comorbidades.","D":"Tratamento preventivo para pessoas com alto risco de adoecimento e vacina contra a\ntuberculose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-229605","number":"229605","sourceNumber":"229605","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O risco de transmissão da TB perdura enquanto o paciente eliminar bacilos no escarro.\nSomente podemos indicar como ERRADA a alternativa:","options":{"A":"Com o início do tratamento, a transmissão tende a diminuir gradativamente e, em geral, após 15\ndias, ela encontra-se muito reduzida.","B":"A importância de realizar baciloscopia de escarro de controle reside somente na confirmação da\neficácia do esquema terapêutico.","C":"As medidas de controle da infecção pelo M. tuberculosis devem ser mantidas até que seja\nconfirmada a negativação ou bacilos não viáveis à baciloscopia do caso fonte","D":"Crianças com TB pulmonar, em geral, têm baciloscopia negativa e, por isso, pouca importância\nna cadeia de transmissão da doença."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-215369","number":"215369","sourceNumber":"215369","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A maior parte dos casos utilizará medicamentos antituberculose nos esquemas\npadronizados e receberá o tratamento e\nacompanhamento nas unidades de Atenção Básica, sejam\ncasos novos ou retratamentos. Somente está ERRADO que,","options":{"A":"no caso do retratamento, coletar material (antes da reintrodução do esquema de tratamento)\npara baciloscopias.","B":"realizar cultura para micobactéria com identificação de espécie e teste de sensibilidade.","C":"procedimentos para confirmar o diagnóstico de tuberculose, mas não para detectar\nprecocemente resistências aos fármacos.","D":"após a coleta de material, o paciente deve reiniciar o esquema de tratamento, devendo ser\nreavaliado após os resultados dos demais exames."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205600","number":"205600","sourceNumber":"205600","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A forma pulmonar, além de ser mais frequente, é também a mais relevante para a\nsaúde pública, especialmente a positiva à\nbaciloscopia, pois é a principal responsável pela\nmanutenção da cadeia de transmissão da doença. Sendo INCORRETO apenas que:","options":{"A":"A ausculta pulmonar pode apresentar diminuição do murmúrio vesicular, sopro anfórico, mas\nnunca é normal.","B":"A tuberculose manifesta-se sob diferentes apresentações clínicas, que podem estar relacionadas\ncom idade, imunodepressão e órgão acometido.","C":"Além da tosse, outros sinais e sintomas podem ocorrer, e devem ser valorizados na investigação\ndiagnóstica individualizada.","D":"Outros sinais e sintomas comuns da tuberculose pulmonar são febre baixa vespertina, sudorese\nnoturna, emagrecimento e fadiga."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205607","number":"205607","sourceNumber":"205607","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A baciloscopia de outros materiais biológicos pode ser realizada para os casos de\nsuspeita clínica de tuberculose extrapulmonar, estando INADEQUADO apenas:","options":{"A":"A tuberculose extrapulmonar tem sinais e sintomas dependentes dos órgãos e/ou sistemas\nacometidos.","B":"As principais formas diagnosticadas de tuberculose extrapulmonar no Brasil são pleural e/ou\nempiema pleural tuberculoso, ganglionar periférica, meningoencefálica, miliar, laríngea,\npericárdica,\nóssea, renal, ocular e peritoneal.","C":"A tuberculose extrapulmonar tem ocorrência aumentada em pessoas que vivem com HIV/aids\n(PVHA), especialmente entre aqueles com imunocomprometimento grave.","D":"É raro a associação da tuberculose extrapulmonar à pulmonar (tuberculose mista)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205610","number":"205610","sourceNumber":"205610","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O teste rápido molecular para tuberculose (TRM-TB) é um teste de amplificação de\nácidos nucléicos utilizado para detecção de DNA\ndo M. tuberculosis e triagem de cepas resistentes\nà rifampicina pela técnica de reação em cadeia da polimerase (PCR) em tempo real. Indica-se a\nrealização de TRM-TB, apenas para possível identificação de resistência à rifampicina, mais a\nbaciloscopia de escarro, cultura para micobactérias e teste de sensibilidade. Sendo INADEQUADO\nque:","options":{"A":"No Brasil, o TRM-TB está indicado, prioritariamente, para o diagnóstico de tuberculose pulmonar\nem adultos apenas.","B":"O TRM-TB poderá ser utilizado para amostras extrapulmonares de líquor, gânglios linfáticos e\noutros tecidos.","C":"Em amostras de liquor, gânglios linfáticos e outros tecidos, o resultado negativo não exclui\ntuberculose, sendo necessário continuar a investigação.","D":"A baciloscopia direta, a cultura e o TRM-TB são considerados confirmatórios de tuberculose\nativa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205618","number":"205618","sourceNumber":"205618","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Pessoas vivendo com HIV/aids PVHA estão mais vulneráveis à tuberculose, sendo\nessa a principal causa associada definida\nde óbito entre as doenças infecciosas nesse grupo, o que\njustifica especial atenção às pessoas com co-infecção TB-HIV. Sendo ADEQUADO apenas que:","options":{"A":"Outros sintomas, como febre, sudorese noturna ou emagrecimento (apenas quando associados\nà tosse), também podem indicar tuberculose e\ndemandam investigação. Deve-se solicitar, para\nessas pessoas, baciloscopia ou teste rápido molecular para tuberculose e cultura com teste de\nsensibilidade.","B":"Outros sintomas, como febre, sudorese noturna ou emagrecimento (associado ou não à tosse),\ntambém podem indicar tuberculose, mas não demandam investigação. Deve-se solicitar, para\nessas pessoas, baciloscopia ou teste rápido molecular para tuberculose e cultura com teste de\nsensibilidade.","C":"Outros sintomas, como febre, sudorese noturna ou emagrecimento (associado ou não à tosse),\ntambém podem indicar tuberculose e demandam investigação. Deve-se solicitar, para essas\npessoas, baciloscopia ou teste rápido molecular para tuberculose e cultura com teste de\nsensibilidade.","D":"Outros sintomas, como febre, sudorese noturna ou emagrecimento (associado ou não à tosse),\ntambém podem indicar tuberculose e demandam investigação. Deve-se solicitar, para essas\npessoas o teste rápido molecular apenas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-214927","number":"214927","sourceNumber":"214927","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação à tuberculose extrapulmonar, considere as seguintes afirmativas: I - A\ntuberculose pleural é a forma mais comum em indivíduos HIV negativo; ocorre mais em jovens e\npode apresentar-se clinicamente simulando pneumonia bacteriana aguda. II - A tuberculose\nganglionar periférica é a forma mais frequente em pacientes HIV positivo em crianças, sendo mais\ncomum abaixo dos 40 anos. III - A tuberculose óssea é mais comum em idosos, sendo rara em\ncrianças, e tem como quadro clínico a tríade dor lombar, dor à palpação e sudorese noturna.\n\nEstá(ão) correta(s):","options":{"A":"I, apenas","B":"II, apenas","C":"I, II, III","D":"I, II"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-201693","number":"201693","sourceNumber":"201693","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Ao atender uma criança de sete anos, com tuberculose pulmonar, no início do\ntratamento, deve ser avaliado o peso do\npaciente para o correto ajuste da dose das medicações a\nserem utilizadas, uma vez que o esquema de tratamento é diferente do esquema para adultos, visto\nhaver possibilidade de neurite óptica por um dos medicamentos usados. Considerando esse evento\nadverso, qual das drogas não poderá ser utilizada em crianças?","options":{"A":"Rifampicina.","B":"Isoniazida.","C":"Pirazinamida.","D":"Etambutol."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-214973","number":"214973","sourceNumber":"214973","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma puérpera tem diagnóstico de tuberculose bacilífera, tendo iniciado seu tratamento\nlogo após o nascimento do filho. Neste caso, a\nmelhor conduta com relação ao recém-nascido é:","options":{"A":"manter aleitamento e iniciar isoniazida","B":"como iniciou tratamento, manter aleitamento com o uso de máscara na mãe","C":"manter aleitamento e vacinar com BCG intradérmico","D":"manter aleitamento, vacinar com BCG intradérmico e iniciar isoniazida"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-201747","number":"201747","sourceNumber":"201747","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose (TB) é a doença infecciosa de maior mortalidade entre as pessoas\nvivendo com HIV (PVHIV). Em 2015, registraram-se\n10,4 milhões de casos de TB em todo o\nmundo, segundo a Organização Mundial da Saúde, sendo que, destes, 11% ocorreram em\nportadores de HIV. A estratégia de controle de coinfecção TB-HIV está pautada no diagnóstico\nprecoce de ambas as afecções e na garantia de tratamento adequado para o paciente, de forma\noportuna. No contexto apresentado:","options":{"A":"O teste rápido molecular é a atual metodologia indicada para o diagnóstico de tuberculose,\nporém ele não está validado para amostras\nextrapulmonares.","B":"As PVHIV têm de três a doze vezes mais chance de adoecer por TB que a população em geral.\n\nO tratamento de tuberculose latente está indicado aquelas com contagem de LT-CD4 < 350\ncéls/mm3, desde que descartada a doença ativa.","C":"O tratamento antirretroviral, em caso de coinfecção TB-HIV, deve ser instituído o mais\nprecocemente possível, concomitante ao esquema anti-TB, independentemente do nível de\nLT-CD4.","D":"A genotipagem pré-tratamento do HIV está indicada e o esquema antirretroviral preferencial,\npara virgens de tratamento e coinfectados com\ntuberculose, é a associação de tenofovir +\nlamivudina + dolutegravir."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-216520","number":"216520","sourceNumber":"216520","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sr. Waldomiro, 44 anos, chega para consulta com sua médica de família, Dra. Mariana,\nqueixando-se de tosse produtiva, com presença de sangue, perda de peso e febre durante a noite,\nnão mensurada. Refere que o quadro está há mais ou menos 3 semanas. Ele está impossibilitado\nde ir ao trabalho por estar se sentindo muito mal com essa tosse que sai sangue. Refere ser lixeiro,\ne que andou trabalhando sob chuva e notou piora após esses dias. No caso do Sr. Waldomiro, qual\na conduta adequada para a Dra. Mariana tomar?","options":{"A":"Encaminhar o paciente ao programa de tuberculose imediatamente.","B":"Solicitar baciloscopia do escarro, sendo 2 amostras, uma no momento do diagnóstico clínico, na\nprópria unidade de saúde, e outra pela manhã em jejum, levando ao laboratório do programa de\ntuberculose para ser acompanhado o resultado. Se positivo, ser notificado e iniciado o tratamento e\nreencaminhado o paciente para sua unidade de saúde para seguimento compartilhado.","C":"Solicitar baciloscopia do escarro, sendo 1 amostra, no momento do diagnóstico, e encaminhada\nao programa de tuberculose para seguimento do\ncaso.","D":"Encaminhar o paciente para a unidade de pronto atendimento para realizar os exames\npertinentes."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-202636","number":"202636","sourceNumber":"202636","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O complexo de Ghon está relacionado à seguinte patologia:","options":{"A":"sarcoidose.","B":"pneumonia por Pneumocystis carinii.","C":"aspergilose.","D":"tuberculose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-216465","number":"216465","sourceNumber":"216465","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à história natural da tuberculose na infância, é correto afirmar que:","options":{"A":"A infecção tem um curto período de incubação, cerca de 15 dias.","B":"Os lactentes apresentam maior risco de progressão para formas graves, devendo ser priorizados\nna investigação mesmo quando vacinados com BCG.","C":"A tuberculose renal ocorre com alta frequência na infância, especialmente em lactentes.","D":"A infecção latente de aquisição recente, há menos de um ano, apresenta menor risco de\nprogressão para doença ativa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-202698","number":"202698","sourceNumber":"202698","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O sinal de Monod é observado","options":{"A":"no crânio.","B":"no tórax.","C":"no abdome.","D":"na pelve."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205603","number":"205603","sourceNumber":"205603","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"As medidas de controle de transmissão dividem-se em categorias, as administrativas\nabaixo listadas apresentam uma alternativa ERRADA,\nqual seria?","options":{"A":"As medidas administrativas, isoladamente, são as menos efetivas na prevenção da transmissão\nda tuberculose e não devem ser priorizadas.","B":"Essas medidas estão relacionadas a rotinas e protocolos e previnem a geração de partículas\ninfectantes na unidade, reduzindo assim a exposição de profissionais de saúde e usuários do\nserviço.","C":"Tendo em vista que não é possível eliminar completamente a geração e a exposição às\npartículas infectantes, as medidas de controle\nambiental e proteção individual são complementares\na essas ações.","D":"São relacionadas à prática do trabalho cotidiano e fazem parte da primeira linha na prevenção\nda disseminação da TB em unidades de saúde."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205627","number":"205627","sourceNumber":"205627","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Dentre os cuidados que devem ser observados nas áreas de coleta de escarro, NÃO\npodemos concordar com o seguinte:","options":{"A":"Em geral, a pressão negativa pode ser obtida apenas com exaustores.","B":"A descarga do ar exaurido deve ser direcionada para o exterior da unidade, para locais\nafastados de outros pacientes, dos profissionais de saúde e de sistemas de captação de ar.","C":"Se necessário, o exaustor pode ser conectado a um duto, para que a descarga de ar se faça a,\npelo menos, 9 m de qualquer abertura externa do ambiente (como janelas, vãos de entrada de\npessoas etc.) e a uma altura de 3 m acima do teto da construção, sem necessidade de\nconsideração a direção dos ventos predominantes.","D":"Caso não seja viável esse direcionamento do ar , uma alternativa é a utilização de filtros de\nalta\neficiência para ar particulado (filtros Hepa ? High Efficiency Particulate Air), que eliminam os\nbacilos\nem suspensão, permitindo que o ar seja descarregado em ambientes onde circulem pessoas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205631","number":"205631","sourceNumber":"205631","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Considerando a maior proporção de abandono, falha ao tratamento e ocorrência de\neventos adversos em pessoas com coinfecção TB-HIV, a intensificação de estratégias de adesão\nao tratamento de ambos os agravos é uma prioridade. Esses indivíduos necessitam de avaliação\nconstante, manejo adequado e escuta qualificada para os diferentes contextos individuais,\nprovendo abordagens resolutivas e adequadas. Sendo INADEQUADO que:","options":{"A":"O Tratamento Diretamente Observado (TDO) deve ser universal e está indicado a todos os\npacientes com tuberculose.","B":"O Serviços de Atenção Especializada SAE deve se articular com as unidades da Atenção Básica\npara realizar o TDO compartilhado.","C":"Caso haja possibilidade, o TDO poderá ser realizado no SAE.","D":"Caso o TDO não esteja disponível, recomenda-se a dispensação dos medicamentos antiTB com\nperiodicidade máxima de 60 dias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205635","number":"205635","sourceNumber":"205635","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para diminuir aerossóis contendo Mycobacterium tuberculosis (bacilo da tuberculose)\nno ambiente onde circulam pacientes que o produzam\ne que oferece algum risco de transmissão.\nPreciso considerar diversos aspectos, um dos abaixo se mostra ERRADO, indique-o.","options":{"A":"Deve-se priorizar ações preventivas para os pacientes não diagnosticados (sintomático\nrespiratório) ou nas primeiras cinco semanas de tratamento.","B":"Ocorrendo infecção pelo bacilo da TB, as pessoas com maior risco de adoecer são aquelas com\na imunidade comprometida.","C":"Com o início do tratamento e o uso correto de medicamentos antiTB, a transmissibilidade\ndiminui.","D":"Dentre as ações de controle da coinfecção TB-HIV direcionadas ao SAE, as medidas de controle\nda infecção pelo Mycobacterium tuberculosis\nrepresentam uma prioridade."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205639","number":"205639","sourceNumber":"205639","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Especial cuidado deve ser observado nas áreas de coleta de escarro. Sendo\nincompatível o seguinte item:","options":{"A":"Nunca utilizar cômodos fechados, como banheiros, para esse procedimento.","B":"O escarro induzido só deve ser realizado em salas com condições adequadas de biossegurança.","C":"De preferência esta ação deve ocorrer em área interna da unidade, resguardando a privacidade\ndo paciente.","D":"É um procedimento que estimula a produção de aerossóis."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-205642","number":"205642","sourceNumber":"205642","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para o manejo da Coinfecção TB-HIV em Serviços de Atenção Especializada a\nPessoas Vivendo com HIV/AIDS, de maneira adequada,\ndevemos nos atentar para diversas\ninterações de condutas, sendo INADEQUADA apenas que:","options":{"A":"Pacientes multiexperimentados em TARV que utilizam medicamentos de terceira linha\n(darunavir, tipranavir, raltegravir, etravirina\nou enfuvirtida) devem ter seu esquema de tratamento\ndefinido com suporte de profissionais experientes no manejo da resistência do HIV e/ou médicos de\nreferência em genotipagem.","B":"Pacientes com coinfecção TB-HIV devem ser monitorados cuidadosamente para avaliar a\nefetividade e toxicidade do tratamento de ambas as doenças.","C":"A rifampicina, indutora do citocromo P450, aumenta o metabolismo do inibidor de protease IP, o\nque ocasiona diminuição de suas concentrações\nplasmáticas.","D":"A rifampicina possui eficácia e eficiência comprovadas, deve fazer parte do esquema secundário\nde tratamento para TB e compõe esquema básico\npreconizado."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-187573","number":"187573","sourceNumber":"187573","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com tosse persistente há mais de 8 semanas, previamente hígido, nega\ntabaquismo, com Rx de tórax normal, nega uso de medicações. Os diagnósticos prováveis são","options":{"A":"asma, rinossinusite ou doença do refluxo gastroesofágico.","B":"rinossinusite, hipertensão pulmonar ou doença pulmonar obstrutiva crônica.","C":"doença do refluxo gastroesofágico, pneumotórax ou rinite alérgica.","D":"tuberculose, embolia pulmonar ou disfunção de cordas vocais."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-182428","number":"182428","sourceNumber":"182428","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma puérpera tem diagnóstico de tuberculose bacilífera, tendo iniciado seu tratamento\nlogo após o nascimento do filho. Neste caso, a\nmelhor conduta com relação ao recém-nascido é:","options":{"A":"manter aleitamento e iniciar isoniazida","B":"como iniciou tratamento, manter aleitamento com o uso de máscara na mãe","C":"manter aleitamento e vacinar com BCG intradérmico","D":"manter aleitamento, vacinar com BCG intradérmico e iniciar isoniazida"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-183266","number":"183266","sourceNumber":"183266","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação à Hemoptise Maciça, assinale a alternativa INCORRETA:","options":{"A":"Pode ser definida como perda maior que 500-600mL de sangue proveniente dos pulmões em 24\nhoras","B":"A atual taxa de mortalidade é de aproximadamente 13% e está mais relacionada com a\nexsanguinação do que a asfixia.","C":"O diagnóstico e o tratamento da hemoptise maciça caracteristicamente incluem radiografia de\ntórax e broncoscopia rígida de emergência.","D":"As principais causas de hemoptise maciça são a tuberculose, bronquiectasia e câncer."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-173591","number":"173591","sourceNumber":"173591","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem de 27 anos, em tratamento para tuberculose pulmonar (TB), baciloscopia no\ndiagnóstico ++ e teste molecular positivo para Mycobacterium tuberculosis com ausência de\nresistência à rifampicina. Paciente no final do 2º. mês do esquema básico (EB) preconizado pelo\nMinistério da Saúde (rifampicina, isoniazida, pirazinamida e etambutol) administrado sob\nobservação direta. Neste momento, exibida baciloscopia negativa, teste molecular positivo e com\npersistência de tosse esporádica. Com base nas melhores evidências, qual é a conduta a ser\nseguida neste momento?","options":{"A":"Mudar para a segunda fase do EB.","B":"Instituir tratamento para TB multirresistente.","C":"Drecretar falência do tratamento e reiniciar o EB.","D":"Solicitar teste de sensibilidade para isoniazida e demais drogas e manter esquema atual."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-186482","number":"186482","sourceNumber":"186482","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Considerando o Tratamento Diretamento Observado (TDO) para tuberculose, segundo\no Plano nacional pelo fim da tuberculose como\nproblema de saúde pública - 2017 do Ministério da\nSaúde, podemos afirmar que todas as alterantivas estão corretas EXCETO que:","options":{"A":"O Tratamento Diretamente Observado consiste na ingestão diária dos medicamentos\nantituberculose pelo paciente sob a observação de um profissional de saúde.","B":"Para registro do Tratamento Diretamente Observado no Sistema de Informação de Agravos de\nNotificação (Sinan), é necessário que a tomada seja observada todos os dias, ao menos 3 vezes na\nsemana, no mínimo 24 tomadas da medicação na fase de ataque, e 48 na fase de manutenção.","C":"O Tratamento Diretamente Observado estimula a criação de vínculo entre profissionais de saúde\ne o paciente, facilita a cura por meio da\nadesão ao tratamento, fortalece a atenção à pessoa com\nTB devido à melhora do acolhimento e estimula a organização do serviço para o apoio à tomada da\nmedicação.","D":"No Sistema de Informação de Agravos de Notificação (Sinan), será considerado Tratamento\nDiretamente Observado (TDO) quando realizado por amigos e/ou familiares."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-186506","number":"186506","sourceNumber":"186506","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Ao longo dos últimos anos, diversos avanços foram alcançados pelos programas de\ncontrole da tuberculose em todas as esferas de gestão do SUS. Contudo, ainda existem desafios a\nserem superados para o alcance do objetivo de acabar com a tuberculose como um problema de\nsaúde pública no Brasil (Ministério da Saúde; Brasília-DF 2017). Entre os avanços, estão as\nFortalezas para o Programa Nacional de Controle de Tuberculose e enfrentamento da doença.\n\nPodemos dizer que está INCORRETO:","options":{"A":"Diagnóstico e tratamento padronizado disponíveis no SUS e implantação da Rede de Teste\nRápido Molecular.","B":"Elevada cobertura vacinal do BCG em todo território nacional e a centralização das ações de\ndetecção, diagnóstico e acompanhamento da tuberculose.","C":"Estabelecimento de parcerias intersetoriais com o Ministério da Justiça e o Ministério do\nDesenvolvimento Social e Agrário e parcerias intrassetoriais com o Departamento de Infeccções\nSexualmente Transminssíveis (IST), Aids e Hepatite virais, Atenção Básica e a Secretaria da\nCiência, Tecnologia e Insusmos Estratégicos (SCTIE).","D":"Desenvolvimento de estratégias de análise de dados para o monitoramento das ações de\ncontrole da tuberculose na atenção básica em\nparceria com o Departamento de Atenção Básica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-157045","number":"157045","sourceNumber":"157045","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Qual infecção pulmonar oportunista é mais frequente em pacientes\nimunocomprometidos?","options":{"A":"Candidíase.","B":"Criptococose.","C":"Nocardiose.","D":"Aspergilose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-150263","number":"150263","sourceNumber":"150263","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma paciente de 18 anos é atendida no ambulatório de um Centro de Atendimento\nIntegral à Saúde (CAIS) relatando história\nde tosse seca, perda de 4 kg em duas semanas, febre\nbaixa vespertina e inapetência há 20 dias. Há três dias, iniciou dor forte em pontada em base do\nhemitórax direito, ventilatório-dependente com irradiação para ombro direito. Apresenta-se lúcida,\ntemperatura axilar de 37,5°C, frequência respiratória de 20 irpm; saturação de oxigênio (SatO?) à\noximetria de pulso (SatO?) igual a 96%, pressão arterial de 120 x 70 mmHg, normocárdica, com\nausculta pulmonar evidenciando diminuição do murmúrio vesicular em base direita; expansibilidade\ndiminuída e macicez à percussão neste local; hemograma normal. A radiografia de tórax mostra\nvelamento de dois terços do hemitórax direito. (Conforme a imagem do caderno de questões). A\ntoracocentese evidenciou líquido amarelo citrino, exsudativo segundo os critérios de LIGHT,\napresentando 5% de neutrófilos, 90% de linfócitos e 5% de eosinófilos; raros mesoteliócitos;\nadenosina deaminase de 100 UI/L; glicose pleural de 80 mg/dl; citologia oncótica negativa;\npesquisa direta de bacilos álcool-ácido-resistentes negativa no material. A principal hipótese\ndiagnóstica para esta paciente é:","options":{"A":"Quilotórax.","B":"Tuberculose pleural.","C":"Derrame parapneumônico complicado.","D":"Derrame paraneoplásico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/150263.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-150239","number":"150239","sourceNumber":"150239","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem de 32 anos, morador de rua em Goiânia, usuário de crack, refere que há cerca\nde quatro meses iniciou quadro de tosse\nprodutiva, acompanhada de febre não aferida e suores\nnoturnos, bem como perda de cerca de 8 kg [peso habitual 50 kg]. Neste período, procurou três\nvezes os serviços de saúde, sendo que, nas duas últimas oportunidades, recebeu diagnóstico de\npneumonia. Fez uso irregular de amoxacilina no primeiro diagnóstico e de azitromicina no segundo,\nagora regularmente. Ao exame, estava febril [38,3 °C], hipocorado 2+/4+, anictérico, hidratado,\neupneico em repouso, mas com leve dispneia ao caminhar. O aparelho respiratório evidenciava\ndiminuição do murmúrio vesicular em terço superior do hemitórax direito, com presença de\nestertores crepitantes, bem como aumento do frêmito toracovocal, nesta topografia. O aparelho\ncardiovascular não exibia alterações significativas. O abdômen não mostrava massas ou\nvisceromegalias. Sem adenomegalias palpáveis em cadeia cervical, supraclaviculares e axilares.\n\nSem lesões de pele. Os dentes se encontravam em mau estado de conservação. Não havia lesões\nna mucosa oral. A radiografia de tórax\nmostrou opacidade heterogênia em lobo superior do pulmão\ndireito, bem como infiltrados micronodulares em bases, bilateralmente. Uma baciloscopia do\nescarro [coloração de Ziehl-Neelsen] foi negativa. Qual é a principal hipótese diagnóstica para esse\npaciente?","options":{"A":"Pneumonia por Kebsiella pneumoniae.","B":"Tuberculose pulmonar.","C":"Paracoccidioidomicose pulmonar.","D":"Abscesso pulmonar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-160551","number":"160551","sourceNumber":"160551","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose continua sendo um problema de saúde pública no Brasil. A\ndescentralização das ações de controle e o\nexercício da vigilância epidemiológica no âmbito da\natenção primária à saúde têm importância destacada nesse cenário. Sobre essa doença, verifica-se\no seguinte:","options":{"A":"O teste cutêneo com tuberculina é diagnóstico, mas não é um exame de rastreamento útil em\ncontatos potenciais com pessoas infectadas.","B":"Os indivíduos com tuberculose ativa devem ser inicialmente tratados com terapia multifármacos,\ncomo isoniazida, rifampicina, clofazimina e dapsona.","C":"Somente pessoas com tuberculose ativa pulmonar ou laríngea transmitem a doença e, em geral,\napós 15 dias de tratamento adequado, já não são mais capazes de infectar outras pessoas.","D":"A inoculação pelo bacilo pode resultar em dois processos: infecção latente assintomática ou\ndoença ativa. De maneira mais frequente, essa\ninoculação resulta em doença ativa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-140628","number":"140628","sourceNumber":"140628","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente do sexo masculino, 34 anos , dá entrada no pronto-socorro trazido por\nfamiliares com quadro de icterícia há 3 dias. Familiar relata que paciente se queixou, durante a\nsemana, de intensa dor muscular, principalmente em panturrilhas, e cefaleia frontal intensa.\n\nPaciente tem histórico de trabalho no serviço de distribuição de água da cidade. No momento do\nexame, encontrava-se confuso, prostrado, com leve taquicardia e pele levemente alaranjada. Além\ndisso, apresentava hipersensibilidade no quadrante superior direito do abdômen. Qual o provável\ndiagnóstico clínico do paciente?","options":{"A":"Hantavirose","B":"Blastomicose sul americana","C":"Hepatite A","D":"Leptospirose ictérico hemorrágica"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-137037","number":"137037","sourceNumber":"137037","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com quadro de dengue dá entrada no PS com dor abdominal, náuseas e\nvômitos. Ao exame físico, encontra-se\ndesidratado, com regular estado geral e com leve\nhipotensão. O hemograma revela série vermelha dentro dos padrões normais, leucócitos de 7.500 e\n\n100.000 plaquetas. Foi submetido a hidratação venosa, analgésico e atiemético. Após 24 horas as\nplaquetas caíram para 90.000 e houve aumento do hematócrito e os leucócitos permanecem em\n\n7.500. Nesse caso é preciso muita atenção e cuidados, pois existe a possibilidade de estar\nevoluindo:","options":{"A":"com hemorragia, visto que as plaquetas estão baixas e isso representa agravamento do quadro\nclínico.","B":"com complicações importantes do ponto de vista epidemiológico dependente da cepa viral.","C":"com desidratação importante com sequestro de líquidos para o terceiro espaço, correndo risco\nde choque hipovolêmico, pois o aumento do hematócrito significa hemoconcentração.","D":"de maneira natural para os pacientes portadores de dengue e não há motivos para\npreocupação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-140627","number":"140627","sourceNumber":"140627","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na avaliação de uma criança com quadro de dengue, os seguintes achados indicam\nsinais de alerta :","options":{"A":"sangramento de mucosas e leucopenia.","B":"leucopenia e prova do laço positiva.","C":"dor abdominal contínua e prova do laço positiva.","D":"sangramento de mucosas e dor abdominal contínua."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-127310","number":"127310","sourceNumber":"127310","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Qual das alternativas abaixo NÃO representa sinal de alerta/alarme de evolução para a\nforma grave de Dengue?","options":{"A":"Aparecimento de leucopenia, linfocitose relativa com atipialinfocitária.","B":"Diminuição repentina da temperatura corpórea ou hipotermia.","C":"Aumento repentino do hematócrito.","D":"Dor abdominal intensa e contínua"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-129881","number":"129881","sourceNumber":"129881","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Os elementos clínicos laboratoriais que sugerem diagnóstico de dengue\nhemorrágica/síndrome de choque da dengue são:","options":{"A":"Dor abdominal intensa e contínua, vômitos persistentes, hipotensão postural e/ou lipotimia.","B":"vômitos volumosos, leucocitose, plaquetose e hemoconcentração.","C":"dor abdominal, leucopenia, plaquetopenia e hemodiluição.","D":"prurido, leucopenia, anemia e hemodiluição."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-111372","number":"111372","sourceNumber":"111372","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A leptospirose é uma zoonose de distribuição global e é especialmente comum em\nregiões tropicais. Seus diagnósticos diferenciais incluem dengue, outras febres hemorrágicas e\ndoenças causadas por mordida de artrópodes ou roedores. Podemos afirmar que:","options":{"A":"As formas brandas da doença apresentam acometimento hepático levando a disfunção\nhepatocelular, incluindo a diminuição da produção de fatores da coagulação e albumina.","B":"Entre os pacientes infectados, 90% apresentam a forma ictérica e 10% a forma anictérica.","C":"A meningite asséptica é a complicação mais comum dos casos ictéricos, principalmente na fase\nimune.","D":"A transmissão ocorre por contato indireto com animal infectado.","E":"Todas as alternativas estão corretas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-109185","number":"109185","sourceNumber":"109185","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para o diagnóstico laboratorial da Febre da Dengue Hemorrágica (DHF), os principais\nexames são:","options":{"A":"Hematócrito e tempo de protrombina.","B":"Hematócrito e dosagem de hemoglobina.","C":"Número de plaquetas e leucograma.","D":"Hematócrito e contagem de plaquetas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-106731","number":"106731","sourceNumber":"106731","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em 2009 um novo vírus Influenza A (H1N1) foi reconhecido em pacientes. Este vírus:","options":{"A":"tem acometido desproporcionalmente mais idosos do que crianças e indivíduos adultos jovens\nno Brasil.","B":"apresenta, na maioria dos casos, replicação menos prolongada em humanos, se comparado ao\nvírus da Influenza sazonal.","C":"está associado a quadros pneumônicos graves em obesos.","D":"tem período de incubação de sete dias."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-110277","number":"110277","sourceNumber":"110277","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O Ministério da Saúde tem alertado sobre o risco de epidemias de febre de\nChikungunya (FC) e dengue no próximo ano. Sobre estas doenças, sabe-se que:","options":{"A":"As duas têm quadro clínico semelhante e diferenciam-se pelo vetor e pela forma de transmissão;","B":"a febre de Chikungunya, ao contrário da dengue, não é a doença de notificação imediata;","C":"o período de incubalão da febre de Chikungunya é de 15 a 20 dias; já na dengue, este período é\nde 3 a 7 dias;","D":"o quadro clínico da febre de Chikungunya se diferencia do da dengue por apresentar dores\narticulares mais intensas e que podem cronificar por meses."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-102493","number":"102493","sourceNumber":"102493","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"O controle químico dirigido para a fase adulta do mosquito é a medida de controle vetorial\nrecomendada na leishmaniose visceral.","B":"A transmissão das hepatites, por via sexual, é mais comum para a HCV que para o HBV.","C":"O indivíduo infectado pelo HIV só transmite a doença na sua fase aguda.","D":"No Brasil, a maioria dos casos de febre amarela ocorre nos meses de novembro e dezembro.","E":"Nenhuma das anteriores."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-103683","number":"103683","sourceNumber":"103683","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre a febre amarela, considere as afirmações a seguir. 1. É uma infecção viral\ntransmitida por picada de mosquito, que se\ncaracteriza por sinais sistêmicos gerais, como febre,\nmal estar, mialgia, cefaleia e manifestações gastrointestinais que duram em torno de 7 dias. Os\nsintomas hepáticos e renais ocorrem sempre após essa fase inicial; 2. As manifestações hepáticas\ne renais da febre amarela ocorrem somente nos pacientes que evoluem para as formas graves e\nmalignas da doença. As formas leves e moderadas não apresentam alterações hepáticas; 3. A\nvacina da febre amarela é composta por vírus inativado, motivo pelo qual é contraindicada somente\npara pacientes com histórico de alergia à proteína de ovo; 4. O diagnóstico laboratorial da febre\namarela baseia-se em metodologias sorológicas, com a pesquisa de anticorpos IgG e IgM. Os\ntestes para isolamento viral e de detecção de ácido nucleico também podem ser utilizados para\npacientes que estejam em uma fase precoce da doença. São CORRETAS as afirmações contidas,\nAPENAS, em:","options":{"A":"1, 3 e 4","B":"3 e 4","C":"2 e 4","D":"1 e 2"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-101190","number":"101190","sourceNumber":"101190","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A Leishmaniose Tegumentar Americana é uma infecção não contagiosa, causada por\nespécies de protozoários do gênero Leishmania. Produz lesões cutâneas e nas mucosas, sendo\ndenominada entre leigos de úlcera de Bauru ou ferida brava. Em relação a esta infecção,\nconsidera-se que:","options":{"A":"as lesões cutâneas caracterizam-se por pápulas e pústulas pruriginosas e dolorosas, que nunca\nulceram e são mais comuns em tronco.","B":"as lesões nas mucosas iniciam-se com eritema e infiltração nasal, evoluindo com destruição do\nsepto. Podem acometer lábios, palato, gengivas, língua, faringe e laringe.","C":"a intradermorreação de Montenegro, se positiva, permite a confirmação do diagnóstico.","D":"a droga de escolha para o tratamento são antibióticos da classe das tetraciclinas, por longos\nperíodos, sendo a dose calculada por peso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-101218","number":"101218","sourceNumber":"101218","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente procedente de Niquelândia-GO procurou o serviço de saúde com duas lesões\nulceradas que se iniciaram há quatro semanas, ilustradas na imagem a seguir. Trazia o resultado\nde uma intradermorreação de Montenegro (IDRM) negativa. No caso deste paciente, deve-se (VER\nIMAGEM):","options":{"A":"excluir o diagnóstico de leishmaniose tegumentar dada a presença de IDRM negativa.","B":"indicar exames sorológicos, pois são considerados indispensáveis para o diagnóstico etiológico\nde doenças parasitárias.","C":"indicar raspado da lesão para coloração pelo Gram e Ziehl-Neelsen.","D":"considerar as seguintes hipóteses diagnósticas:\n\nleishmaniose tegumentar, piodermite, paracoccidioidomicose e esporotricose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/101218.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-109344","number":"109344","sourceNumber":"109344","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A dengue é a doença viral, transmitida por mosquito, mais prevalente do mundo. A\nprova do laço é utilizada na avaliação dos pacientes acometidos por essa doença. Segundo o\ndocumento \"Dengue - diagnóstico e manejo clínico - criança\" (Ministério da Saúde, 2011), essa\nprova, em crianças:","options":{"A":"Deve apresentar dez ou mais petéquias na área delimitada para ser considerada positiva.","B":"Deve ser realizada mantendo-se o manguito insuflado até o valor correspondente à fórmula\n(PAS + PADx2)/3.","C":"Deve ser realizada mantendo-se o manguito insuflado até o valor determinado por um período\nde seis minutos.","D":"Deve ser realizada desenhando-se um quadro de cinco centímetros de lado no antebraço da\ncriança e contando o número de plaquetas formadas dentro dele."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-85352","number":"85352","sourceNumber":"85352","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança de sete anos de idade, apresenta quadro de febre alta há seis dias. Há um dia\niniciou dor abdominal, vômitos associados com cefaleia holocraniana, mialgia, artralgia e dor\nretrorbitária. Ao exame, encontra-se prostrada, PA 97 X 60 mmHg, FC 85 bpm, prova do laço\npositiva, tempo de enchimento capilar = 1,5 segundos. Abdome com hepatomegalia dolorosa,\npulmões com diminuição do murmúrio vesicular em base direita. Os exames laboratoriais revelam:\nhematócrito 49%, plaquetas 81000. RX de tórax com derrame pleural à direita. A classificação da\ndoença e o tratamento inicial adequado são, respectivamente:","options":{"A":"dengue clássica - concentrado plaquetário.","B":"dengue associada à pneumonia - antibioticoterapia.","C":"febre hemorrágica da dengue - soro fisiológico 20 ml/kg.","D":"síndrome do choque da dengue - ringer lactato 10 ml/kg."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-86351","number":"86351","sourceNumber":"86351","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Joaquim Barbosa sempre residiu em São Vicente, litoral paulista, município onde\nnasceu, há 30 anos. Tem queixa de febre há um\ndia. Acaba de voltar de pescaria de uma semana\nno rio Tocantins, sua primeira viagem fora dos limites do estado de São Paulo. Na rua onde\nJoaquim mora houve, só neste começo de mês, três casos de dengue. Do ponto de vista de saúde\npública, qual a pergunta mais relevante a ser feita a Expedito?","options":{"A":"Se tomou vacina contra febre amarela 10 dias antes da viagem.","B":"Se em sua casa há pneus velhos ao relento.","C":"Se percebeu ter sido picado por mosquito durante dia claro.","D":"Se não se importa em retornar em 5 dias para coleta de sangue."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-85326","number":"85326","sourceNumber":"85326","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A dengue é, hoje, uma das doenças mais frequentes no Brasil, atingindo a população\nem todos os estados da União, independente da\nclasse social. Sobre essa doença, considere as\nassertivas a seguir e assinale a CORRETA.","options":{"A":"Um caso confirmado de dengue clássica é um caso suspeito confirmado laboratorialmente:\nporém, no curso de uma epidemia, a confirmação\npode ser feita pelos critérios\nclinicoepidemiológicos, exceto nos primeiros casos da área que deverão ter confirmação\nlaboratorial.","B":"A transmissão se dá através da picada do mosquito que adquiriu o vírus e pelo contato de um\ndoente ou suas secreções com uma pessoa sadia.","C":"Todo paciente que apresenta doença febril aguda com duração máxima de dez dias,\nacompanhada de, pelo menos, dois dos seguintes\nsintomas: cefaleia, dor retro-orbitária, mialgia,\nartralgia, prostação e exantema, é considerado caso suspeito da doença.","D":"As formas graves sobrevêm, geralmente, após o quinto ou sexto dia de doença, quando a febre\ncomeça a ceder e o exantema, quando presente, é maculopapular, nunca pruriginoso, o que facilita\no diagnóstico diferencial com outras doenças exantemáticas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-79560","number":"79560","sourceNumber":"79560","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A febre é fenômeno observado quando ocorre elevação do ponto de termorregulação\ndo centro termorregulador desencadeando um\nconjunto de mecanismos que visam elevar a\ntemperatura corpórea. Com relação à febre na infância podemos afirmar que, exceto:","options":{"A":"A utilização de meios físicos, como banhos mornos e compressas frias têm indicação precisa\nnos casos de febre","B":"Não está indicada a utilização da combinação de 2 antitérmicos intercalados para melhor efeito\nterapêutico","C":"A febre acelera a atividade enzimática, produzindo um aumento da atividade metabólica de\ntodas as células do organismo e induzindo maior atividade celular","D":"Na febre ocorre uma aceleração da migração dos leucócitos para os tecidos onde estiver\nocorrendo um processo inflamatório","E":"Não existem evidências clínicas de que a magnitude da temperatura alcançada nos quadros\nfebris tenha qualquer valor prognóstico\n(gravidade) ou diagnóstico (viral ou bacteriano) nos quadros\ninfecciosos"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-85813","number":"85813","sourceNumber":"85813","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O vírus da dengue é um RNA-vírus que pode afetar diferentes tipos de células\nhumanas e não humanas. Sua ligação com com\ncélulas é mediada pela glicoproteína E do\nenvelope viral, sendo que esta é crítica para infectividade. O vírus entra no hospedeiro após a\npicada do inseto e circula até atingir células-alvo, onde irá replicar principalmente no sistema\nlinfático. Sobre o manejo da dengue é correto afirmar que:","options":{"A":"a prova do laço é um exame específico que confirma dengue hemorrágica.","B":"raramente cursa com leucopenia e plaquetopenia.","C":"a hemoconcentração é comum mesmo com hidratação adequada","D":"a sorologia especifica (lgM) deve ser solicitada a partir do 3º (terceiro) dia de sintomas","E":"a pesquisa do antígeno NS-1 pode ser feita até o 4º (quarto) dia dos sintomas"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-69201","number":"69201","sourceNumber":"69201","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma paciente, com 25 anos de idade, há três dias apresenta febre, cefaleia intensa\nretro-orbital, mialgia e exantema cutâneo\nmorbiliforme. Há oito dias retornou de Fortaleza e há um\ndia começou a apresentar petéquias, epistaxe e teste do torniquete positivo. Sua pressão arterial é\nde 120/70 mmHg e sua pulsação, de 80 bpm, a temperatura é de 36,7º C. Os exames laboratoriais\nmostraram plaquetas de 80.000, leucopenia, tempos de protrombina e tromboplastina parcial\nnormais e sorologia para dengue (IgM) positiva. Esse quadro caracteriza diagnóstico de:","options":{"A":"Dengue hemorrágica.","B":"Síndrome de choque da dengue.","C":"Dengue hemorrágica com CIVD.","D":"Dengue clássica.","E":"Dengue com comprometimento neurológico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-61775","number":"61775","sourceNumber":"61775","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança 4 anos, 17 kg, com história de febre há 3 dias, cefaleia, dor retro-orbitária,\nexantema, mialgia e artralgia. Procedência -\nMunicípio de Goiânia, PA= 60/40 mmHg pulsos\nfiliformes e sonolenta. Diante da suspeita de Dengue, responda a questão a seguir: Classifique o\nrisco (estadiamento da doença do Ministério da Saúde) e conduta imediata.","options":{"A":"Grupo A, Hidratação oral.","B":"Grupo B, Hidratação Venosa.","C":"Grupo C, Hidratação oral.","D":"Grupo C, Hidratação Venosa.","E":"Grupo D, Hidratação Venosa."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-61780","number":"61780","sourceNumber":"61780","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança 4 anos, 17 kg, com história de febre há 3 dias, cefaleia, dor retro-orbitária,\nexantema, mialgia e artralgia. Procedência -\nMunicípio de Goiânia, PA = 60/40 mmHg pulsos\nfiliformes e sonolenta. Diante da suspeita de Dengue, responda a questão a seguir: Esta criança\ndeverá ser posteriormente conduzida em qual nível de complexidade de assistência em saúde?","options":{"A":"Unidade de Atenção Primária em Saúde","B":"Unidade de Atenção Secundária em Saúde com suporte para observação","C":"Unidade de Atenção Terciária em Saúde com leitos de internação","D":"Unidades de Atenção Terciária em Saúde com leitos de UTI","E":"Unidade Domiciliar"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-63403","number":"63403","sourceNumber":"63403","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A presença de sinais de alarme, relacionados a seguir, indicam a possibilidade de\ngravidade do quadro clínico e de evolução para dengue hemorrágica e/ou síndrome do choque da\ndengue. São eles, exceto:","options":{"A":"Dor abdominal intensa e contínua.","B":"Hipotensão postural e/ou lipotimia.","C":"Hepatomegalia dolorosa.","D":"Hemorragias importantes (hematêmese e/ou melena).","E":"Dor ocular retro-orbitária."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-62763","number":"62763","sourceNumber":"62763","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com 32 anos, procedente da Nigéria, onde trabalhava na construção civil, HIV\nnegativo. Refere há sete dias um quadro súbito de febre irregular, acompanhada de cefaleia,\ncalafrios e dor no corpo durante os episódios febris. Ao exame físico, estava prostrado, levemente\nictérico e com hepatoesplenomegalia. Na pesquisa direta de parasitos no sangue periférico,\nobservou-se uma estrutura aneliforme com dupla cromatina no interior da hemácia (seta) e\nestruturas maiores em forma de banana. (VER IMAGEM) Considerando-se os achados clínicos e\nlaboratoriais, o diagnóstico é:","options":{"A":"Amebíase.","B":"Babesiose.","C":"Balantidíase.","D":"Malária."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/62763.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-61785","number":"61785","sourceNumber":"61785","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em um paciente com confirmação de um quadro de dengue clássica, a presença de\nsinais de alarme, indicam a possibilidade de gravidade do quadro clínico e de evolução para\ndengue hemorrágica e/ou síndrome do choque da dengue. Qual relato caracteriza um sinal de\nalarme da dengue?","options":{"A":"Hipertermia.","B":"Aumento da diurese.","C":"Insônia.","D":"Redução súbita do hematócrito.","E":"Lipotimia."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-49025","number":"49025","sourceNumber":"49025","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Leishmaniose deixa Goiânia em alerta. Secretaria Municipal de Saúde investiga o\navanço da doença. ?Os moradores de Goiânia,\nprincipalmente da região leste, estão preocupados\nquanto ao perigo de contaminação da leishmaniose. Somente durante o mês de julho foram\ndetectados 13 cães contaminados com a doença.\" (www.g1.globo.com 28/07/2011). É parte do\ncontrole da doença para evitar infecção em humanos:","options":{"A":"Identificação de cães doentes/infectados, tratá-los e só depois de curados retorná-los ao\nconvívio.","B":"Identificação de cães doentes/infectados, sacrificá-los e cães que não foram infectados, usar\ncoleira especial repelente.","C":"Vacinação para cães sadios e tratamento dos cães doentes.","D":"Vacinação de bloqueio em áreas de risco para todos os cães.","E":"Vacinar pessoas que têm contato direto com cães."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-49031","number":"49031","sourceNumber":"49031","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Cláudia é professora e está com muita febre há três dias. Procura então Unidade\nBásica de Saúde. Ao ser atendida, ela referiu\nao médico, além de febre, dor intensa no corpo,\nnáuseas, prostração e cefaleia retro-orbital. Feito exame físico seguido de prova do laço, ela se\nrevelou positiva. Diante desse quadro sugestivo de dengue, o médico resolveu fazer isolamento\nviral para confirmação e possível classificação como febre hemorrágica da dengue. O melhor\nmomento para fazê-lo seria:","options":{"A":"Imediatamente, pois está em momento virêmico.","B":"Três dias depois, porque a recomendação é após o quinto dia, quando o vírus se torna evidente.","C":"Como o período de incubação é de 3 a 15 dias, já seria necessário fazer sorologia, pois o\nisolamento não daria positivo.","D":"A partir do sétimo dia.","E":"Após melhora do quadro."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-53637","number":"53637","sourceNumber":"53637","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Pedro tem oito anos de idade e quando retornava da escola pra casa, pisou\nacidentalmente num prego, tendo o mesmo perfurado seu tênis e seu pé. As vacinas de Pedro\nestão atualizadas. Como há possibilidade de infecção local, qual o agente etiológico que mais\npreocupa nesta situação?","options":{"A":"Staphylococcus aureus.","B":"Pseudomonasaeruginosa.","C":"Hemophilisinfluenzae.","D":"Clostridium tetani.","E":"Neisseriameningitidis."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-47705","number":"47705","sourceNumber":"47705","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma criança de 10 anos, procedente da zona rural de Niquelândia (GO) é encaminhada\nao hospital regional com quadro de febre diária\nhá oito semanas, emagrecimento e aumento do\nvolume abdominal. Ao exame físico, apresentava-se com mucosas hipocoradas, anictérica,\nlinfonodos cervicais palpáveis bilateralmente com 0,5 a 1,0 cm de diâmetro, móveis, indolores, de\nconsistência habitual, fígado a 2 cm do rebordo costal direito e baço a 4 cm do rebordo costal\nesquerdo. Laboratorialmente, foram evidenciados Hb = 10 g/dl; Leucócitos totais = 2.900/mm³ com\ncontagem diferencial normal; Plaquetas = 110.000/mm³; TGO = 58 U/L e TGP = 65 U/L; Albumina =\n2,8 g/dl e Globulinas = 4,0 g/dl. O diagnóstico e o exame de escolha para sua confirmação são:","options":{"A":"Toxoplasmose linfonodal aguda e sorologia;","B":"Leishmaniose visceral e mielograma;","C":"Tuberculose ganglionar e biópsia de linfonodo;","D":"Malária e pesquisa de hematozoários."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-35629","number":"35629","sourceNumber":"35629","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Jovem de 26 anos, hígida previamente, 1 semana após atravessar enxurrada, passou a\napresentar febre, cefaleia holocraniana importante, dor em panturrilhas, tosse e expectoração clara\ncom laivos de sangue. Ao exame físico, apresenta discreta crepitação em terço médio de ambos os\nhemitóraces, com o restante do exame normal. A principal suspeita diagnóstica considerando os\nantecedentes é:","options":{"A":"Pneumonia bacteriana.","B":"Tromboembolismo pulmonar.","C":"Edema agudo de pulmão.","D":"Vasculite pulmonar por autoanticorpos.","E":"Vasculite pulmonar secundária à infecção sistêmica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-35691","number":"35691","sourceNumber":"35691","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Mulher de 22 anos de idade, gestante de 7 meses, procedente de Imperatriz do\nMaranhão, há 10 dias sem intercorrências nos\núltimos meses. Apresentou febre alta (até 39,8°C) e\ncefaleia holocraniana há 5 dias, falta de ar e ?barriga dura? há 2 dias. Foi ao Centro de\nReferência,\ntendo sido realizado o diagnóstico de malária ao exame de ?gota espessa?. Nega quadro\nsemelhante anteriormente. Podemos afirmar com relação ao caso acima:","options":{"A":"Se a espécie isolada for P. vivax, o tratamento indicado é a associação de cloroquina com\nprimaquina.","B":"A erradicação das formas parasitárias é mais difícil nesta paciente pelo fato de ser gestante.","C":"Se a espécie isolada for P. falciparum, o paciente pode ser tratado com mefloquina, devendo\nretornar no máximo em 1 semana para avaliação\nda resposta terapêutica.","D":"A dispneia apresentada provavelmente é devido à hipertermia, já que não se observa\nenvolvimento pulmonar.","E":"A indicação de hospitalização se fará se a parasitemia por P. falciparum for maior que 2%."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-27185","number":"27185","sourceNumber":"27185","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente de 40 anos, masculino, proveniente do Pará, área de desmatamento e com\nqueixa de ferida no antebraço direito há 3 meses. Ao exame físico mostra lesão úlcerocrostosa,\ncom bordos elevados, em moldura, com 4,0 cm de diâmetro e fundo granuloso. Foi feita hipótese\ndiagnóstica de Leishmaniose Tegumentar Americana. Marque a alternativa mais correta para o\ncaso.","options":{"A":"O agente etiológico mais comum da doença é a Leishamânia donovania, fungo dimorfo e\nPAS-positivos.","B":"No exame histopatológico de fragmento da pele serão observados granulomas de células\nepitelióides com necrose \"caseosa\" na área central e BAAR corados em vermelho pelo\n\nZiehl-Neelsen.","C":"A disseminação dos microorganismos causadores da lesão faz principalmente pela via\nhematogênica, comprometendo com muita frequência pulmões e medula óssea.","D":"Até três meses de evolução os microorganismos podem ser encontrados em raspados da lesão\ncorados pelo Giemsa ou nos exames histopatológicos, até mesmo na coloração clássica,\nHematoxilina-Eosina (HE).","E":"A história clínica e epidemiológica, com teste de intradermorreação positivo são suficientes para\nfirmar o diagnóstico de certeza e autoriza o início do tratamento específico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-8937","number":"8937","sourceNumber":"8937","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Avalie a tabela abaixo e responda: (VER IMAGEM)\nSobre a Dengue em Goiás, é incorreto afirmar:","options":{"A":"Um aumento nas notificações de Dengue ao longo dos últimos anos reflete uma maior\nsensibilidade do sistema de vigilância epidemiológica da doença, mas não é indicativo de uma\nmudança no perfil epidemiológico da doença.","B":"Observa-se uma tendência de aumento dos óbitos por FHD. Os fatores de risco relacionados\ncom a Febre Hemorrágica do Dengue referem-se à\ncepa viral, idade do indivíduo, anticorpo\n\nanti-dengue pré existente, imunidade. Genética do hospedeiro e local com transmissão simultânea\nde mais de um sorotipo.","C":"Em Goiás, a circulação sequencial de mais de um sorotipo proporcionou um aumento da\nincidência da Febre Hemorrágica do Dengue e um incremento na mortalidade causada pela\nmesma.","D":"Com relação ao controle da doença, as campanhas desenvolvidas em Goiás priorizam as\nmudanças de hábito, decorrentes da maior\nconscientização e mobilização social sobre a\nnecessidade das comunidades manterem seus ambientes livres do mosquito transmissor da\nDengue."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-9287","number":"9287","sourceNumber":"9287","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Quanto à febre amarela, os estudos apontam que:","options":{"A":"a forma urbana é endêmica na região Centro-Oeste, e a vacinação é indicada para pessoas que\nvivem ou viajam para essa região.","B":"o comprometimento visceral ocorre em aproximadamente 15% dos casos, e a letalidade varia de\n20 a 50%.","C":"a vacina disponível é de vírus inativado, tem alta eficácia e raramente está associada a efeito\nneurológico adverso.","D":"os mosquitos dos gêneros Haemagogus e Aedes são os principais reservatórios do vírus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-273951","number":"273951","sourceNumber":"273951","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à tuberculose, a Organização Mundial da Saúde - OMS, nos seus objetivos\ndo desenvolvimento sustentável, propõe, além da\nvacinação BCG, outras medidas programáticas\npara um maior controle da doença. Assinale a ação programática que é empregada com o intuito\nde fortalecer os indicadores de saúde:","options":{"A":"Tratamento de reatores ao teste tubérculo.","B":"Confirmar cura dos casos.","C":"Tratamento de infecções latentes para todos os Contatos.","D":"Tratamento de sintomáticos respiratórios."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-250265","number":"250265","sourceNumber":"250265","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Casal que está em tratamento para tuberculose pulmonar há 30 dias leva ao posto de\nsaúde seu filho de cinco anos para\ninvestigação. O menino tem a marca vacinal da BCG, está\nassintomático, sua radiografia de tórax apresenta resultado normal e teste tuberculínico de 12mm.\nBaseando-se no Manual de Recomendações para o Controle da Tuberculose no Brasil, do\nMinistério da Saúde, em relação ao menino, deve-se:","options":{"A":"Considerar infecção latente por tuberculose e fazer isoniazida durante seis meses.","B":"Considerar tuberculose ativa e fazer esquema tríplice durante seis meses.","C":"Considerar vacinado e repetir prova tuberculinica em oito semanas.","D":"Considerar não infectado e observar clinicamente e revê-lo em oito semanas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-216208","number":"216208","sourceNumber":"216208","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Esposa de paciente recentemente diagnosticado com tuberculose pulmonar procurou a\nUnidade Básica de Saúde para avaliação médica. Encontrava-se assintomática. Realizou PPD,\ncom induração = 7 mm, e radiografia de tórax normal. A melhor conduta para esse contato é:","options":{"A":"Isoniazida por 3 meses.","B":"Isoniazida por 6 meses.","C":"Repetir prova tuberculínica entre 5 e 8 semanas.","D":"Orientar retorno em caso de sintomas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-176250","number":"176250","sourceNumber":"176250","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com 5 anos de idade, proveniente da zona rural do Estado do Maranhão,\napresenta adenomegalia generalizada,\nemagrecimento, febre intermitente e eosinofilia acentuada\ndetectada em sangue periférico. A hipótese MAIS PROVÁVEL é:","options":{"A":"Doença da arranhadura do gato","B":"Sindrome de Löeffler","C":"Tuberculose","D":"Linfoma de Hodgkin","E":"Paracoccidioidomicose"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-176270","number":"176270","sourceNumber":"176270","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com 2 anos de idade, história de contato domiciliar com avó com diagnóstico\nrecente de tuberculose pulmonar, foi\nsubmetido à investigação de contactante com exame clínico\nde aparelho respiratório normal, radiografia de tórax com laudo normal e PPD reator de 6mm\n(reator fraco). Nunca foi vacinado com BCG. A conduta MAIS CORRETA:","options":{"A":"Iniciar esquema de isoniazida.","B":"Iniciar esquema tríplice específico para tuberculose.","C":"Repetir PPD após 15 dias.","D":"Solicitar lavado gástrico para baciloscopia.","E":"Observação clínica ambulatorial e indicar a BCG."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-131882","number":"131882","sourceNumber":"131882","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança de 5 anos, evoluindo com hepatoesplenomegalia, palidez e desnutrição\nimportantes, febre prolongada e geralmente baixa. Hemograma com pancitopenia. Qual o\ndiagnóstico mais provável?","options":{"A":"Leucemia.","B":"Malária.","C":"Leishmaniose visceral.","D":"Doença de Chagas.","E":"Endocardite."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-105675","number":"105675","sourceNumber":"105675","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Qual é o agente etiológico do Calazar (leishmaniose visceral)?","options":{"A":"Leishmania braziliensis.","B":"Leishmania guyanensis.","C":"Leishmania donovani.","D":"Leishmania amazonensis.","E":"Leishmania lainsoni."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-80920","number":"80920","sourceNumber":"80920","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O agente etiológico da doença de Chagas é:","options":{"A":"Plasmodium vivax.","B":"Schistosoma mansoni.","C":"Treponema pallidum.","D":"Trypanosoma cruzi.","E":"Echinococcus granulosus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-80863","number":"80863","sourceNumber":"80863","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação à malária causada pelo P. falciparum, é correto afirmar, EXCETO:","options":{"A":"Está indicado o tratamento com cloroquina.","B":"Paciente pode apresentar anemia hemolítica grave.","C":"É comum o comprometimento renal e consequente insuficiência renal aguda.","D":"O comprometimento do sistema nervoso central, também chamado de malária cerebral, pode se\napresentar com crises convulsivas e coma.","E":"Plaquetopenia menor que 50.000/mm³ constitui critério de gravidade."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-84891","number":"84891","sourceNumber":"84891","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Suspeita-se de DENGUE na presença dos seguintes sintomas e sinais, EXCETO:","options":{"A":"Febre com duração de até 07 dias, mialgia, cefaleia e prostração.","B":"Febre de 03 dias de evolução, artralgia, dor retro-orbitária e petéquias.","C":"Febre com duração de pelo menos 10 dias, hepatoesplenomegalia, linfadenomegalia e epistaxe.","D":"Febre com duração de 02 dias de evolução, cefaleia, exantema maculopapular e petéquias.","E":"Febre com duração de 05 dias, mialgia e petéquias generalizadas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-62602","number":"62602","sourceNumber":"62602","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Constituem sinais de alarme da dengue os seguintes achados, exceto:","options":{"A":"2 episódios de vômitos em 12 horas;","B":"Lipotimia;","C":"Diminuição da diurese;","D":"Desconforto respiratório;","E":"Hematêmese."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-62649","number":"62649","sourceNumber":"62649","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Dengue em uma criança tem um amplo espectro clínico, podendo manifestar variados\nsinais e sintomas, além de ser uma doença dinâmica, podendo expressar, em determinado\nmomento, sinais de gravidade e choque. Devido a essas características, pode-se destacar seu\ndiagnóstico diferencial em síndromes clínicas, EXCETO:","options":{"A":"Síndrome nefrótica: Cirrose hepática, Desnutrição proteica (kwashiorkor), Enteropatia perdedora\nde proteínas (linfangiectasia intestinal);","B":"Síndrome febril: enteroviroses, influenza e outras viroses respiratórias, hepatites virais,\nmalária,\nfebre tifoide e outras arboviroses;","C":"Síndrome exantemática febril: diagnóstico diferencial com rubéola, sarampo, escarlatina, eritema\ninfeccioso, exantema súbito, enteroviroses, mononucleose infecciosa, parvovirose,\ncitomegalovirose, outras arboviroses (Mayaro), farmacodemias, doença de Kawasaki;","D":"Síndrome hemorrágica febril: hantavirose, febre amarela, leptospirose, malária grave,\nriquetsioses e púrpuras;","E":"Síndrome dolorosa abdominal: apendicite, obstrução intestinal, abcesso hepático, abdome\nagudo, pneumonia, infecção urinária."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-47489","number":"47489","sourceNumber":"47489","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com dengue tem quadro de febre alta, cefaleia holocraniana e dor retrorbital,\nalém de mialgia generalizada. Entre os achados\ndo exame físico que traduzem gravidade estão:","options":{"A":"Hepatomegalia e exantema maculopapular","B":"Derrames cavitários e hipotensão","C":"Adenomegalia e mialgias generalizadas","D":"Esplenomegalia e cianose","E":"Petéquias e artrite"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-35765","number":"35765","sourceNumber":"35765","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à dengue, é VERDADE que:","options":{"A":"É, hoje, a principal doença emergente do mundo.","B":"Existe tratamento etiológico e quimioprofilático efetivos.","C":"É possível evitar casos de dengue em áreas infestadas pelo Aedes aegypti.","D":"É possível prevenir epidemias de grandes dimensões por meio do aprimoramento da vigilância\nepidemiológica.","E":"Não é possível reduzir a letalidade da doença, que se situa em torno de 5 a 6% para as formas\ngraves."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-35699","number":"35699","sourceNumber":"35699","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente natural de São Luís, há 4 meses com quadro de febre, pancitopenia,\nanasarca, icterícia e hepatoesplenomegalia.\nDurante investigação diagnóstica colheu mielograma\nque confirmou o diagnóstico de leishmaniose visceral. Qual a melhor conduta terapêutica?","options":{"A":"Colher culturas para direcionar antibioticoterapia.","B":"Realizar esplenectomia.","C":"Iniciar o antimoniato de N-metilglucamina.","D":"Iniciar a anfotericina B.","E":"Prescrever primaquina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-35782","number":"35782","sourceNumber":"35782","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança deu entrada com febre de duração há seis dias com cefaleia retro-orbitária, dor\nabdominal, mialgia. Você suspeita de dengue e além de solicitar hemograma completo, para fazer o\ndiagnóstico solicitaria:","options":{"A":"Sorologia para Dengue.","B":"Isolamento viral.","C":"VHS e hemocultura.","D":"Urina tipo I e isolamento viral.","E":"PCR + VHS."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-35783","number":"35783","sourceNumber":"35783","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Das drogas abaixo todas são recomendadas usar no dengue. EXCETO:","options":{"A":"Paracetamol ? novalgina.","B":"Dexclorfeniramina + dipirona.","C":"Anti-histamínico + tylenol.","D":"AAS ? ibuprofeno.","E":"Paracetamol + dexclorfeniramina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-28264","number":"28264","sourceNumber":"28264","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na definição de caso suspeito de Dengue é INCORRETO afirmar:","options":{"A":"Na definição de dengue clássica, a febre deve ter duração máxima de 7 dias e ser acompanhada\nde pelo menos dois sintomas dentre os quais\ncitamos a cefaleia e artralgia.","B":"A mialgia e a dor retro-orbital também são sintomas que compõem o quadro de caso suspeito de\ndengue, em presença de febre de até 7 dias.","C":"A febre hemorrágica do dengue inclui todos os casos suspeitos de dengue clássico que\napresentem também manifestações hemorrágicas.","D":"A síndrome de choque por dengue faz parte da definição de caso suspeito de febre hemorrágica\ndo dengue.","E":"Existem três manifestações distintas de dengue que são de notificação compulsória: dengue\nclássico, febre hemorrágica por dengue e dengue em idosos com mais de 65 anos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-28273","number":"28273","sourceNumber":"28273","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A dengue constitui um desafio para a saúde pública mundial. O Brasil vem\napresentando, nos últimos anos, número\ncrescente de casos graves em adultos e, especialmente\nem menores de 15 anos. Acerca deste grave problema de saúde pública assinale a alternativa\nINCORRETA:","options":{"A":"Os quatro sorotipos do vírus dengue (DENV-1, DENV-2, DENV-3, DENV-4) pertencem à família\nflaviviridae e ao gênero Flavivirus, que reúne 53 espécies de vírus","B":"Se o choque por dengue for tratado precoce e adequadamente, com soluções cristaloides em\nvolume de 60 ml a 80 ml/kg/dia estaremos evitando a evolução desfavorável","C":"É sabido que, na dengue, são produzidos anticorpos antiplaquetários, de modo que as plaquetas\ntransfundidas serão destruídas. Entretanto, quando há menos de 50.000 plaquetas/mm³ de sangue\ne a presença de sangramento, a transfusão de plaquetas é indicada","D":"A primoinfecção por dengue será sempre benigna e em virtude da chamada \"infecção\nsequencial\", qualquer infecção secundária evoluirá com gravidade","E":"A elevação das transaminases tem sido observada em até 90% dos casos de dengue, sendo os\nníveis de aspartato aminotransferase (AST/TGO) geralmente mais altos do que os de alanina\naminotransferase (ALT/TGP)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-28276","number":"28276","sourceNumber":"28276","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Analise as afirmações abaixo acerca da influenza humana: I - Os vírus influenza são\nvírus RNA da família Orthomyxoviridae,\nenvelopados, altamente transmissíveis e mutáveis; II - Das\ncomplicações da influenza, a pneumonia é a mais comum, podendo ser primária, resultante do\nenvolvimento pulmonar diretamente pelo vírus influenza, ou secundária, causada por Streptococcus\npneumoniae, Staphylococcus aureus ou Haemophilus influenzae; III - Dos inibidores da\nneuraminidase (oseltamivir e zanamivir), o zanamivir (inalatório) é o mais indicado em pacientes\ncom asma ou DPOC; Estão corretos os itens:","options":{"A":"I, II, III","B":"I e II, apenas","C":"I e III, apenas","D":"II e III, apenas","E":"III apenas"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-308631","number":"308631","sourceNumber":"308631","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O tratamento da tuberculose drogarresistente (TB DR) é um dos maiores desafios para\no controle da doença no mundo. Variados\npadrões de resistência exigem diferentes abordagens\npara seu tratamento. Como se pode classificar um indivíduo com tuberculose que apresenta\nresistência a dois ou mais fármacos antituberculose, exceto à associação rifampicina e isoniazida?","options":{"A":"Polirresistência","B":"Monorresistência","C":"Multirresistência","D":"Resistência extensiva","E":"Resistência à rifampicina"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-302086","number":"302086","sourceNumber":"302086","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Hospital especializado em oncologia passa por um surto de casos de Aspergillus\ninvasivo em pacientes internados no setor de\ntransplante de medula óssea. Qual das alternativas\nabaixo aponta corretamente a fonte mais provável de infecção por Aspergillus?","options":{"A":"disseminação de profissional da saúde para paciente, devido ao uso inadequado de desinfetante\ncontendo álcool","B":"fonte de água contaminada","C":"disseminação de interpacientes em salas de espera de consultórios","D":"disseminação de profissional da saúde para paciente, devido a técnica inadequada de lavagem\nde mãos","E":"fonte de ar contaminado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-263705","number":"263705","sourceNumber":"263705","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No início da década de 1980, houve recrudescimento global da tuberculose: nos países\nde alta renda, esse recrudescimento se\ndeveu principalmente à emergência da infecção pelo Vírus\nda Imunodeficiência Humana (HIV) e, nos países de baixa renda, devido à ampliação da miséria e\ndo processo de urbanização descontrolada, além de desestruturação dos serviços de saúde e dos\nprogramas de controle da tuberculose. Alguns conceitos sofreram modificações durante esse\nperíodo, dentre os quais está: sintomático respiratório, que hoje é considerado:","options":{"A":"Pessoa que, durante a estratégia programática de busca ativa, apresenta tosse por 3 semanas\nou mais, devendo ser levado em consideração\npopulações especiais onde o tempo de sintomas é\nmenor.","B":"Pessoa que, durante a estratégia programática de busca ativa, apresenta tosse por 3 semanas\nou mais, independente do tipo de população\ninvestigada.","C":"Pessoa que, durante a estratégia programática de busca passiva apresenta tosse por 2\nsemanas ou mais, não deve ser levado em\nconsideração populações especiais onde o tempo de\nsintomas é menor.","D":"Pessoa que, durante a estratégia programática de busca passiva, apresenta tosse por 3\nsemanas ou mais, devendo ser levado em\nconsideração populações especiais onde o tempo de\nsintomas é maior.","E":"Pessoa que, durante a estratégia programática de busca ativa, apresenta tosse por 4 semanas\nou mais, devendo ser levado em consideração\npopulações especiais onde o tempo de sintomas é\nmenor."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-263766","number":"263766","sourceNumber":"263766","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação ao diagnóstico e conduta da tuberculose, assinale a alternativa CORRETA:","options":{"A":"A técnica-padrão para realização da cultura para M. tuberculosis é o meio de lowenstein-jensen.\n\nEssa é padrão-ouro para o diagnóstico de tuberculose com tempo de obtenção do resultado de 3-4\ndias.","B":"Em pacientes pediátricos, há dificuldade de confirmação bacteriológica da tuberculose, pois a\nforma pulmonar nessa faixa etária é paucibacilar.","C":"O teste tuberculínico com PPD, realizado pela técnica de Mantoux na região de extensão do\nbraço direito, com leitura após 48-72 horas, não é valorizado em pacientes vacinados com BCG.","D":"As dificuldades diagnósticas da tuberculose em pacientes menores de 15 anos propiciaram o\ndesenvolvimento do sistema de pontos adotados pelo Ministério da Saúde, e quando a pontuação é\nigual a 25 está indicado tratamento medicamentoso imediato.","E":"A prevenção em larga escala se baseia na estratégia de vacinação com BCG, que evita o\nadoecimento."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-252401","number":"252401","sourceNumber":"252401","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente masculino, 59 anos, dá entrada na emergência com hemorragia alveolar\ndifusa. Assinale o achado esperado no lavado broncoalveolar desse paciente.","options":{"A":"Corpos ferruginosos","B":"Macrófagos com hemossiderina","C":"Macrófagos espumosos","D":"Pneumócitos do tipo II, atípicos","E":"Linfocitose com razão CD4-CD8 aumentada"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-252411","number":"252411","sourceNumber":"252411","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No tratamento da tuberculose, devido ao uso da isoniazida, recomenda-se reposição\nde:","options":{"A":"Ácido fólico.","B":"Vitamina B1.","C":"Vitamina B6.","D":"Sulfato ferroso.","E":"Vitamina D."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-252452","number":"252452","sourceNumber":"252452","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre tuberculose na pediatria, selecione a opção que corresponde à forma clínica\nextrapulmonar mais comum.","options":{"A":"Ganglionar.","B":"Meníngea.","C":"Óssea.","D":"Renal.","E":"Miliar."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-203217","number":"203217","sourceNumber":"203217","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Mulher, 50 anos, com diagnóstico de linfoma não Hodgkin dá entrada no pronto-socorro\ncom quadro febril, tosse e neutropenia\nprolongada. Na tomografia de tórax, evidenciam-se nódulos\npulmonares bilaterais com o sinal de halo. Um teste de soro galactomanano resulta positivo.\n\nAssinale o agente causativo mais provável do quadro acima.","options":{"A":"S. aureus.","B":"Pneumocystis jiroveci.","C":"Espécies de Aspergillus","D":"Zigomicetos.","E":"E. coli."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-203318","number":"203318","sourceNumber":"203318","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Menor de três meses de idade com mãe no 5° mês de tratamento para tuberculose\npulmonar. A criança está realizando\nquimioprofilaxia com isoniazida e não foi vacinada com a BCG\naté o momento. A criança realizou teste de mantoux com 3 meses de idade, que resultou 8\nmilímetros. Tendo em conta as recomendações do Ministério da Saúde, qual medida deve ser\nadotada?","options":{"A":"Manutenção do tratamento com isoniazida por 6 meses e vacinar com BCG posteriormente.","B":"Orientar vacinação com BCG imediata e suspender quimioprofilaxia.","C":"Orientar Vacinação com BCG imediata e manutenção do tratamento com isoniazida por 6\nmeses.","D":"Iniciar tratamento para tuberculose pulmonar e vacinar com BCG posteriormente.","E":"Não vacinar, supender quimioprofilaxia e observar."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-175009","number":"175009","sourceNumber":"175009","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com 18 anos de idade procurou pronto-socorro com história de pele\namarelada, vômitos e fraqueza. Refere estar em\ntratamento há 10 dias, na Unidade Básica de\nSaúde ? UBS, por tuberculose pulmonar bacilífera. Ao exame físico: PA = 90 X 60 mmHg e FC =\n130 bpm. O médico plantonista indicou internação. Com relação às normas de biossegurança, qual\na melhor conduta?","options":{"A":"Paciente em quarto com isolamento usando máscara cirúrgica.","B":"Paciente em quarto comum e profissionais de saúde usando máscara respiratória (N95).","C":"Não há necessidade de isolamento desse paciente por já ter iniciado o tratamento.","D":"Paciente em quarto com isolamento usando máscara respiratória (N95).","E":"Paciente em quarto com isolamento e os profissionais da saúde usando máscara respiratória\n(N95)."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-184854","number":"184854","sourceNumber":"184854","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O teste de Interferon -Gama(Interferon-gama Release Assay - IGRAS) no Brasil\nregistrado como Quantiferon-TB Glodin (QTF),que\nserve para avaliar a resposta imune celular por\nmeio da dosagem do gama Interferon liberado pelos linfócitos T ativados em presença do bacilo da\ntuberculose com relação ao emprego do Quantiferon (QTF) na investigação da tuberculose é\nINCORRETO afirmar que:","options":{"A":"O QTF serve para diferenciar indivíduos com tuberculose latente dos indivíduos com tuberculose\ndoença.","B":"O QTF detecta o gama interferon (IFN-y) liberado pelas células T a partir da estimulação por\nantígenos específicos do M. Tuberculosis.","C":"O QTF tem especificidade superior a 95% no diagnóstico de Tuberculose latente.","D":"O QTF não sofre interferência nos resultados em pessoas vacinadas pelo BCG.","E":"Essa técnica tem especial utilidade em indivíduos que apresentam algum tipo de\ncomprometimento imunológico."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177457","number":"177457","sourceNumber":"177457","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Portador de tuberculose pulmonar, com boa resposta inicial ao tratamento com o\nesquema I, começa a apresentar parestesias\nem queimação em extremidades. Qual a conduta\nrecomendada nesta situação?","options":{"A":"Suspender etambutol.","B":"Prescrever piridoxina.","C":"Suspender isoniazida.","D":"Suspender pirazinamida.","E":"Prescrever vitamina B12."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-160385","number":"160385","sourceNumber":"160385","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No tratamento medicamentoso da tuberculose, a estratégica de tomada com\nobservação direta (estratégia DOT), que tem por\nobjetivo a verificação da adesão ao tratamento,\nestá indicada na seguinte situação:","options":{"A":"Apenas na tuberculose pulmonar.","B":"Apenas na meningoencefalite tuberculosa.","C":"Em todos os casos de tuberculose.","D":"Apenas na tuberculose drogarresistente.","E":"Apenas na tuberculose ganglionar."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-160414","number":"160414","sourceNumber":"160414","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Menino de 4 anos é atendido na unidade de saúde. Assintomático, possui cicatriz\nvacinal (BCG) na inserção do músculo deltoide\ndireito. Radiografia de tórax normal e teste\ntuberculínico (PT) de 5 mm. Sua mãe é cuidadora e está fazendo tratamento para tuberculose\npulmonar diagnosticada há cerca de 2 meses. Baseando-se no Manual de Recomendações para o\nControle da Tuberculose no Brasil, do Ministério da Saúde, em relação à criança, a melhor conduta\né:","options":{"A":"Tratá-la com isoniazida por um período mínimo de 6 meses.","B":"Repetir prova tuberculínica (PT) em 8 semanas. Se o resultado da PT for > 5 mm, a\nquimioprofilaxia deve ser feita por 3 meses, caso contrário interrompe-se o uso da isoniazida.","C":"Observar clinicamente e revê-la em 8 semanas.","D":"Tratá-la com o esquema tríplice considerando a provável infecção latente pelo Mycobacterium\ntuberculosis (ILTB).","E":"Tratá-la com isoniazida + rifampicina por um período mínimo de 6 meses."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-140029","number":"140029","sourceNumber":"140029","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A Febre de Origem Obscura (FOO) clássica é definida como permanência de febre,\napós 3 dias de Investigação hospitalar ou\ntrês consultas ambulatoriais com investigação criteriosa e\ninvasiva sem elucidação de uma causa. Sobre esta condição podemos afirmar:","options":{"A":"Com o aperfeiçoamento das tecnologias diagnósticas - em particular a tomografia de alta\nresolução, a RM, a PET e os ensaios\nantígenos tumorais- os estudos recentes mostram que menos\nde 5% dos casos de FOO permaneceram sem diagnóstico.","B":"As infecções, como a tuberculose extrapulmonar e - em áreas endêmicas - a febre tifoide e a\nmalária, são causas raras de FOO passível de diagnóstico.","C":"No indivíduo jovem, uma doença multissistêmica é a causa mais frequente de FOO, é arterite de\ncélulas gigantes.","D":"Deve-se considerar a possibilidade de uma etiologia relacionada com fármacos em todos os\ncasos de febre prolongada. Qualquer padrão\nfebril pode ser provocado por um fármaco, porém é\nraro ocorrer com antibióticos beta-lactâmicos e fenitoína.","E":"O teste cutâneo com tuberculina (TCT)/PPD pode produzir resultados negativos na tuberculose\nmiliar, na sarcoidose, na doença de Hodgkin, na\ndesnutrição ou na Aids."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-132781","number":"132781","sourceNumber":"132781","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre as infecções fúngicas é correto afirmar, EXCETO:","options":{"A":"A histoplasmose disseminada é observada comumente em pacientes SIDA, especialmente\nquando CD4 < 100. Caracteriza-se por febre,\ndispneia, tosse, hepatoesplenomegalia, podendo até\nlevar a um quadro semelhante ao choque séptico.","B":"São fatores de risco para candidíase invasiva: neutropenia prolongada, antibioticoterapia de\nlargo espectro, presença de cateter vascular, uso de NPT.","C":"A criptococose é a causa mais comum de meningite fúngica, especialmente em pacientes SIDA,\nem usuários de corticoide e em outras\nsituações de imunossupressão. O fluconazol é recomendado\ncomo terapia inicial isolada para tratamento da meningite criptocócica aguda.","D":"O tratamento de escolha para pneumocistose é o sulfametoxazol + trimetoprima, sendo indicado\ntambém o uso de prednisona nos casos mais graves, especialmente de hipoxemia.","E":"Existem diversas apresentações da aspergilose: aspergilose broncopulmonar alérgica,\nacometendo tipicamente pacientes com histórico de\nasma; aspergiloma, colonizando cavidades\npulmonares preexistentes, como aquelas formadas pós-TB; aspergilose invasiva disseminada,\ntípica de pacientes portadores de neoplasias hematológicas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-103922","number":"103922","sourceNumber":"103922","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Analise as seguintes afirmativas sobre a dengue na infância e assinale com V as\nverdadeiras e com F as falsas e, em\nseguida, escolha a opção que contém a sequência corrente. ( )\nCriança proveniente de área endêmica com quadro febril, sem sinais de localização da doença na\nausência de sinais respiratórios, é considerada caso suspeito de dengue. ( ) O início da doença na\ncriança pode passar despercebido e o quadro grave ser identificado como a primeira manifestação\nclínica. ( ) Os sinais de alarme e o agravamento do quadro clínico costumam ocorrer na fase em\nque predomina a febre alta. ( ) A prova do laço deve ser realizada na triagem, obrigatoriamente, em\ntodo paciente com suspeita de dengue e que não apresente sangramento espontâneo. ( ) Todas as\ncrianças classificadas como caso suspeito de dengue devem ser mantidas em observação\nhospitalar, mesmo que não apresentem sinais de alarme, por serem um grupo de risco para\nevolução grave.","options":{"A":"F F V V F","B":"F V F V V","C":"V V F V F","D":"V F V F V","E":"V F V V F"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-89277","number":"89277","sourceNumber":"89277","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem de 35 anos de idade, com história de viagem para o interior há 10 dias\n(ecoturismo), apresenta quadro de cefaleia e\nmialgias importantes há 24h, que o motivaram a\nprocurar o PS. Realizou exames que mostraram hemograma normal e CPK com níveis séricos 3\nvezes aumentados e liquor com pleocitose discreta (60 céls e predomínio de linfomononucleares).\nApós melhora por 2 dias, apresentou piora do quadro clínico, com declínio da função renal\n(creatinina = 3,5 mg/dl e ureia = 80 mg/dl). Os níveis de CPK aumentaram, o paciente passou a\napresentar icterícia com predomínio de bilirrubina direta e aparecimento de sufusões conjuntivais\nhemorrágicas. A principal hipótese, neste caso, é:","options":{"A":"Meningite asséptica.","B":"Leptospirose.","C":"Hepatite viral aguda.","D":"Dengue.","E":"Colangite."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-89581","number":"89581","sourceNumber":"89581","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale o principal componente hemodinâmico encontrado no choque da dengue.","options":{"A":"Manifestações hemorrágicas espontâneas","B":"Aumento da permeabilidade vascular","C":"Resistência vascular sistêmica diminuída","D":"Presença de disfunção miocárdica, com fração de ejeção < 50%","E":"Débito cardíaco aumentado"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-65614","number":"65614","sourceNumber":"65614","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Adolescente do sexo masculino, 18 anos, residente em Pedrinhas, internado com\nquadro de febre, perda de peso, inapetência e\nvômitos, há 1 mês. Ao exame físico: palidez, febre\n(Tax.: 39°C), dor em hipocôndrio D e esplenomegalia 7 cm abaixo do rebordo costal E (confirmada\npor ultrassom). Hemograma: anemia, neutropenia com desvio para esquerda e plaquetopenia.\n\nEletroforese de proteínas: hipoalbuminemia e hipergamaglobulinemia policlonal. Considerando\nLeishmaniose Visceral como diagnóstico presuntivo, é correto afirmar, EXCETO:","options":{"A":"A internação foi bem indicada, sendo necessária, na admissão, a coleta de hemoculturas e início\nde antibiótico empírico para neutropenia\nfebril.","B":"Se não houvesse manifestações clínicas sugestivas de Leishmaniose Visceral, um teste\nsorológico reagente não autorizaria o início do tratamento.","C":"O aspirado de medula óssea, embora menos sensível que a punção de baço, constitui\nprocedimento diagnóstico seguro, permitindo a\nvisualização de formas promastigotas do parasita.","D":"Trata-se de paciente imunodeprimido, sujeito a infecções secundárias, principalmente por\ntuberculose, bactérias capsuladas e bactérias Gram-negativas.","E":"O tratamento de primeira escolha pode levar a efeitos adversos importantes relacionados à\ncardiotoxicidade (alterações do segmento ST e da onda T) e elevação de enzimas hepáticas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-65657","number":"65657","sourceNumber":"65657","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa correta sobre as manifestações clínicas da dengue:","options":{"A":"A dengue na criança, na maioria das vezes, é assintomática;","B":"Em crianças menores de 05 anos, o início da doença pode passar despercebido e o quadro\ngrave ser identificado como a primeira\nmanifestação clínica;","C":"Manifestações clínicas neurológicas são comuns na fase precoce da doença em lactentes;","D":"Os sinais de alerta e o agravamento do quadro não costumam ocorrer na fase de remissão da\nfebre;","E":"Os sintomas clínicos nas crianças menores de 02 anos são predominantemente manifestações\nrespiratórias."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-65650","number":"65650","sourceNumber":"65650","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na dengue grave, é correto afirmar que:","options":{"A":"No final da etapa febril, surgem alguns sinais de gravidade como dor abdominal, vômitos\nfrequentes e hipotermia.","B":"Uso de soluções glicofisiológicas podem ser usadas como expansores de volume.","C":"O choque hipovolêmico é determinado, principalmente, por um quadro de hemorragia grave\nmaciça do trato gastrointestinal, muitas das vezes de difícil tratamento;","D":"Surgem precocemente petéquias disseminadas em pele e prova do laço positiva, que constituem\nsinais de gravidade ou de alerta da\ndoença;","E":"O uso de soluções coloides é preconizado quando existe uma hipoalbuminemia severa, e seu\nuso precoce pode evitar a evolução para óbito."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-327364","number":"327364","sourceNumber":"327364","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"?A infecção latente pelo Mycobacterium tuberculosis ocorre quando uma pessoa se\nencontra infectada por essa bactéria, sem\nmanifestação da doença ativa. Estima-se que um quarto\nda população mundial esteja infectada pelo Mycobacterium tuberculosis.? (Ministério da Saúde,\n2018) Sobre os critérios para tratamento da infecção latente, conforme orientação do Ministério da\nSaúde, considere: I. Recém-nascido que coabita com caso-fonte diagnosticado laboratorialmente.\n\nII. Portador de Diabetes Mellitus com PPD=10mm. III. Paciente em uso de corticóide (Prednisona\n5mg/dia por 6 meses) com PPD de 4mm. Para o\ntratamento da infecção latente, estão corretos os\ncritérios","options":{"A":"I e III, apenas.","B":"II e III, apenas.","C":"I e II, apenas.","D":"I, II e III."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-348450","number":"348450","sourceNumber":"348450","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente, sexo masculino, 39 anos, peso 59kg, pedreiro, tabagista 19 anos/maço, HIV\npositivo e com recente diagnóstico de tuberculose pulmonar. Nos casos de coinfecção do HIV e\ntuberculose pulmonar, o tratamento correto é:","options":{"A":"2 comprimidos em dose fixa combinada de RHZE (Rifampicina ? 150mg, Isoniazida ? 75mg,\nPirazinamida ? 400mg e Etambutol ? 275mg) na fase de ataque e 4 comprimidos ou cápsulas com\ndosagens fixas de RH (Rifampicina ? 300mg e Isoniazida ? 200mg) na fase de manutenção.","B":"4 comprimidos em dose fixa combinada de RHZE (Rifampicina ? 150mg, Isoniazida ? 75mg,\nPirazinamida ? 400mg e Etambutol ? 275mg) por dois meses e 2 comprimidos ou cápsulas com\ndosagens fixas de RH (Rifampicina ? 300mg e Isoniazida ? 200mg) por quatro meses.","C":"O esquema preconizado para casos de coinfecção com HIV em adultos e adolescentes consiste\nem doses fixas combinadas por nove meses,\nsendo dois meses de RHZE com 4 comprimidos,\nseguidos de sete meses de RH com 2 comprimidos.","D":"Para os casos de coinfecção TB/HIV em adultos e adolescentes, doses fixas combinadas por\ndoze meses, divididos em seis meses com 4 comprimidos do esquema RHZE, seguidos de seis\nmeses com 2 comprimidos do esquema RH."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-330923","number":"330923","sourceNumber":"330923","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Após confirmado o diagnóstico de Tuberculose Pulmonar e iniciado o tratamento, é\nnecessário o controle do tratamento, este feito em dose supervisionada e diária na unidade básica\nde saúde. NÃO é exemplo desse controle/acompanhamento:","options":{"A":"Realização mensal da baciloscopia de controle. Ela é indispensável no segundo, quarto e sexto\nmeses do tratamento.","B":"Acompanhamento clínico mensal do paciente no intuito de identificar queixas ou sinais clínicos,\nvisando à avaliação da evolução da doença, ao uso correto da medicação e à detecção de\nmanifestações adversas dos medicamentos.","C":"Exame radiológico utilizado periodicamente a partir do segundo mês de tratamento, para\nacompanhar a evolução das lesões, sobretudo na ausência de expectoração. Sua realização,\nporém, é indispensável no final do tratamento para comprovar a cura.","D":"Pacientes inicialmente bacilíferos deverão ter pelo menos duas baciloscopias negativas para\ncomprovar cura, uma na fase de acompanhamento e outra ao final do tratamento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-308324","number":"308324","sourceNumber":"308324","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Morador do interior de Mato Grosso, trabalhador rural, 45 anos, solteiro. Recebeu\ndiagnóstico de HIV em 2016 e, na ocasião,\npor não compreender bem o diagnóstico, parou o uso\nda terapia antiretroviral após 30 dias do seu início. Há 5 meses, começou a apresentar perda\nponderal importante (> 10% do peso habitual) associada à febre baixa esporádica, tosse seca e\nsurgimento de lesões extensas, de aspecto moriforme, em mucosa jugal e palato mole, além de\nadenomegalias cervicais, algumas com flutuação e fistulização. Ao exame físico, paciente\nencontrava-se emagrecido, com palidez mucosa de 2+/4+; taquipneico; anictérico e acionótico\n(SO? 94%). Hepatoesplenomegalia leve. O exame direto do raspado da lesão mucosa evidenciou\nlevedura com brotamentos múltiplos (coloração com KOH 10%). Considerando o quadro clínico e\nos achados laboratoriais, qual provável diagnóstico do paciente e a melhor opção terapêutica?","options":{"A":"Criptococcus neoformans; Anfotericina B + fluconazol","B":"Micobacteryum tuberculosis; Rifampicina, isoniazida, etambutol e pirazinamida","C":"Paracoccidioides brasiliensis; Anfotericina B","D":"Histoplasma capsulatum; Itraconazol"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-267289","number":"267289","sourceNumber":"267289","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Há três dias, atendeu-se o paciente Valtair na Unidade Básica de Saúde. Ele tem 51\nanos, é pequeno agricultor, tabagista,\nelitista, procedente de Juara-MT. Durante a consulta, relatou\nsintomas de tosse produtiva há 6 meses, perda ponderal de 5% do peso habitual, lesões\nmoriformes periodontais e linfadenites palpáveis em cadeias cervicais bilaterais. A hipótese\ndiagnóstica é paracoccidioidomicose (PCM). Solicitaram os seguintes exames para confirmar o\ndiagnóstico: micológico direto do escarro e radiografia de tórax em duas incidências. O paciente\nretornou hoje com os resultados dos exames que confirmaram o diagnóstico inicial, o que\npossibilitou a prescrição do tratamento de escolha para PCM. Com base no Segundo Consenso\nBrasileiro de Paracoccidioidomicose (2017), assinale a alternativa que apresenta os critérios\nmicológico e radiológico CORRETOS, bem como o diagnóstico da forma clínica e o tratamento\nmais adequado para esse paciente.","options":{"A":"Exame micológico direto demonstrando formas leveduriformes de Paracoccidioides spp.; lesão\ncavitária única em lobo superior do pulmão esquerdo; paracoccidioidomicose aguda;\nsulfametoxazol-trimetoprim por via oral, 1600-320 mg/dia por 18 a 24 meses.","B":"Exame micológico direto demonstrando formas micelianas de Paracoccidioides spp.; opacidades\nretículo-alveolares simétricas bilaterais no terço médio, com distribuição maior do centro para a\nperiferia; paracoccidioidomicose crônica unifocal; itraconazol por via oral, 200 mg/dia por 18 a 24\nmeses.","C":"Exame micológico direto demonstrando formas leveduriformes de Paracoccidioides spp.;\nopacidades retículo-alveolares simétricas bilaterais no terço médio, com distribuição maior do\ncentro para a periferia; paracoccidioidomicose crônica multifocal; itraconazol por via oral, 200\nmg/dia por 9 a 18 meses.","D":"Exame micológico direto demonstrando formas micelianas de Paracoccidioides spp.; opacidades\nretículo-alveolares simétricas bilaterais no terço médio, com distribuição maior do centro para a\nperiferia; paracoccidioidomicose aguda; sulfametoxazol-trimetoprim por via oral, 1600-320 mg/dia\npor 18 a 24 meses."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-274112","number":"274112","sourceNumber":"274112","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"SFR, masculino, 40 anos, solteiro, caminhoneiro, tabagista (20 cigarros/dia) desde os\n12 anos, refere que há 40 dias iniciou tosse\nseca e que após 10 dias notou também fraqueza e\nperda do apetite. Procurou atendimento médico na UBS, recebeu diagnóstico de IVAS com\nprescrição de sintomáticos. Fez uso correto da medicação, porém evoluiu com piora do quadro\nretornando à UBS. Assinale a alternativa que apresenta a principal hipótese diagnóstica, dados\nsemiológicos esperados e a investigação para o caso.","options":{"A":"HIV/AIDS infecção aguda; questionar presença de diarreia, úlceras aftosas e quelite angular;\nInvestigar doenças oportunistas e testes anti-HIV.","B":"Tumor pulmonar; sibilos, hemoptise, baqueteamento digital, síndrome carcinoide; Broncoscopia\ne RNM encéfalo.","C":"Pneumonia bacteriana; esforço expiratório, murmúrio vesicular universalmente diminuído e\nsibilos; TC Tórax e fibrobroncoscopia.","D":"Tuberculose pulmonar; ? do murmúrio vesicular, sopro anfórico e emagrecimento; Baciloscopia\ndireta, Teste Rápido Molecular e Rx tórax."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-288145","number":"288145","sourceNumber":"288145","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente do sexo masculino, 60 anos de idade, previamente hígido, apresenta há 60\ndias hiporexia e emagrecimento de 15% do peso. Há 20 dias apresenta febre diária e episódios de\ntosse seca. Em investigação médica, os exames evidenciaram pesquisa de BAAR no escarro 3+ e\nsorologia para HIV reagente (método quimioluminescência). Assinale a conduta CORRETA para o\ncaso.","options":{"A":"Confirmar o diagnóstico da infecção pelo HIV, iniciar itraconazol, e logo em seguida, após boa\nadesão, iniciar lamivudina, tenofovir e dolutegravir.","B":"Confirmar o diagnóstico da infecção pelo HIV, iniciar esquema RIPE (rifampicina, isoniazida,\npirazinamida e etambutol), e logo em seguida, após boa adesão do esquema RIPE, iniciar\nlamivudina, tenofovir e dolutegravir.","C":"Confirmar o diagnóstico da infecção pelo HIV, iniciar esquema RIPE (rifampicina, isoniazida,\npirazinamida e etambutol), e logo em seguida, após boa adesão do esquema RIPE, iniciar\nlamivudina, tenofovir e darunavir/ritonavir.","D":"Confirmar o diagnóstico da infecção pelo HIV, iniciar anfotericina b lipossomal, e logo em\nseguida, após boa adesão do tratamento, iniciar lamivudina, tenofovir e dolutegravir."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-255309","number":"255309","sourceNumber":"255309","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Nas lesões caseosas fechadas, o fármaco mais efetivo é a rifampicina, sendo a ação\nda isoniazida mais lenta e demorada. Nesse\ncontexto, está correto que:","options":{"A":"Na lesão cavitária, a rifampicina, isoniazida e estreptomicina não são muito efetivas e atuam em\npH neutro.","B":"Na lesão cavitária, a rifampicina, isoniazida e estreptomicina são muito efetivas e atuam em pH\nácido.","C":"Na lesão cavitária, a rifampicina, isoniazida e estreptomicina são pouco efetivas e atuam em pH\nneutro.","D":"Na lesão cavitária, a rifampicina, isoniazida e estreptomicina são muito efetivas e atuam em pH\nneutro."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-251282","number":"251282","sourceNumber":"251282","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em um paciente sintomático respiratório, apresentando tosse com expectoração há\ncerca de 3 meses, qual é o primeiro exame a ser realizado na investigação diagnóstica?","options":{"A":"Radiografia torácica","B":"Histopatológica","C":"Baciloscopia de escarro (BAAR)","D":"Cultura de orofaringe"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-255316","number":"255316","sourceNumber":"255316","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A infecção pelo HIV e a consequente imunodepressão celular modificam a história\nnatural da paracoccidioidomicose - PCM. Sendo adequado o item:","options":{"A":"Em comparação à doença em imunocompetentes, os pacientes coinfectados tendem a ser mais\nidosos envolvidos em atividades agrícolas, predominando as profissões e ambientes urbanos.","B":"Em comparação à doença em imunocompetentes, os pacientes coinfectados tendem a ser mais\njovens e mais envolvidos em atividades agrícolas.","C":"Em comparação à doença em imunocompetentes, os pacientes coinfectados tendem a ser mais\njovens e menos envolvidos em atividades agrícolas, predominando as profissões e ambientes\nurbanos.","D":"Em comparação à doença em imunocompetentes, os pacientes coinfectados tendem a ser mais\njovens e não envolvidos em atividades de ambientes urbanos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-255318","number":"255318","sourceNumber":"255318","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A atuação dos medicamentos anti TB difere conforme o metabolismo bacilar. Sendo\nadequado que:","options":{"A":"Na população intramacrofágica, agem os fármacos que melhor se difundem no meio intracelular\ne em pH ácido: rifampicina, pirazinamida e\netambutol.","B":"Na população intramacrofágica, agem os fármacos que pior se difundem no meio intracelular e\nem pH ácido: rifampicina, pirazinamida e etambutol.","C":"Na população intramacrofágica, agem os fármacos que melhor se difundem no meio extracelular\ne em pH ácido: rifampicina, pirazinamida e\netambutol.","D":"Na população intramacrofágica, agem os fármacos que melhor se difundem no meio intracelular\ne em pH básico: rifampicina, pirazinamida e\netambutol."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-254176","number":"254176","sourceNumber":"254176","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa que contenha a duração do esquema básico para tratamento da\ntuberculose pulmonar em adultos e a frequência indicada para realização de baciloscopia de\ncontrole após início do tratamento, respectivamente.","options":{"A":"6 meses; a cada 2 meses","B":"6 meses; mensalmente","C":"4 meses; a cada 2 meses","D":"4 meses; mensalmente"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-255352","number":"255352","sourceNumber":"255352","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para promover a incorporação de iniciativas inovadoras para aprimorar o controle da\ntuberculose, apenas não podemos aceitar que:","options":{"A":"Estimular a utilização dos resultados das pesquisas no enfrentamento da tuberculose.","B":"Incorporar novos medicamentos aos esquemas de tratamento da doença ativa e não na infecção\nlatente.","C":"Estimular a troca e a implantação de experiências exitosas das ações de controle entre os\nprogramas de controle da tuberculose.","D":"Incorporar, de maneira oportuna, novas tecnologias de diagnóstico."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-255356","number":"255356","sourceNumber":"255356","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Estudos sugerem que o adoecimento por TB resulta da relação entre determinantes\nprovenientes de três diferentes níveis: a comunidade, o ambiente domiciliar e características\nindividuais. Podemos apenas aceitar que:","options":{"A":"Os padrões de vida em uma comunidade não conformam a posição socioeconômica domiciliar,\nque, por sua vez, influência nas oportunidades\nindividuais em termos de educação, ocupação,\nqualidade da habitação e interações sociais.","B":"Os padrões de vida em uma comunidade conformam a posição socioeconômica domiciliar, que,\npor sua vez, não pode influenciar nas\noportunidades individuais em termos de educação, ocupação,\nqualidade da habitação e interações sociais.","C":"Os padrões de vida em uma comunidade conformam a posição socioeconômica domiciliar, que,\npor sua vez, não influencia nas\noportunidades individuais em termos de educação, ocupação,\nqualidade da habitação e interações sociais.","D":"Os padrões de vida em uma comunidade conformam a posição socioeconômica domiciliar, que,\npor sua vez, influência nas oportunidades\nindividuais em termos de educação, ocupação, qualidade\nda habitação e interações sociais."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-221112","number":"221112","sourceNumber":"221112","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A tuberculose é uma doença altamente prevalente no Brasil, com elevada\nmorbimortalidade nas faixas etárias\npediátricas, principalmente em crianças infectadas pelo HIV,\nindígenas e em imunodeficientes. A respeito da tuberculose na infância, analise as afirmativas. I.\nDeve-se suspeitar de tuberculose em crianças com diagnóstico de pneumonia sem melhora com o\nuso de antimicrobianos. II. Febre, tosse produtiva contínua, perda de peso e às vezes hemoptises\nsão as manifestações clínicas mais frequentes. III. Os achados radiográficos mais sugestivos da\ntuberculose pulmonar na infância são adenomegalias mediastinais, imagens cavitadas de lobos\nsuperiores e infiltrados nodulares difusos. IV. A prova tuberculínica (PPD) consiste na inoculação\nintradérmica de um derivado proteico do M. tuberculosis para medir a resposta imune celular a seus\nantígenos. V. A pesquisa do bacilo no escarro é o instrumento mais útil para o diagnóstico. VI. PPD\n\n= 10 mm em criança de 3 anos é diagnóstico de tuberculose latente e tem indicação de tratamento\ncom isoniazida por 3 meses. Está CORRETO o que se\nafirma em:","options":{"A":"II, III, V e VI, apenas.","B":"I, II, III e IV, apenas.","C":"V e VI, apenas.","D":"I e IV, apenas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-213955","number":"213955","sourceNumber":"213955","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Luiz, 56 anos, tabagista pesado, com queixa de tosse seca de longa data. Refere que\ncerta vez um médico disse que sempre ia ter\nfalta de ar e que teria que fazer inalação com\nfrequência, porém relata pouca melhora mesmo com uso de berotec e atrovent. Nos últimos 2\nmeses, vem apresentando piora da tosse, cansaço e episódios frequentes de \"gripe\". Sobre o caso\nacima, responda a questão. Qual a alternativa CORRETA?","options":{"A":"A radiografia de tórax está contraindicada por não auxiliar no exame complementar.","B":"Luiz é sintomático respiratório e mesmo que não seja um quadro característico de TB pulmonar\na baciloscopia do escarro deve ser solicitada.","C":"O único exame a ser solicitado é a espirometria para que seja confirmada a suspeita clínica de\nAsma.","D":"A cessação do tabagismo não deve ser foco do tratamento, pois não causa grande impacto no\nquadro clínico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-217923","number":"217923","sourceNumber":"217923","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para fins de medida de resultado efetivo no tratamento de uma determinada doença, a\natenção básica usa como estratégia a utilização do Tratamento Direto Observado (TDO) que\nconsiste na tomada diária de medicamentos (de segunda a sexta-feira) sob supervisão do\nprofissional de saúde (enfermeiro, técnico e auxiliar de enfermagem, médico e agente comunitário\nde saúde). Já em instituições fechadas como, por exemplo, o sistema prisional, o profissional\ntreinado pode realizar o TDO. Esta estratégia desenvolvida pelo Ministério da Saúde é utilizada em\npacientes portadores de:","options":{"A":"Dengue.","B":"Tuberculose.","C":"Hanseníase.","D":"HIV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-221056","number":"221056","sourceNumber":"221056","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Carolina, com diagnóstico recente de Tuberculose Pulmonar já há uma semana, em\ntratamento com o esquema RIPE, mãe do RN Afonso, quer amamentar o bebê. Qual é a orientação\na ser dada, em relação à amamentação e à doença?","options":{"A":"Não amamentar e iniciar o esquema tríplice ao RN.","B":"Não amamentar e esperar até que a mãe se torne não contagiante.","C":"Iniciar isoniazida no RN e amamentar com máscara.","D":"Aplicar BCG no RN e amamentar com máscara."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-214545","number":"214545","sourceNumber":"214545","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma senhora, que está em tratamento de tuberculose pulmonar há 3 semanas, leva o\nfilho de 4 anos ao pediatra para investigação clínica de contactantes porque assim foi orientada por\nseu médico. A criança está assintomática e apresenta marca da vacina BCG. O RX de tórax está\nnormal e o PPD foi = 7 mm. De acordo com o Manual de Recomendações para o Controle da\nTuberculose no Brasil e em relação à criança, marque a afirmativa CORRETA.","options":{"A":"Está indicada isoniazida por 4 meses.","B":"Trata-se de tuberculose latente.","C":"A prova tuberculínica deve ser repetida em 2 meses.","D":"Deve-se acompanhar clinicamente a criança e repetir o RX de tórax em 30 dias."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177279","number":"177279","sourceNumber":"177279","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação aos aspectos relacionados à toxoplasmose, assinale a alternativa correta:","options":{"A":"os cistos teciduais contém bradizoítas, os quais são altamente sensíveis ao tratamento com\nsulfadiazina e pirimetamina.","B":"a forma mais comum de contágio é a ingestão dos esporozoítas em carnes mal passadas.","C":"o acometimento ocular é caracterizado por coriorretinite e pode acometer pacientes\nimunocompetentes.","D":"a forma encefálica (neurotoxoplasmose) se dá comumente na primo-infecção, sendo raro os\ncasos por reativação.","E":"é a causa de febre de origem obscura, com linfadenite cervical dolorosa, confluente, com\ntendência á fistulização."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-185250","number":"185250","sourceNumber":"185250","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O Tratamento Direto Observado (TDO) consiste na tomada diária (de segunda a\nsexta-feira) de medicamentos sob supervisão do profissional de saúde (enfermeiro, técnico e\n\nauxiliar de enfermagem, médico e agente comunitário de saúde). O TDO é uma estratégia de saúde\npública, utilizada na Atenção Primária, em pessoas portadoras de:","options":{"A":"HIV","B":"Dengue","C":"Tuberculose","D":"Hanseníase","E":"Hepatite B"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-181538","number":"181538","sourceNumber":"181538","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente internado na UTI adulto há 20 dias devido acidente vascular encefálico\nisquêmico, evoluindo com sepse. Nas duas hemoculturas cresceu Candida glabrata. Qual\nantimicrobiano é adequado para tratamento dessa infecção?","options":{"A":"Caspofungina","B":"Fluconazol","C":"Sulfametoxazol/trimetropim","D":"Cetoconazol"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-181623","number":"181623","sourceNumber":"181623","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Uma doença infectocontagiosa prevalente no Brasil é a tuberculose. Seu tratamento\nnormalmente é feito por 4 antibióticos, distribuídos em 02 fases, sendo a 1.a fase com\npreferencialmente 4 antibióticos e na 2.a fase preferencialmente com 2 antibióticos. Assinale a\nafirmativa correta sobre o tratamento da tuberculose para adolescentes e adultos.","options":{"A":"Um paciente pesando 56 kg, com diagnóstico de tuberculose pulmonar, deve tomar 4\ncomprimidos do esquema RIPE (Rifampicina 150\nmg /Isoniaziada 75 mg/ Pirazinamida 400 mg/\nEtambutol 275 mg) durante os 2 primeiros meses e 4 comprimidos (Rifampicina 150 mg/ Isoniazida\n75 mg) pelos 4 meses subsequentes, totalizando 06 meses (tratamento esperado).","B":"Um paciente pesando 45 kg, com diagnóstico de tuberculose pulmonar, deve tomar 03\ncomprimidos do esquema RIPE (Rifampicina 150\nmg /Isoniaziada 75 mg/ Pirazinamida 275 mg/\nEtambutol 400 mg) durante os 2 primeiros meses e 3 comprimidos (Rifampicina 150 mg/ Isoniazida\n75 mg) pelos 4 meses subsequentes, totalizando 6 meses (tratamento esperado).","C":"Um paciente pesando 56 kg, com diagnóstico de tuberculose pulmonar, deve tomar 03\ncomprimidos do esquema RIPE (Rifampicina 150\nmg /Isoniaziada 75 mg/ Pirazinamida 400 mg/\nEtambutol 275 mg) durante os 2 primeiros meses e 3 comprimidos (Rifampicina 150 mg/ Isoniazida\n75 mg) pelos 4 meses subsequentes, totalizando 6 meses (tratamento esperado).","D":"Um paciente pesando 45 kg, com diagnóstico de tuberculose pulmonar, deve tomar 4\ncomprimidos do esquema RIPE (Rifampicina 150\nmg /Isoniaziada 75 mg/ Pirazinamida 275 mg/\nEtambutol 400 mg) durante os 2 primeiros meses e 4 comprimidos (Rifampicina 150 mg/ Isoniazida\n75 mg) pelos 4 meses subsequentes, totalizando 6 meses (tratamento esperado)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-159403","number":"159403","sourceNumber":"159403","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Um médico decidiu recomendar o uso de vitamina C para pacientes com sintomas\ngripais e observou que todos os pacientes\nque utilizavam ficavam curados 7 dias após o início dos\nsintomas. Passou então a recomendar vitamina C para todos os pacientes com gripe. Comprimidos\nde vitamina C não eram distribuídos pela farmácia pública até então e, devido ao grande número de\nprescrições, a prefeitura passou a realizar a compra e distribuição desta medicação. Em relação a\nsituação acima descrita assinale a alternativa INCORRETA:","options":{"A":"Experiência clínica conforme descrito no enunciado não é base consistente para fundamentação\nde decisões médicas.","B":"Recomendações médicas baseadas em evidências têm implicações financeiras para o sistema\nde saúde e para a sociedade.","C":"A decisão do médico em prescrever vitamina C a partir de suas observações foi incorreta uma\nvez que não houve busca de evidências.","D":"Fundamentação fisiopatológica mostrando mecanismo de ação da vitamina C na resolução do\nprocesso gripal seria base consistente suficiente para a indicação da gripe."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-159415","number":"159415","sourceNumber":"159415","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"São sinais de alerta da Dengue, EXCETO:","options":{"A":"Vômitos incoercíveis.","B":"Hepatomegalia.","C":"Hipotermia.","D":"Febre acima de 40°C."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-158112","number":"158112","sourceNumber":"158112","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre Tuberculose, assinale a afirmativa INCORRETA:","options":{"A":"A transmissão do bacilo causador da doença se dá em forma de aerossóis de gotículas\nminúsculas portadoras do bacilo, chamadas gotículas de Flugge.","B":"Na primoinfecção, os bacilos inalados chegam aos alvéolos onde ocorre reação inflamatória\nlocal, seguida de disseminação hematogênica e\nlinfática. Nessa situação, 95% dos casos evoluem\npara necrose caseosa e fibrose local.","C":"A maior parte dos casos de tuberculose pulmonar é de reativações de focos infecciosos,\nchamados de tuberculose pós-primária, ocorrendo anos após a infecção primária.","D":"É uma doença infecciosa que afeta exclusivamente os pulmões, provocando sintomas como\nemagrecimento, tosse produtiva e, eventualmente, hemoptise devido a lesões pulmonares."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-158118","number":"158118","sourceNumber":"158118","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre o tratamento da Tuberculose, assinale a afirmativa INCORRETA:","options":{"A":"O tratamento da tuberculose se dá inicialmente mediante esquema composto pelos agentes\nantibióticos Rifampicina (R), Isoniazida (H), Pirazinamida (Z) e Etambutol (E), e passa pela fase\nIntensiva, de 4 meses, seguido pela fase de Manutenção, de 2 meses (4RHZE + 2RH).","B":"O paciente que inicia o tratamento para tuberculose pulmonar deixa de expelir os bacilos em\ngotículas aerossóis em no máximo 15 dias de tratamento.","C":"O tratamento da tuberculose deve ser feito, salvo em raras exceções, através do chamado\nTratamento Diretamente Observado (TDO) em que o\npaciente comparece diariamente à Unidade\nde Saúde e faz uso da medicação perante um agente de saúde.","D":"A dose dos antibióticos deve ser ajustada pelo peso dos pacientes, corrigindo a dose caso o\npaciente mude de peso durante o tratamento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-136902","number":"136902","sourceNumber":"136902","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente J.J.C., 58 anos, sexo masculino, mora em Rondônia, apresenta há 5 dias\nfebre, astenia e mal-estar. Há 1 dia, evoluiu\ncom prostração, leve icterícia, desidratação e diarreia.\nAo exame físico: PA = 90 x 60 mmHg; FC = 110 bpm; FR = 29 irpm; T = 38,8°C. Regular estado\ngeral, acianótico, ictérico 1+/4+, taquidispneia leve, hipocorado 2+/4+, consciente e cooperante.\n\nAusculta cardíaca e pulmonar sem alterações; abdome com leve esplenomegalia. Assinale a\nalternativa que apresenta diagnóstico CORRETO e conduta apropriada:","options":{"A":"Dengue; hidratação (expansão volêmica).","B":"Malária; hidratação (expansão volêmica) e uso de cloroquina e primaquina via oral.","C":"Calazar; hidratação (expansão volêmica) e uso de anfotericina B lipossomal.","D":"Malária; hidratação (expansão volêmica) e uso de artesunato e clindamicina endovenosos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-85068","number":"85068","sourceNumber":"85068","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A leishmaniose tegumentar é doença endêmica em grande parte do Brasil. Quanto aos\naspectos clínicos, analise as afirmativas. I - A Leishmaniose Cutânea (LC) pode preceder a\nLeishmaniose Mucosa (LM). II - Como apresentação inicial da LM em sua forma tardia, têm-se\nfrequentemente lesões de mucosa nasal assim como da mucosa oral. III - A LC é frequentemente\nrepresentada por lesões ulceradas únicas ou múltiplas pouco dolorosas e com granulações ao\nfundo. Está correto o que se afirma em:","options":{"A":"I, II e III.","B":"I e II, apenas","C":"III, apenas.","D":"I e III, apenas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-360593","number":"360593","sourceNumber":"360593","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O achado de micobactérias não tuberculosas (MNT) em isolados clínicos pode ter\nsignificados:","options":{"A":"A bactéria é responsável pela ocorrência de uma micobacteriose, é um contaminante, mas\nnunca um simples colonizador.","B":"A bactéria é responsável pela ocorrência de uma micobacteriose, nunca ou é um contaminante,\nou um simples colonizador.","C":"A bactéria é responsável pela ocorrência de uma micobacteriose, ou é um contaminante, ou um\nsimples colonizador.","D":"A bactéria nunca é a responsável pela ocorrência de uma micobacteriose, e sim um\ncontaminante, ou um simples colonizador."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-309780","number":"309780","sourceNumber":"309780","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale V (verdadeiro) ou F (falso) nas afirmativas a seguir quanto aos efeitos\ncolaterais dos fármacos que compõem o\nesquema básico (RHEZ) para o tratamento da tuberculose\ne a conduta. Ana Marques; ( ) Náusea, vômito e dor abdominal, a conduta é suspender o esquema\ne após uma semana introduzir uma a uma e suspender a responsável pela intolerância. ( ) Prurido\nou exantema leve são causados pela rifampicina e a isoniazida, conduta manter o esquema e\nprescrever um anti-histamínico. ( ) Dor articular e febre são causadas pelo etambutol, conduta\nmanter o esquema e medicar com anti-inflamatórios não hormonais. ( ) Rabdomiólise com\nmioglobinúria e insuficiência renal, suspender a pirazinamida e reiniciar esquema especial sem a\nreferida medicação. ( ) Encefalopatia tóxica, suspender a Isoniazida e reiniciar esquema especial\nsem a referida medicação. Indique a alternativa que apresenta a sequência CORRETA:","options":{"A":"V, V, F, V, F","B":"F, V, F, V, V","C":"V, F, F, V, F","D":"V, F, V, V, V","E":"Nenhuma das alternativas anteriores"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-301654","number":"301654","sourceNumber":"301654","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A identificação histológica de granuloma com necrose de caseificação é compatível\ncom o diagnóstico de Tuberculose. Sendo\nadequado que:","options":{"A":"A avaliação histológica de fragmento de tecido obtido por biópsia não é um método empregado\nna investigação das formas pulmonares que se\napresentam radiologicamente como doença difusa\ne nas formas extrapulmonares.","B":"A avaliação histológica de fragmento de tecido obtido por biópsia é um método empregado na\ninvestigação das formas pulmonares que se apresentam radiologicamente como doença difusa e\nnas formas extrapulmonares.","C":"A avaliação histológica de fragmento de tecido obtido por biópsia é um método empregado na\ninvestigação das formas pulmonares que se apresentam radiologicamente como doença difusa e\nnunca nas formas extrapulmonares.","D":"A avaliação histológica de fragmento de tecido obtido por biópsia é um método empregado na\ninvestigação das formas pulmonares que se apresentam radiologicamente como doença não difusa\ne nas formas extrapulmonares."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-276026","number":"276026","sourceNumber":"276026","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente masculino, 35 anos, portador do vírus HIV em tratamento irregular, é atendido\nno pronto-socorro com quadro de hemoptise de\npequeno volume de início há 1 hora, associada a\ntosse produtiva, febre vespertina diária e perda de peso (6 kg) nos últimos 3 meses. Nega outras\ncomorbidades. Nega tabagismo ou uso ilícito de drogas. Após medidas de suporte iniciais, foi\nsubmetido a uma tomografia computadorizada do tórax sem contraste, representada a seguir:\nDiante dos dados clínicos e imagem tomográfica, qual a principal hipótese diagnóstica?","options":{"A":"Adenocarcinoma pulmonar.","B":"Aspergiloma.","C":"Abscesso pulmonar.","D":"Pneumonia necrotizante."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/276026.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-286106","number":"286106","sourceNumber":"286106","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em recém-nascido filho de mãe com tuberculose pulmonar com pesquisa de BAAR\npositiva no escarro, a conduta mais adequada é:","options":{"A":"tratar com o esquema básico;","B":"iniciar quimioprofilaxia;","C":"fazer radiografia do tórax;","D":"realizar tomografia de alta resolução do tórax;","E":"realizar teste tuberculínico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-274961","number":"274961","sourceNumber":"274961","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Dentre os objetivos de se iniciar o tratamento da Tuberculose (TB), o mais\nprecocemente possível, estão a cura e a quebra da\ncadeia de transmissão da doença. Especial\natenção deve ser dada ao abandono do tratamento, a fim de se evitar o desenvolvimento de\nresistência aos fármacos utilizados. Nesse contexto, recomenda-se o Tratamento Diretamente\nObservado (TDO) como estratégia para redução das taxas de abandono do tratamento pelos\npacientes. Sobre o TDO, assinale a alternativa CORRETA.","options":{"A":"O TDO da tuberculose consiste na ingestão supervisionada da medicação pelo paciente. Essa\nobservação deve ser realizada por um profissional da equipe de saúde, por, no mínimo, 5 (cinco)\nvezes na semana, tanto na dose de ataque quanto na dose de manutenção.","B":"O TDO da tuberculose consiste na ingestão supervisionada da medicação pelo paciente. Essa\nobservação deve ser realizada por um profissional da equipe de saúde, por, no mínimo, 3 (três)\nvezes na semana, tanto na dose de ataque quanto na dose de manutenção.","C":"O TDO da tuberculose consiste na ingestão supervisionada da medicação pelo paciente. Essa\nobservação deve ser realizada por um profissional da equipe de saúde, nos primeiros 3 (três) dias\ndo tratamento, na dose de ataque.","D":"O TDO da tuberculose consiste na ingestão supervisionada da medicação pelo paciente. Essa\nobservação deve ser realizada por um\nprofissional da equipe de saúde, nos primeiros 10 (dez) dias\ndo tratamento, na dose de ataque.","E":"O TDO da tuberculose consiste na ingestão supervisionada da medicação pelo paciente. Essa\nobservação deve ser realizada por um profissional da equipe de saúde, nos primeiros 12 (doze)\ndias do tratamento, na dose de ataque."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-284217","number":"284217","sourceNumber":"284217","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Para os profissionais de saúde, atenção se deve à exposição constante a pessoas com\nTB, aumentando o risco de desenvolvimento da doença ativa. Sendo correto o item:","options":{"A":"Nesses profissionais, deve-se sempre buscar e não considerar a possibilidade de infecção\nrecente.","B":"Nesses profissionais, deve-se sempre buscar e desconsiderar a possibilidade de infecção\nrecente.","C":"Nesses profissionais, não se deve buscar e considerar a possibilidade de infecção recente.","D":"Nesses profissionais, deve-se sempre buscar e considerar a possibilidade de infecção recente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-243743","number":"243743","sourceNumber":"243743","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito do manejo da tuberculose em pacientes com outras comorbidades, é correto\nafirmar que:","options":{"A":"quando se estabelece o diagnóstico simultâneo de SIDA e tuberculose, recomenda-se iniciar\nprimeiramente o tratamento antirretroviral, e após 15 dias, o tratamento específico para\ntuberculose,\npor conta do risco de síndrome de reconstituição imune","B":"em pacientes com diabetes melittus, a tuberculose costuma fugir do padrão radiológico clássico,\ntem maior probabilidade de localização basal,\nbilateral, e tem cavitações frequentes","C":"nos pacientes com cirrose e tuberculose, o tratamento indicado não difere daqueles pacientes\nsem esta doença hepática","D":"em pacientes com diabetes melittus e tuberculose, o controle glicêmico tem metas menos\nrigorosas"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-247124","number":"247124","sourceNumber":"247124","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Criança indígena, 5 anos de idade, moradora na aldeia Bororó em Dourados-MS, com\nhistória de tosse seca diária, principalmente no período vespertino, há mais de 1 mês,\nacompanhada de febre esporádica que melhorava com uso de antitérmico, foi levada à Unidade\nBásica de Saúde (UBS), sendo diagnosticada com pneumonia e tratada com amoxacilina mais\nclavulanato e broncodilatador, porém com persistência da tosse. Foi efetuada busca ativa e sem\ncontato com tuberculose. Realizados PPD não reator e baciloscopia negativa. História vacinal com\nBCG, no primeiro mês de vida. Ao exame físico, apresentava adinamia e emagrecida. Raios X de\ntórax com alargamento de mediastino superior e condensação parenquimatosa em base esquerda.\nDe acordo com o sistema de pontuação para o diagnóstico de tuberculose na infância, preconizado\npelo Ministério da Saúde, para esse caso qual a conduta a ser adotada?","options":{"A":"Não tratar como tuberculose.","B":"Iniciar tratamento para tuberculose.","C":"Fica a critério do médico iniciar o tratamento para tuberculose.","D":"Continuar a investigação de caso suspeito de tuberculose.","E":"Encaminhar para a pneumologia investigar outra patologia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-216837","number":"216837","sourceNumber":"216837","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"De acordo com a OMS em sua publicação ?Estratégia pelo fim da Tuberculose? de\n2015, é imprescindível aumentar o rastreio,\ndiagnóstico e tratamento da Infecção Latente pelo\nMycobacterium Tuberculosis (ILTB). Neste ano, 2018, o Ministério da Saúde do Brasil, publicou por\nmeio do Programa Nacional de Controle da Tuberculose o protocolo de vigilância da ILTB do Brasil.\nConsiderando o definido por esse protocolo, podemos afirmar que:","options":{"A":"A tuberculose ativa não exclui a ILTB concomitante.","B":"O tratamento da ILTB está indicado para recém-nascidos coabitantes de caso suspeito não\nconfirmado laboratorialmente.","C":"O tratamento da ILTB está indicado para profissionais da área da saúde e trabalhadores de\ncasas de longa permanência com prova\ntuberculínica com conversão (2ª PT com incremento de 10\nmm em relação à 1ª PT).","D":"O tratamento da ILTB está indicado para Portadores de Diabetes mellitus e/ou tabagistas com\nProva tuberculínica = 5mm."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-220268","number":"220268","sourceNumber":"220268","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre o tratamento integral dos pacientes com tuberculose (TB) é CORRETO afirmar\nque:","options":{"A":"O esquema básico com 3 fármacos para os menores de 12 anos inclui Isoniazida, clofazimina e\nrifampicina em regime domiciliar com tomadas diárias supervisionadas","B":"O tratamento diretamente observado (TDO) durante todo o tempo de tratamento deve ser\nindicado para todos os pacientes com TB pulmonar\nindependente da positividade do escarro e da\nidade.","C":"O paciente com diagnóstico de TB deve fazê-lo em regime TDO e ser encaminhado ao serviço\nsocial com licença médica a qual tem direito durante todo o tempo de tratamento","D":"Pacientes com a coinfecçao HIV/TB, o seu tratamento será em regime hospitalar durante os 2\nprimeiros meses devido a necessidade do uso de antirretrovirais pois o risco de efeitos colaterais\nmaiores é alto."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-220230","number":"220230","sourceNumber":"220230","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Juca, 35 anos teve diagnostico de tuberculose pulmonar, ele reside com a mulher e 3\nfilhos menores de 10 anos. Fátima, a esposa, apresenta tosse há mais de 3 semanas.\n\nConsiderando a família qual a conduta inicialmente recomendada é:","options":{"A":"Prova tuberculínica, teste rápido molecular para tuberculose (TB) e baciloscopia seriada do\nescarro","B":"Prova tuberculínica, teste rápido molecular para TB e radiografia do tórax para todos os\nresidentes","C":"Prova tuberculínica para os filhos, para a esposa teste rápido molecular para TB e radiografia do\ntórax","D":"Avaliação clínica, prova tuberculínica e radiografia de tórax para todos os que residem na casa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-214043","number":"214043","sourceNumber":"214043","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"No que concerne à tuberculose, assinale a alternativa CORRETA.","options":{"A":"A forma pulmonar é a mais comum. O diagnóstico é feito através dos sintomas apresentados\nassociados ao resultado do teste\ntuberculínico.","B":"A forma pleural é bastante comum em profissionais da área da saúde. O diagnóstico é feito\natravés de exames de imagem e baciloscopia positiva no escarro.","C":"É comum o aparecimento da doença em pacientes portadores do vírus HIV. Nesses pacientes, o\ntratamento deve ser estendido por 12 meses.","D":"Gestantes que apresentam diagnóstico de tuberculose não devem ser tratadas até o nascimento\ndo bebê pelo risco de teratogenicidade.","E":"Na tuberculose ganglionar, é comum a fistulização dos gânglios com saída de secreção\npurulenta. Nesses casos, é comum a visualização microscópica do agente no aspirado da\nsecreção."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-213990","number":"213990","sourceNumber":"213990","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente masculino, 42 anos, vendedor, está tossindo há alguns meses e procura a\nUnidade Básica de Saúde para uma consulta médica. Durante a consulta diz à médica que viu um\nprograma na televisão sobre câncer de pulmão e está com receio de ter a doença. Relata que está\ntossindo há mais de 3 meses. Nega tabagismo, uso de álcool e medicamentos. A tosse é\npersistente e tem momentos de piora como, por exemplo, após as refeições. Relata ainda que\nsente \"catarro descer pela garganta\" e que o nariz está constantemente \"escorrendo\". Pela\ndescrição, a tosse desse paciente é","options":{"A":"emocional, pois o paciente está aflito com a possibilidade de ter câncer.","B":"aguda, por apresentar piora em situações específicas.","C":"subaguda, pois está presenta há mais de 8 semanas.","D":"crônica, pois está presente há mais de 8 semanas.","E":"subaguda, pois a presença de catarro na garganta indica infecção."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177172","number":"177172","sourceNumber":"177172","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente, caso novo de tuberculose, ex-privado de liberdade em tratamento em UBS\ncom esquema básico, em supervisão diária da\ntomada dos medicamentos por um agente\ncomunitário de saúde. Apresenta baciloscopia (++) ao final do segundo mês de tratamento. Foi\nsolicitada cultura, identificação e teste de sensibilidade. No quarto mês de tratamento, apresenta\nbaciloscopia positiva (++), sem conseguir ganhar peso. O resultado da cultura foi: contaminada.\nQual a conduta mais indicada?","options":{"A":"Considera o caso como falência e encaminha para a referência terciária, mantendo o esquema\nbásico.","B":"Manter o esquema básico e solicita nova cultura, identificação e teste de sensibilidade.","C":"Solicitar baciloscopia, cultura e teste de sensibilidade e acrescenta estreptomicina ao esquema\nbásico.","D":"Iniciar esquema de tuberculose multirresistência."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-177902","number":"177902","sourceNumber":"177902","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Ana Maria, 7 anos, é levada ao pronto-atendimento com história de tosse persistente e\nfebre há duas semanas. Ao exame físico: FR: 52 irpm, FC: 126bpm e murmúrio vesicular diminuÍdo\nno hemitórax esquerdo. RX de tórax: extenso derrame pleural. A toracocentese apresentou líquido\namarelado e a citologia diferencial demonstrou predomínio de linfócitos (>80%). O agente etiológico\nmais provável a ser considerado é:","options":{"A":"Streptococcus pneumoniae.","B":"Mycoplasma pneumoniae.","C":"Staphylococcus aureus.","D":"Haemophilus influenzae.","E":"Mycobacterium tuberculosis."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-183518","number":"183518","sourceNumber":"183518","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em uma ESF, paciente de 58 anos de idade, sexo masculino, trabalhador rural, com\nantecedente de HAS mal controlada, tabagismo 25 anos/maço, e etilismo social, procura\natendimento médico com queixa de tosse produtiva, falta de ar progressiva há cerca de 30 dias e\nfebre no início dos sintomas. Ao exame físico, apresenta FR 22 irpm MV + com roncos e sibilos\ndifusos. Orofaringe com dentes em péssimo estado de conservação. Com relação a esse caso,\nassinale a alternativa CORRETA.","options":{"A":"Devem ser solicitados exames de raios x de tórax e escarro para pesquisa de fungos e BAAR, e\ntratamento sintomático até o resultado dos exames.","B":"Deve ser solicitada espirometria e encaminhada ao pneumologista.","C":"Deve ser iniciada antibioticoterapia empírica para pneumonia e se não houver melhora clínica\nencaminhar o paciente ao especialista.","D":"Deve ser realizado ECG e encaminhado a um cardiologista com urgência.","E":"O paciente deve ser encaminhado a um PA com urgência, devido à gravidade do caso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-156097","number":"156097","sourceNumber":"156097","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Homem de 60 anos, trabalhador rural, tabagista e etilista, procura serviço de saúde\nqueixando de lesão ulcerada nasal há 6 meses, que não melhora com pomadas locais e uso de\nciclo de antibioticoterapia. Traz biópsia de mucosa nasal com a seguinte descrição: Presença de\ninfiltrado inflamatório crônico de aspecto granulomatoso com células leveduriformes arredondadas\nde parede espessa; com múltiplas gemulações (aspecto de \"roda de leme\"). Baseando-se nesses\ndados, qual a hipótese diagnóstica CORRETA?","options":{"A":"Granulomatose inespecífica.","B":"Paracoccidioidomicose.","C":"Tuberculose extrapulmonar.","D":"Hanseníase virchowiana.","E":"Leishmaniose cutaneomucosa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-151078","number":"151078","sourceNumber":"151078","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente em uso de esquema básico para tuberculose pulmonar, acompanhado em\numa unidade básica de saúde. A partir da 3ª\nsemana de tratamento, apresentou náuseas, vômitos,\nicterícia e aumento das enzimas hepáticas 6x o limite superior normal. Negava hepatopatias prévias\nou alcoolismo. Qual a conduta mais adequada?","options":{"A":"Interrupção do tratamento e início imediato do esquema SEO.","B":"Interrupção do tratamento; esperar a normalização dos níveis enzimáticos e melhora da icterícia\npara reintrodução inicialmente com a rifampicina\n+ etambutol, acrescentando a isoniazida e, por\núltimo, a pirazinamida, com intervalo de três a sete dias entre elas.","C":"Interrupção do tratamento, encaminhamento para uma referência terciária.","D":"Interrupção do tratamento e, após a melhora clínica e enzimática, reintroduzir a pirazinamida por\ntrês a cinco dias; acrescentar a isoniazida e por último a rifampicina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-155689","number":"155689","sourceNumber":"155689","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A respeito da tuberculose, podemos afirmar que:","options":{"A":"A vacinação com BCG diminui a incidência de formas graves de tuberculose em crianças, sendo\nque a segunda dose passou a ser\nobrigatória desde 2006.","B":"O teste rápido molecular para tuberculose (TRM-TB) é um teste automatizado, simples, rápido e\nde fácil execução. Testa simultaneamente o\nMycobacterium tuberculosis e a resistência à\nrifampicina em aproximadamente duas horas.","C":"O TRM-TB, além de fazer o diagnóstico, também é amplamente utilizado para acompanhamento\nde casos de tuberculose, substituindo as\nbaciloscopias, e para fechar o diagnóstico de\nmicrobacterioses não tuberculosas.","D":"O Ministério da Saúde não recomenda a revacinação de crianças que não apresentem a cicatriz\nvacinal após seis meses da vacinação, excetuando-se as que são comunicantes de casos\npositivos.","E":"Crianças sintomáticas e adultos HIV positivos devem realizar a vacina da BCG juntamente com\nimunoglobina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-132251","number":"132251","sourceNumber":"132251","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"O Aedes aegypti, o Triatoma infestans e o Anopheles spp. são vetores dos agentes\netiológicos das seguintes doenças, respectivamente:","options":{"A":"Febre amarela, doença de Chagas e malária.","B":"Febre amarela, malária e doença do sono.","C":"Dengue, doença de Chagas, doença do sono.","D":"Dengue, febre amarela e malária."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-132286","number":"132286","sourceNumber":"132286","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação aos pacientes com Dengue, assinale a afirmativa correta, entre as\nseguintes:","options":{"A":"Os casos mais graves apresentam hemodiluição, plaquetopenia, hipoalbuminemia e aumento de\ntransaminases.","B":"A ultrassonografia não é um exame útil para o diagnóstico de derrames cavitários em fase\ninicial.","C":"Hepatoesplenomegalia é um achado bastante frequente nas crianças com Dengue.","D":"Entre os achados laboratoriais inespecíficos, a leucopenia é frequente nos pacientes com\nDengue."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-130103","number":"130103","sourceNumber":"130103","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"As manifestações clínicas observadas durante a infecção pelo vírus da dengue ocorrem\napós um período de incubação.\nConsiderando-se o dia 0 (zero) como sendo o primeiro dia de\nsintoma febril desta doença, assinale a alternativa que contém as linhas no gráfico a seguir que\ncorrespondem, respectivamente, à viremia e ao anticorpo IgG em um paciente com infecção por\ndengue pela segunda vez na vida: (VER IMAGEM)","options":{"A":"Linhas A e E.","B":"Linhas B e E.","C":"Linhas D e C.","D":"Linhas E e C."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-10/130103.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-132292","number":"132292","sourceNumber":"132292","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com início de febre elevada (39°C) há oito dias, mialgia, cefaleia frontal, dor\nabdominal e dor em panturrilhas. Ao procurar atendimento médico no Posto de Saúde, é admitido\nconsciente e orientado, referindo persistência de alguns picos febris e discreto prurido; o médico\nobserva exantema macular eritematoso em tronco e queixa de discreto prurido. Apresente-se\nictérico, com discreta sufusão hemorrágica conjuntival e com taquipneia relativa. Os primeiros\nexames laboratoriais demonstram anemia e trombocitopenia, potássio 3,0 mEq/L, creatinina: 2,3\nmg/dL, CPK e bilirrubinas elevadas. Qual é a principal hipótese diagnóstica?","options":{"A":"Doença de Weil","B":"Dengue","C":"Malária","D":"Febre Tifoide"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-132229","number":"132229","sourceNumber":"132229","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"A leishmaniose visceral é uma doença que deve sempre ser investigada em pacientes\ncom história de febre prolongada. Assinale a\nalternativa que contém um critério laboratorial\nesperado para um paciente com diagnóstico de calazar clássico, cuja pesquisa para HIV é não\nreagente:","options":{"A":"Teste de Montenegro reator forte","B":"Eletroforese de proteínas com aumento da fração gama","C":"Hepatomegalia sem esplenomegalia","D":"Ensaioimunoenzimático para Leishmania spp não reagente"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-138023","number":"138023","sourceNumber":"138023","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Com relação à Dengue, assinale a afirmativa incorreta:","options":{"A":"A dengue representa a principal arbovirose do mundo, sendo hoje considerada um problema de\nsaúde pública internacional, com\nhiperendemicidade em vários centros urbanos localizados em\nregiões tropicais e subtropicais.","B":"Existem quatro sorotipos virais geneticamente distintos, designados DEN-1, DEN-2, DEN-3 e\nDEN-4, capazes de causar desde febre indiferenciada até formas clínicas graves, como a febre\nhemorrágica da dengue/síndrome do choque da dengue (FHD/SCD).","C":"As manifestações clínicas iniciais de FHD podem ser as mesmas descritas para a dengue\nclássica, até que ocorra a defervescência, entre o 3º e o 7º dias, quando costuma ocorrer a\ninstalação da síndrome.","D":"É uma doença de notificação obrigatória no Brasil, porém somente casos confirmados devem\nser notificados, pelo médico assistente, em ficha\nde notificação específica; sendo que os casos\ngraves confirmados devem ter notificação imediata.","E":"Duas alterações fisiopatológicas principais ocorrem na FHD/SCD: aumento da permeabilidade\nvascular, provocando perda de plasma para o\nterceiro espaço, e disfunção na hemostasia,\nenvolvendo alterações vasculares, trombocitopenia e coagulopatia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-107837","number":"107837","sourceNumber":"107837","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Paciente com quadro de febre há 2 dias (temperatura máxima 39 graus) associada à\nintensa mialgia e artralgia. Associado refere cefaleia e surgimento de exantema macular não\npruriginoso. A artralgia é predominante de grandes e médias articulações sem sinais de artrite. Traz\no resultado de hemograma mostrando: Hb: 12,0 g/dl, Leucócitos: 5.300 (Segmentados 55%\nLinfócitos 40 % e Monócitos 5%), Plaquetas: 285.000/mm³. Qual a hipótese diagnóstica?","options":{"A":"Febre do Chikungunya.","B":"Febre Hemorrágica da Dengue.","C":"Doença de Kawasaki.","D":"Sífilis secundária.","E":"Hepatite viral."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-106738","number":"106738","sourceNumber":"106738","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na leishmaniose visceral em adultos jovens:","options":{"A":"A icterícia é comum.","B":"A elevação de eosinófilos é sinal de gravidade.","C":"Não aumenta recidiva na associação com HIV/Aids.","D":"Anfotericina B lipossomal é a droga mais segura sem efeitos colaterais.","E":"A sorologia IFI = 1:80 preenche critério laboratorial."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-106744","number":"106744","sourceNumber":"106744","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre a malária, podemos afirmar que:","options":{"A":"As espécies mais prevalentes no Brasil são P. falciparum e P. malariae.","B":"A transmissão vetorial ocorre pela picada de mosquitos do gênero Lutzomyia.","C":"O período de incubação é inferior a 7 dias, independente da espécie de plasmódio.","D":"O homem é o único reservatório com importância epidemiológica.","E":"Mato Grosso do Sul é considerada área endêmica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-106754","number":"106754","sourceNumber":"106754","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Adolescente, 16 anos, procedente de Corumbá-MS, com história de 3 (três) meses com\nfebre. emagrecimento de 10 kg no período, dor abdominal e sangramento gengival. Apresenta-se\nhipocorada +2/+4, Traube ocupado, fígado 3 cm do RCD. Exames laboratoriais revelam anemia\nnormocrômica e normocítica, leucopenia e plaquetopenia, inversão albumina/globulina. Conduta\ndiagnóstica mais adequada:","options":{"A":"Pesquisa de antígeno rK39 (imunocromatografia).","B":"Mantoux.","C":"Reação de Montenegro.","D":"Biópsia de fígado.","E":"Esplenectomia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-106798","number":"106798","sourceNumber":"106798","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação a dengue, assinale a medida menos eficaz para a redução do número de\ncasos:","options":{"A":"Redução do número de criadouros de Aedes aegypti.","B":"Visita regular bimensal supervisionada às residências para orientação e inspeção pelos agentes.","C":"Borrifação de inseticida eficaz, a ultra baixo volume nas ruas com casos suspeitos, por pessoal\ncapacitado, usando máquinas bem reguladas.","D":"Participação efetiva da população.","E":"Envolvimento de prefeitos e vereadores para a manutenção e regularidade das ações de\ncontrole."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-107029","number":"107029","sourceNumber":"107029","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Leishmaniose visceral, no Brasil, está em expansão: novas áreas de casos caninos e\nhumanos têm sido relatadas. Sobre a\nepidemiologia e métodos diagnósticos, é CORRETO afirmar\nque:","options":{"A":"No Brasil, casos humanos geralmente precedem os casos em cães.","B":"No Brasil, o principal vetor é Lutzomyia longipalpis.","C":"A Leishmania chagasi não é responsável pelos casos de leishmaniose visceral no Brasil.","D":"O tratamento específico no cão (drogas leishmanicidas humanas) está indicado e aprovado pelo\nMinistério da Saúde."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-111783","number":"111783","sourceNumber":"111783","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à Dengue, a confirmação da entrada do sorotipo DEN4 no Brasil, além da\ncirculação prévia dos três outros sorotipos:","options":{"A":"Tranquiliza as autoridades sanitárias em função da imunidade adquirida pela população.","B":"Não faz diferença no que diz respeito ao quadro epidemiológico.","C":"Provavelmente acarretará o aumento da transmissão, tendo em vista o alto número de\nsuscetíveis na população.","D":"Demonstra que o programa de controle da dengue deve ser totalmente remodelado.","E":"Obriga ao recadastramento de todos os pacientes que tiveram dengue no passado."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-111787","number":"111787","sourceNumber":"111787","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em 2014 o Brasil confirmou 37 casos de Chikungunya. Os exames laboratoriais para\ndetecção do vírus causador dessa doenças são:","options":{"A":"Hemograma, sorologia e contagem de plaquetas.","B":"Hemocultura e sorologia.","C":"Exame de gota espessa e hemograma.","D":"Isolamento viral e contagerm de plaquetas.","E":"Sorologia, PCR em tempo real (RT-PCR) e isolamento viral."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-106793","number":"106793","sourceNumber":"106793","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Menino de 12 anos apresentou febre remitente por 15 dias, além de\nhepatoesplenomegalia e pancitopenia. Teve o\ndiagnóstico de leishmaniose visceral confirmado, ao\nevidenciar-se o parasita. Foi tratado com antimonial pentavalente (antimoniato de\n\nN-metilglucamina) em regime hospitalar, apresentando melhora gradual do quadro clínico. Sobre\neste caso assinale a alternativa INCORRETA:","options":{"A":"A recidiva da leishmaniose embora não seja frequente, precisa ser monitorada no seguimento\ndeste paciente.","B":"Além da recidiva, é possível a reinfecção, uma vez que a resposta imune específica à\nleishmaniose não confere imunidade permanente.","C":"Um dos efeitos colaterais deste antimonial é causar distúrbios de repolarização no aparelho\ncardiovascular e consequente arritmia.","D":"Deve ser realizada investigação sorológica para leishmaniose em todas as pessoas contactantes\ndeste paciente.","E":"Ao receber alta hospitalar o menino deve ser acompanhado ambulatorialmente, até que\napresente todos os critérios de cura."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-83564","number":"83564","sourceNumber":"83564","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Mulher, 24 anos, previamente hígida, com história de febre alta há 3 dias, seguida de\ncefaleia e prostração. Hoje notou sangramento gengival durante escovação dentária e pequenas\nmanchas na pele, principalmente em tornozelos. Aparecimento de dor abdominal difusa, que vem\naumentando de intensidade nas últimas 2 horas, acompanhada de náuseas. Ao exame físico:\nregular estado geral, eupneica, acianótica e anictérica. Temperatura axilar de 39°C, Pressão\nArterial 80 X 50 mmHg, frequência Cardíaca: 149 BPM. Petéquias em tornozelos e intensa dor à\npalpação abdominal difusa. Prova do laço positiva. Hemograma demonstrava hematócrito de 50% e\nplaquetopenia de 56.000/mm³. A principal hipótese diagnóstica e o tratamento imediato são:","options":{"A":"Leptospirose e hemodiálise.","B":"Febre hemorrágica da Dengue/ Síndrome do choque da Dengue e expansão volêmica\nintravenosa.","C":"Febre maculosa e antibioticoterapia específica.","D":"Meningococcemia e antibioticoterapia específica.","E":"Febre amarela e transfusão de plaquetas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81225","number":"81225","sourceNumber":"81225","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Sobre a Dengue, assinale a alternativa incorreta:","options":{"A":"Pacientes com manifestações hemorrágicas espontâneas ou prova do laço positiva, mesmo sem\nrepercussão hemodinâmica e sem sinais de alerta, independentemente dos valores do hematócrito\ne plaquetas, são classificados como pacientes graves e devem ser internados imediatamente.","B":"A infecção por um dos quatro sorotipos do vírus da dengue gera imunidade por toda a vida\ncontra este sorotipo.","C":"A grande marca de Febre Hemorrágica da Dengue não é a hemorragia, mas sim o aumento da\npermeabilidade vascular que leva ao extravasamento de plasma e que pode evoluir para o choque.","D":"Tanto os pacientes com dengue clássica como os com Febre Hemorrágica da Dengue\ncostumam apresentar leucopenia, trombocitopenia e aumento das aminotransferases.","E":"Em crianças, as formas graves da dengue surgem mais precocemente do que nos adultos, isto\né, por volta do 3° dia, acompanhadas ou não da defervescência da febre."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81182","number":"81182","sourceNumber":"81182","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"São sinais de choque na dengue:","options":{"A":"Dor abdominal intensa e contínua; vômitos persistentes e lipotimia.","B":"Hipotensão arterial, pressão arterial convergente (PA diferencial < 20 mmHg); extremidades\nfrias, cianose; pulso rápido e fino e enchimento\ncapilar lento (> 2 segundos).","C":"Hepatomegalia dolorosa e sonolência e/ou irritabilidade.","D":"Aumento repentino do hematócrito; queda abrupta de plaquetas.","E":"Febre, plaquetopenia, hiperviscosidade sanguínea."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81194","number":"81194","sourceNumber":"81194","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na dengue, com relação à prova do laço, podemos afirmar que:","options":{"A":"A prova do laço nem sempre deve ser realizada em todos os casos suspeitos de dengue durante\no exame físico.","B":"Deve-se desenhar um quadrado de 2,5 cm de lado (ou uma área ao redor da falange distal do\npolegar) no antebraço da pessoa e verificar a PA (deitada ou sentada).","C":"Deve-se calcular o valor médio: (PAS + PAD)/4.","D":"Deve-se insuflar novamente o manguito até o valor médio e manter por oito minutos na criança,\nou até o aparecimento de petéquias ou\nequimoses.","E":"Deve-se contar o número de petéquias no quadrado. A prova será positiva se houver 12\npetéquias em adultos e 3 em crianças."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81152","number":"81152","sourceNumber":"81152","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Assinale a alternativa correta, em relação à Dengue:","options":{"A":"A dengue na criança, na minoria das vezes, apresenta-se como uma síndrome febril com sinais\ne sintomas específicos: apatia, sonolência,\nrecusa da alimentação, vômitos, diarreia ou fezes\namolecidas.","B":"Nos menores de 2 anos de idade, especialmente em menores de 6 meses, os sintomas são:\ncefaleia, mialgias e artralgias.","C":"As formas graves sobrevêm geralmente em torno do terceiro dia de doença, acompanhadas ou\nnão da defervescência da febre.","D":"Na criança, o início da doença é evidente, e o quadro grave é identificado na primeira\nmanifestação clínica.","E":"O exantema, sempre presente, é da forma micropapular, apresenta-se sob todas as formas\n(pleomorfismo), com prurido precoce."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81110","number":"81110","sourceNumber":"81110","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Em relação à leptospirose, podemos afirmar que:","options":{"A":"É uma doença infecciosa afebril de início insidioso.","B":"Trata-se de uma zoonose de baixa importância social e econômica, por apresentar baixa\nincidência em determinadas áreas, alto custo hospitalar.","C":"Sua ocorrência está relacionada às precárias condições de infraestrutura sanitária e alta\ninfestação de morcegos infectados.","D":"São sinonímias da leptospirose: Doença de Weil, síndrome de Weil, febre dos pântanos, febre\ndos arrozais, febre outonal, doença dos\nporqueiros, tifo canino.","E":"Micobactéria anaeróbica obrigatória do gênero Leptospira, do qual se conhecem atualmente 12\nespécies patogênicas, sendo a mais importante a L. interrogans."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81129","number":"81129","sourceNumber":"81129","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Na Leishmaniose, pode-se afirmar que:","options":{"A":"A Leishmaniose Visceral (LV) era uma doença praticamente silvestre e, com o desmatamento,\nhouve mudança da disponibilidade de animais para\nservir de fonte de alimentação para o mosquito\ntransmissor, colocando o cão e o homem como alternativas mais acessíveis.","B":"É uma doença endêmica em grandes metrópoles.","C":"No Brasil, o calazar atinge preferencialmente os estados da região Sul do país, onde se\nconcentram mais de 90% dos casos humanos da doença.","D":"O flebótomo Lutzomyia longipalpis é a espécie mais conhecida como transmissora da\nLeishmania chagasi, mas recentemente\nregistrou-se a incriminação do Lutzomyia cruzi como vetor\nno Rio Grande do Sul.","E":"Os reservatórios silvestres da Leishmania chagasi, agente etiológico da LV, são morcegos e\nmarsupiais e, no ambiente doméstico, as aves."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-10-81191","number":"81191","sourceNumber":"81191","collectionBlock":"med:med-clinica-medica-med-clm-10","collectionLabel":"MED · MED CLM 10","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 10","subtopic":"","stem":"Pode ocorrer em casos de febre hemorrágica da dengue:","options":{"A":"febre ou história de febre recente de sete dias.","B":"trombocitopenia (<=100.000/mm³ ou menos) sem história de febre recente.","C":"prova do laço positiva, petéquias, equimoses ou púrpuras, sangramentos de mucosas do trato\ngastrintestinal e outros; Trombocitopenia.","D":"extravasamento de plasma devido à vasodilatação e hiperviscosidade.","E":"diminuição de hematócrito em 37% sobre o basal na admissão; presença de derrame pleural,\ntrombose venosa profunda e baqueteamento digital."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 10/MED CLM 10.txt","sourceLabel":"MED · MED CLM 10","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 10","MED"],"answerSource":"missing","commentDeferred":true}]};
